function consoleUserId(value) {
  return String(value == null ? "" : value).trim();
}

function selectedPersonaStorageKey(user = state.currentUser) {
  const workspaceUserId = consoleUserId(ADMIN_WORKSPACE_USER_ID || user?.id);
  return workspaceUserId ? `${SELECTED_PERSONA_STORAGE_KEY}:${workspaceUserId}` : "";
}

function storedSelectedPersonaId(user = state.currentUser) {
  const key = selectedPersonaStorageKey(user);
  if (!key) return "";
  try {
    return String(window.localStorage.getItem(key) || "").trim();
  } catch {
    return "";
  }
}

function setSelectedPersonaId(personaId, { persist = true } = {}) {
  const cleanId = String(personaId || "").trim();
  const changed = cleanId !== String(state.selectedPersonaId || "").trim();
  state.selectedPersonaId = cleanId;
  if (changed) {
    state.publishHistoryPreviewId = "";
  }
  if (!persist) return cleanId;
  const key = selectedPersonaStorageKey();
  if (!key) return cleanId;
  try {
    if (cleanId) window.localStorage.setItem(key, cleanId);
    else window.localStorage.removeItem(key);
  } catch {}
  if (cleanId && consoleIdentityReady) {
    queueMicrotask(() => restorePersonaPostGenerationTasks(cleanId));
  }
  return cleanId;
}

function maskConsoleForIdentityRevalidation() {
  // Keep the current layout mounted while /api/me is checked. Setting
  // `hidden` on <html> removes the whole document from layout, which makes
  // the browser clamp scrollY to 0 and produces a visible white flash.
  const root = document.documentElement;
  if (!root) return;
  if (root.dataset) root.dataset.consoleIdentityChecking = "true";
  else root.hidden = true;
}

function unmaskConsoleAfterIdentityRevalidation() {
  if (consoleBoundaryNavigationActive) return;
  const root = document.documentElement;
  if (!root) return;
  if (root.dataset) delete root.dataset.consoleIdentityChecking;
  else root.hidden = false;
}

