function clearStoredAdminWorkspaceContext() {
  try { window.sessionStorage.removeItem("vecto-admin-workspace-user-id"); } catch (_) {}
  try { window.sessionStorage.removeItem("vecto-admin-console-context"); } catch (_) {}
}

function handleSessionBoundary(status) {
  const normalizedStatus = Number(typeof status === "object" ? status?.status : status || 0);
  const boundaryCode = String(typeof status === "object" ? status?.code || "" : "").trim();
  if (![401, 428].includes(normalizedStatus)) return false;
  if (consoleBoundaryNavigationActive) return true;
  consoleBoundaryNavigationActive = true;
  clearTenantInMemoryState();
  const isAdminConsole = typeof ADMIN_CONSOLE_SESSION !== "undefined" && ADMIN_CONSOLE_SESSION;
  if (isAdminConsole) clearStoredAdminWorkspaceContext();
  const returnUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;
  const passwordTarget = isAdminConsole
    ? `/change-password.html?admin_console=1&return_url=${encodeURIComponent(returnUrl)}`
    : `/change-password.html?return_url=${encodeURIComponent(returnUrl)}`;
  const loginTarget = isAdminConsole
    ? `/admin?return_url=${encodeURIComponent(returnUrl)}`
    : `/?login=1&return_url=${encodeURIComponent(returnUrl)}`;
  const boundaryTarget = normalizedStatus === 428
    ? (isAdminConsole && boundaryCode === "mfa_setup_required" ? "/admin.html#admin-account" : passwordTarget)
    : loginTarget;
  window.location.replace(boundaryTarget);
  return true;
}

function reloadForIdentityChange() {
  if (consoleBoundaryNavigationActive) return;
  consoleBoundaryNavigationActive = true;
  clearTenantInMemoryState();
  window.location.reload();
}

function tenantArrayFallback(error, currentValue = []) {
  if (consoleBoundaryNavigationActive || error?.stale || [401, 428].includes(Number(error?.status || 0))) return [];
  return Array.isArray(currentValue) ? currentValue : [];
}

