function uniqueAccountOptions(accounts) {
  const seen = new Set();
  return (accounts || []).filter((account) => {
    const username = String(account.username || account.account_username || "").trim().toLowerCase();
    const key = [
      String(account.platform || ""),
      username || String(account.id || "").trim().toLowerCase(),
    ].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function accountOptionKey(account) {
  const username = String(account?.username || account?.account_username || "").trim().toLowerCase();
  return [
    String(account?.platform || "").trim().toLowerCase(),
    username || String(account?.id || "").trim().toLowerCase(),
  ].join("|");
}

function accountStatusRank(status) {
  const value = String(status || "").trim().toLowerCase();
  if (value === "ready") return 5;
  if (value === "account_confirmation_required") return 4;
  if (value === "need_verification") return 4;
  if (value === "pending_login") return 3;
  if (value === "cookie_expired") return 2;
  if (value === "transient_error") return 2;
  if (value === "disabled") return 1;
  return 0;
}

function mergedAccountCards(accounts) {
  const groups = new Map();
  (accounts || []).forEach((account) => {
    const key = accountOptionKey(account);
    if (!key || key === "|") return;
    const current = groups.get(key);
    if (!current) {
      groups.set(key, { ...account, binding_count: 1, account_ids: [account.id].filter(Boolean) });
      return;
    }
    current.binding_count += 1;
    if (account.id) current.account_ids.push(account.id);
    const currentScore = accountStatusRank(current.status);
    const nextScore = accountStatusRank(account.status);
    const currentTime = Number(current.updated_at || current.created_at || 0);
    const nextTime = Number(account.updated_at || account.created_at || 0);
    if (nextScore > currentScore || (nextScore === currentScore && nextTime > currentTime)) {
      groups.set(key, { ...account, binding_count: current.binding_count, account_ids: current.account_ids });
    }
  });
  return Array.from(groups.values());
}

function personaBindingLabel(persona) {
  const account = accountForPersona(persona);
  const handle = String(persona?.threads_account?.handle || "").trim();
  const profileName = String(account?.username || account?.account_username || "").trim();
  if (handle) return `Threads 主页 · ${handle}`;
  if (profileName) return `执行账号 · ${profileName}`;
  return "未绑定";
}

function personaExecutionAccountDetails(persona) {
  const account = accountForPersona(persona);
  const profileName = String(account?.username || account?.account_username || "").trim();
  const handle = String(persona?.threads_account?.handle || "").trim();
  const accountLabel = profileName || handle || "未绑定";
  const platform = String(account?.platform || (handle ? "threads" : "")).trim().toLowerCase();
  return {
    accountLabel,
    hasExecutionAccount: Boolean(account?.id || profileName || handle),
    platform,
    platformLabel: platform ? platformLabel(platform) : "",
  };
}

function personaExecutionAccountLabel(persona) {
  const { accountLabel, hasExecutionAccount, platformLabel: executionPlatform } = personaExecutionAccountDetails(persona);
  if (!hasExecutionAccount) return "未绑定执行账号";
  return executionPlatform ? `${executionPlatform} · ${accountLabel}` : accountLabel;
}

function renderPersonaExecutionAccountBadge(persona) {
  const fallbackDetails = personaExecutionAccountDetails(persona);
  const selectedPlatform = personaContentPlatform(persona);
  const accounts = personaAccounts(persona);
  const selectedAccount = accounts.find(
    (account) => String(account?.platform || "").trim().toLowerCase() === selectedPlatform,
  ) || null;
  const hasExecutionAccount = Boolean(selectedAccount?.id || (selectedPlatform === fallbackDetails.platform && fallbackDetails.hasExecutionAccount));
  const accountSyncPending = !state.socialDataLoadedAt && !hasExecutionAccount;
  const accountLabel = String(selectedAccount?.username || selectedAccount?.account_username || "").trim()
    || (accountSyncPending ? "账号同步中" : (selectedPlatform === fallbackDetails.platform ? fallbackDetails.accountLabel : "未绑定"));
  const platforms = accountPoolPlatforms.map(([platform]) => platform);
  const platformLogos = platforms.length
    ? `<span class="persona-execution-platform-logos" aria-label="已绑定平台">${platforms.map((item) => {
      const label = platformLabel(item);
      const isCurrent = item === selectedPlatform;
      return `<span class="persona-execution-platform-logo${isCurrent ? " is-current" : ""}"
                    data-persona-content-platform="${esc(item)}"
                    title="${esc(label)}"
                    aria-label="${esc(label)}">${renderAccountPoolPlatformIcon(item)}</span>`;
    }).join("")}</span>`
    : "";
  const statusClass = hasExecutionAccount ? "is-ready" : (accountSyncPending ? "is-loading" : "is-warning");
  return `<span class="persona-status-chip ${statusClass}">${platformLogos}<span>账号：${esc(accountLabel)}</span></span>`;
}

function personaAccountHomepageTarget(persona = selectedPersona()) {
  const platform = personaContentPlatform(persona);
  const account = personaAccounts(persona).find(
    (item) => String(item?.platform || "").trim().toLowerCase() === platform,
  ) || null;
  const username = String(account?.username || account?.account_username || account?.login_username || "")
    .trim()
    .replace(/^@+/, "");
  if (!username) return { account, platform, url: "" };
  const handle = encodeURIComponent(username);
  const url = platform === "instagram"
    ? `https://www.instagram.com/${handle}/`
    : `https://www.threads.com/@${handle}`;
  return { account, platform, url };
}

function personaAccountHomepageUrl(persona = selectedPersona()) {
  return personaAccountHomepageTarget(persona).url;
}

function openPersonaAccountHomepage() {
  const target = personaAccountHomepageTarget();
  if (!target.url) {
    showMsg("commandMsg", "当前平台尚未绑定可打开的账号。", false);
    return;
  }
  const mobile = isMobileNavMode();
  if (mobile && accountDisplayedStatus(target.account) !== "ready") {
    showMsg("commandMsg", "当前账号尚未确认登录，请先完成登录后再打开主页。", false);
    return;
  }
  if (mobile) {
    window.location.assign(target.url);
    return;
  }
  window.open(target.url, "_blank", "noopener,noreferrer");
}

function personaSummaryCounts(persona) {
  const personaId = String(persona?.id || "");
  const selectedPlatform = personaContentPlatform(persona);
  const allDrafts = visiblePersonaDraftPosts(state.personaDraftPosts[personaId] || []);
  const allFavorites = state.personaFavoritePosts[personaId] || [];
  const draftsLoaded = Array.isArray(state.personaDraftPosts[personaId]);
  const favoritesLoaded = Array.isArray(state.personaFavoritePosts[personaId]);
  const drafts = allDrafts.filter((post) => personaPostContentPlatform(post) === selectedPlatform);
  const favorites = allFavorites.filter((post) => personaPostContentPlatform(post) === selectedPlatform);
  const overviewDraftCount = personaOverviewDraftCount(persona);
  const overviewFavoriteCount = personaOverviewFavoriteCount(persona);
  return {
    draftCount: draftsLoaded ? drafts.length : (selectedPlatform === "threads" ? overviewDraftCount : 0),
    favoriteCount: favoritesLoaded ? favorites.length : (selectedPlatform === "threads" ? overviewFavoriteCount : 0),
    totalDraftCount: draftsLoaded ? allDrafts.length : overviewDraftCount,
    totalFavoriteCount: favoritesLoaded ? allFavorites.length : overviewFavoriteCount,
  };
}

function currentPersonaGroupStep(groupKey, profile) {
  const options = personaGroupStepOptions(groupKey, profile);
  const current = state.personaPanels[groupKey] || personaGroups[groupKey]?.defaultStep || options[0]?.[0] || "";
  if (options.some(([value]) => value === current)) return current;
  return options[0]?.[0] || "";
}

function normalizedPersonaGroupKey(groupKey = state.personaGroup || "settings") {
  return Object.prototype.hasOwnProperty.call(personaGroups, String(groupKey || "").trim()) ? String(groupKey || "").trim() : "settings";
}

function setPersonaGroupStep(groupKey, step, profile) {
  const next = currentPersonaGroupStep(groupKey, profile);
  if (!step) {
    state.personaPanels[groupKey] = next;
    return next;
  }
  const options = personaGroupStepOptions(groupKey, profile);
  state.personaPanels[groupKey] = options.some(([value]) => value === step) ? step : next;
  return state.personaPanels[groupKey];
}

function personaGroupStepLabel(groupKey, step, profile) {
  const pair = personaGroupStepOptions(groupKey, profile).find(([value]) => value === step);
  return pair ? pair[1] : "-";
}

function selectedPersonaAutomationPlatform() {
  const value = String($("personaAutoPlatform")?.value || state.personaAutomationPlatform || "threads").trim().toLowerCase();
  return value || "threads";
}

function personaAutomationAccounts(persona, platform = "") {
  return personaAccounts(persona, platform || selectedPersonaAutomationPlatform());
}

function personaAutomationPlatformOptions(persona) {
  const seen = new Set();
  const rows = [];
  const supported = new Set(["threads", "instagram"]);
  const push = (platform) => {
    const value = String(platform || "").trim().toLowerCase();
    if (!value || !supported.has(value) || seen.has(value)) return;
    seen.add(value);
    rows.push(value);
  };
  push("threads");
  push("instagram");
  personaAccounts(persona).forEach((account) => push(account.platform));
  state.socialAccounts.forEach((account) => push(account.platform));
  return rows;
}

function selectedPersonaAutomationAccount(persona, platform = selectedPersonaAutomationPlatform()) {
  const accounts = personaAutomationAccounts(persona, platform);
  const currentId = String($("personaAutoAccount")?.value || state.preferredAccountId || "").trim();
  if (currentId && accounts.some((item) => String(item.id) === currentId)) {
    return accounts.find((item) => String(item.id) === currentId) || null;
  }
  return accounts[0] || null;
}

