function personaAccountPoolCandidates(platform = "", currentPersona = selectedPersona()) {
  const normalizedPlatform = String(platform || "").trim().toLowerCase();
  const currentPersonaId = String(currentPersona?.id || "").trim();
  return (state.socialAccounts || []).filter((account) => (
    (!normalizedPlatform || String(account?.platform || "").trim().toLowerCase() === normalizedPlatform)
    && String(account?.persona_id || "").trim() !== currentPersonaId
  ));
}

function renderPersonaAccountBindingIcon(kind = "bind") {
  const mode = String(kind || "bind").trim().toLowerCase();
  if (mode === "remove") {
    return `<svg class="ui-action-icon persona-account-binding-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m18.8 12.3 1.7-1.7a5 5 0 0 0-7.1-7.1l-1.7 1.7"></path><path d="m5.2 11.7-1.7 1.7a5 5 0 0 0 7.1 7.1l1.7-1.7"></path><path d="M8 2v3M2 8h3M16 19v3M19 16h3"></path></svg>`;
  }
  if (mode === "current") {
    return `<svg class="ui-action-icon persona-account-binding-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="8.5"></circle><path d="m8.4 12.2 2.35 2.35 4.9-5.1"></path></svg>`;
  }
  if (mode === "replace") {
    return renderReplaceIcon("ui-action-icon persona-account-binding-icon");
  }
  if (mode === "add") return renderPlusIcon();
  return `<svg class="ui-action-icon persona-account-binding-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>`;
}

function personaAccountPickerTriggerDisplay({ selectedAccount = null, accounts = [] } = {}) {
  if (selectedAccount) {
    return { kind: "replace", label: "更换账号", title: "从账号池更换当前绑定账号", icon: renderPersonaAccountBindingIcon("replace") };
  }
  if (Array.isArray(accounts) && accounts.length) {
    return { kind: "bind", label: "绑定账号", title: "从账号池绑定账号", icon: renderPersonaAccountBindingIcon("bind") };
  }
  return { kind: "add", label: "添加账号", title: "从账号池添加账号", icon: renderPersonaAccountBindingIcon("add") };
}

function personaAccountBindingDisplay(account, currentPersona = selectedPersona()) {
  const boundPersonaId = String(account?.persona_id || "").trim();
  const currentPersonaId = String(currentPersona?.id || "").trim();
  const boundPersona = boundPersonaId
    ? state.personas.find((item) => String(item?.id || "") === boundPersonaId)
    : null;
  if (!boundPersonaId) {
    return { className: "is-available", label: "可选 · 未绑定人设", action: "绑定账号", actionKind: "bind" };
  }
  if (boundPersonaId === currentPersonaId) {
    return {
      className: "is-current",
      label: `已绑定人设：${currentPersona?.name || currentPersonaId}`,
      action: "已绑定",
      actionKind: "current",
    };
  }
  return {
    className: "is-bound",
    label: `已绑定人设：${boundPersona?.name || boundPersonaId} · 添加后替换`,
    action: "替换绑定",
    actionKind: "replace",
  };
}

function renderPersonaAccountPoolPickerCard(account, currentPersona = selectedPersona()) {
  const accountId = String(account?.id || "").trim();
  const binding = personaAccountBindingDisplay(account, currentPersona);
  return `<button type="button" class="persona-account-picker-card" data-persona-account-pool-select="${esc(accountId)}">
    ${renderAccountPoolCardFields(account, { includeContinueLogin: false })}
    <span class="persona-account-picker-card-meta"><span class="persona-account-picker-binding ${esc(binding.className)}">${esc(binding.label)}</span><span class="persona-account-picker-proxy">${esc(accountResidentialProxyLabel(account))}</span></span>
    <span class="persona-account-picker-card-action is-${esc(binding.actionKind)}">${renderPersonaAccountBindingIcon(binding.actionKind)}<span>${esc(binding.action)}</span></span>
  </button>`;
}

async function bindPoolAccountToPersona(accountId = "", persona = selectedPersona(), platform = "") {
  if (COLLECTOR_DEPLOYMENT) return false;
  if (state.accountPoolBinding) return false;
  const cleanAccountId = String(accountId || "").trim();
  const personaId = String(persona?.id || "").trim();
  const normalizedPlatform = String(platform || "").trim().toLowerCase();
  const previousAccount = selectedPersonaAutomationAccount(persona, normalizedPlatform);
  const account = personaAccountPoolCandidates(normalizedPlatform, persona)
    .find((item) => String(item?.id || "") === cleanAccountId);
  if (!personaId || !account) throw new Error("该账号不存在或平台不匹配，请刷新后重新选择。");
  state.accountPoolBinding = true;
  renderPersonaDetail();
  try {
    await api(`/api/persona_dashboard/automation/accounts/${encodeURIComponent(cleanAccountId)}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ persona_id: personaId, replace_existing_binding: true }),
    });
    state.preferredAccountId = cleanAccountId;
    await loadSocial({ force: true });
    renderPersonaDetail();
    renderConfirmSummary();
    showMsg(
      "commandMsg",
      previousAccount && String(previousAccount.id || "") !== cleanAccountId
        ? `当前人设已更换为账号：${accountDisplayName(account)}。`
        : `账号已绑定到当前人设：${accountDisplayName(account)}。`,
      true,
    );
    return true;
  } finally {
    state.accountPoolBinding = false;
    if (isPersonaWorkspaceModule()) renderPersonaDetail();
  }
}

async function openPersonaAccountPoolPickerModal(persona = selectedPersona(), platform = selectedPersonaAutomationPlatform(), motionTrigger = null) {
  const personaId = String(persona?.id || "").trim();
  const normalizedPlatform = String(platform || "").trim().toLowerCase() === "instagram" ? "instagram" : "threads";
  if (!personaId) {
    showMsg("commandMsg", "请先选择当前人设后再添加账号。", false);
    return false;
  }
  // The account pool is already present in the persona workspace. Open the
  // picker from that cache so the click is instant; refresh it in the
  // background instead of blocking the modal on the full social-data fan-out.
  void loadSocial({ render: false, force: true }).catch(() => {});
  const candidates = personaAccountPoolCandidates(normalizedPlatform, persona);
  const currentAccount = selectedPersonaAutomationAccount(persona, normalizedPlatform);
  const isReplacing = Boolean(currentAccount);
  const emptyMessage = isReplacing ? "请先在账号池添加其他账号后再更换。" : "请先在账号池添加可绑定账号。";
  const request = openConsoleModal({
    title: isReplacing ? "更换当前账号" : "从账号池绑定账号",
    contentHtml: `<div class="persona-account-picker">
      <p class="persona-account-picker-intro">${renderPersonaAccountBindingIcon(isReplacing ? "replace" : "bind")}<span>${isReplacing ? "选择账号后将替换当前人设的绑定账号。" : "选择账号后将绑定到当前人设。"}</span></p>
      <div class="persona-account-picker-list">${candidates.length ? candidates.map((item) => renderPersonaAccountPoolPickerCard(item, persona)).join("") : `<div class="empty-state persona-account-picker-empty-state">${renderPersonaAccountBindingIcon(isReplacing ? "replace" : "bind")}<strong>${isReplacing ? "暂无可更换账号" : "暂无可绑定账号"}</strong><span>${esc(emptyMessage)}</span></div>`}</div>
    </div>`,
    showCancel: false,
    showConfirm: false,
    modalKey: "persona-account-pool-picker",
  });
  startAccountPoolAddButtonMotion(motionTrigger);
  void request.finally(() => closeAccountPoolAddButtonMotion(motionTrigger)).catch(() => {});
  const modal = $("consoleModal");
  const dialog = modal?.querySelector(".console-modal-dialog");
  dialog?.classList.add("persona-account-picker-modal");
  modal?.addEventListener("click", (event) => {
    event.stopPropagation();
    const button = event.target.closest("[data-persona-account-pool-select]");
    if (!button) return;
    button.disabled = true;
    bindPoolAccountToPersona(button.dataset.personaAccountPoolSelect || "", persona, normalizedPlatform)
      .then((bound) => {
        if (bound) closeConsoleModal(true);
        else button.disabled = false;
      })
      .catch((error) => {
        button.disabled = false;
        showMsg("commandMsg", error?.detail || error?.message || "添加账号失败", false);
      });
  });
  void request.catch(() => {});
  return true;
}

function personaAutomationTasksFor(personaId, limit = 0) {
  const rows = socialTaskPresentationRows(state.socialTasks)
    .filter((item) => String(item.persona_id || "") === String(personaId || ""))
    .sort((left, right) => timeValue(right.updated_at || right.created_at || 0) - timeValue(left.updated_at || left.created_at || 0));
  return limit > 0 ? rows.slice(0, limit) : rows;
}

function aggregateSocialTaskBatch(tasks = []) {
  const rows = (Array.isArray(tasks) ? tasks : []).slice().sort((left, right) => {
    const leftPayload = socialTaskPayload(left);
    const rightPayload = socialTaskPayload(right);
    return Number(leftPayload.publish_sequence_index || 1) - Number(rightPayload.publish_sequence_index || 1)
      || timeValue(left.created_at || 0) - timeValue(right.created_at || 0);
  });
  if (rows.length <= 1) return rows[0] || {};
  const statuses = rows.map((task) => socialTaskPresentationStatus(task));
  const activeStatus = ["need_manual", "running", "preparing", "queued"]
    .find((status) => statuses.includes(status));
  const status = activeStatus
    || (statuses.includes("failed") ? "failed" : "")
    || (statuses.every((item) => item === "success") ? "success" : "")
    || (statuses.includes("cancelled") ? "cancelled" : statuses[statuses.length - 1]);
  const source = rows[0];
  const createdTimes = rows.map((task) => Number(task.created_at || 0)).filter(Boolean);
  return {
    ...source,
    status,
    created_at: createdTimes.length ? Math.min(...createdTimes) : Number(source.created_at || 0),
    updated_at: Math.max(...rows.map((task) => Number(task.updated_at || task.created_at || 0))),
    finished_at: activeStatus ? 0 : Math.max(...rows.map((task) => Number(task.finished_at || 0))),
    error: rows.find((task) => task.error)?.error || "",
    batch_task_count: rows.length,
    batch_task_ids: rows.map((task) => String(task.id || "")),
    batch_tasks: rows,
  };
}

function socialTaskPresentationRows(tasks = []) {
  const slots = [];
  const batches = new Map();
  (Array.isArray(tasks) ? tasks : []).forEach((task) => {
    const payload = socialTaskPayload(task);
    const batchId = String(payload.publish_batch_id || "").trim();
    if (String(task?.task_type || "").trim() !== "publish_post" || !batchId) {
      slots.push(task);
      return;
    }
    const key = `${String(task.persona_id || "")}:${String(task.account_id || "")}:${batchId}`;
    if (!batches.has(key)) {
      const batch = [];
      batches.set(key, batch);
      slots.push(batch);
    }
    batches.get(key).push(task);
  });
  return slots.map((item) => Array.isArray(item) ? aggregateSocialTaskBatch(item) : item);
}

function paginateTaskQueueRows(rows, page = 1, pageSize = 1) {
  const cleanPageSize = Math.max(1, Number(pageSize || 1));
  const totalItems = Array.isArray(rows) ? rows.length : 0;
  const totalPages = Math.max(1, Math.ceil(totalItems / cleanPageSize));
  const currentPage = Math.min(Math.max(Number(page || 1), 1), totalPages);
  const start = (currentPage - 1) * cleanPageSize;
  return {
    items: (rows || []).slice(start, start + cleanPageSize),
    page: currentPage,
    pageSize: cleanPageSize,
    totalItems,
    totalPages,
  };
}

