function renderTaskQueueView() {
  const persona = selectedPersona();
  const personaPageSize = Math.min(Math.max(Number(state.taskQueuePersonaPageSize || 12), 1), 100);
  const regularPageSize = Math.min(Math.max(Number(state.taskQueueRegularPageSize || 20), 1), 100);
  const personaSourceRows = persona ? personaAutomationTasksFor(persona.id) : [];
  const personaRows = filterTaskQueuePersonaRows(personaSourceRows);
  const regularRows = Array.isArray(state.tasks) ? state.tasks : [];
  const personaPageInfo = isMobileTweetStreamMode()
    ? mobileTweetStreamInfo(personaRows, `task-queue:persona:${String(persona?.id || "none")}:${String(state.taskQueuePersonaTypeFilter || "all")}`, personaPageSize)
    : paginateTaskQueueRows(personaRows, state.taskQueuePersonaPage, personaPageSize);
  if (!personaPageInfo.mobile) state.taskQueuePersonaPage = personaPageInfo.page;
  const personaTasks = personaPageInfo.items;
  const regularPageInfo = isMobileTweetStreamMode()
    ? mobileTweetStreamInfo(regularRows, "task-queue:regular", regularPageSize)
    : paginateTaskQueueRows(regularRows, state.taskQueueRegularPage, regularPageSize);
  if (!regularPageInfo.mobile) state.taskQueueRegularPage = regularPageInfo.page;
  const regularTasksHtml = regularPageInfo.totalItems ? regularPageInfo.items.map((task) => `
    <article class="compact-row task-row" data-task-queue-row-id="${esc(task.id)}" tabindex="-1">
      <label class="task-queue-check-label task-queue-row-check">
        <input type="checkbox" data-task-queue-select="regular:${esc(task.id)}" ${state.taskQueueSelectedRegularIds.has(String(task.id || "")) ? "checked" : ""} />
        <span class="sr-only">选择</span>
      </label>
      <div data-mobile-label="任务"><strong>${esc(task.workflow_name || task.type || "任务")}</strong><span>${esc(task.id)}</span></div>
      <div data-mobile-label="创建时间">${esc(formatTime(task.created_at))}</div>
      <div data-mobile-label="状态">${renderStatusText(task.status || "")}</div>
      <div class="row-actions" data-mobile-label="操作">
        <button type="button" data-detail="${esc(task.id)}">详情</button>
        ${task.has_download ? `<a href="${esc(adminWorkspaceUrl(`/api/tasks/${encodeURIComponent(task.id)}/download`))}">下载</a>` : ""}
        ${task.status === "failed" ? `<button type="button" data-retry="${esc(task.id)}">重试</button>` : ""}
        ${activeSocialAutomationTask(task) ? `<button type="button" class="danger" data-cancel-task="${esc(task.id)}">停止</button>` : ""}
        <button type="button" class="danger task-queue-delete-button unified-action-icon-button" data-delete-task="${esc(task.id)}" title="删除" aria-label="删除">${renderTrashIcon()}</button>
      </div>
    </article>
  `).join("") : renderModuleEmptyState({
    icon: "task",
    title: "当前还没有通用任务",
    detail: "任务开始执行后会显示在这里",
  });
  const currentPanel = state.taskQueuePanel === "regular" ? "regular" : "persona";
  const panel = currentPanel === "regular"
    ? {
      title: "通用任务队列",
      description: "这里继续保留原有的 Web 任务列表，用于查看详情、下载、重试和停止。",
      actions: `<div class="task-queue-actionbar">${renderTaskQueueBulkControls("regular")}</div>`,
      extraActions: "",
      body: `<div class="task-table-inner task-table-inner--regular">
        <div class="task-table-head"><span>勾选</span><span>任务</span><span>创建时间</span><span>状态</span><span>操作</span></div>
        ${regularTasksHtml}
      </div>`,
      pager: regularPageInfo.mobile
        ? renderMobileTweetStreamFooter(regularPageInfo, "task-queue")
        : renderTaskQueuePager("regular", regularPageInfo),
    }
    : {
      title: "当前人设自动化队列",
      description: persona ? `这里统一查看「${persona.name || persona.id}」的浏览器自动化任务，不再单独放在人设页签里。` : "先在右侧点选一个人设，这里会同步显示对应自动化队列。",
      extraActions: `
        ${persona ? renderTaskQueuePersonaTypeFilter(personaSourceRows) : ""}
        <button type="button" class="persona-mobile-list-toggle task-queue-persona-select-button" data-persona-mobile-list-toggle="taskQueuePersonaSidebar" aria-controls="taskQueuePersonaSidebar" aria-expanded="false" title="选择人设" aria-label="选择人设">
          <svg class="ui-action-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <path d="M4 5h16"></path><path d="M4 12h16"></path><path d="M4 19h16"></path>
          </svg>
        </button>`,
      actions: `
        <div class="task-queue-actionbar">
          ${renderTaskQueueBulkControls("persona")}
          ${persona ? `<button type="button" class="danger unified-action-icon-button" data-task-clear-persona-queue="${esc(persona.id)}" title="清空当前人设队列" aria-label="清空当前人设队列">${renderQueueClearIcon()}</button>` : ""}
        </div>`,
      body: persona
        ? (
          personaTasks.length
            ? `<div class="compact-list task-persona-queue-list">
                <div class="task-table-head task-table-head--persona"><span>勾选</span><span>任务</span><span>平台</span><span>账号</span><span>时间</span><span>状态</span><span>操作</span></div>
                ${renderPersonaQueueRows(personaTasks)}
              </div>`
            : renderModuleEmptyState({
              icon: "task",
              title: "当前人设暂无自动化任务",
              detail: "创建任务后可在这里查看执行状态",
            })
        )
        : renderModuleEmptyState({
          icon: "persona",
          title: "当前还没有选中的人设",
          detail: "选择一个人设后可查看它的自动化任务",
        }),
      pager: personaPageInfo.mobile
        ? renderMobileTweetStreamFooter(personaPageInfo, "task-queue")
        : renderTaskQueuePager("persona", personaPageInfo),
    };
  return `
    <div class="task-queue-layout">
      <div class="persona-step-shell task-queue-shell">
        ${renderTaskQueuePanelTabs(currentPanel)}
        <section class="task-panel-section task-panel-section--shared">
          <div class="task-panel-section-head ${panel.extraActions ? "task-panel-section-head--with-action" : ""}">
            <div>
              <strong>${panel.title}</strong>
              <p>${esc(panel.description)}</p>
            </div>
            ${panel.extraActions ? `<div class="task-panel-section-heading-actions">${panel.extraActions}</div>` : (panel.actions ? `<div class="task-panel-section-controls">${panel.actions}</div>` : "")}
          </div>
          ${panel.extraActions && panel.actions ? `<div class="task-panel-section-actions">${panel.actions}</div>` : ""}
          ${panel.body}
          <div class="task-panel-section-foot">${panel.pager}</div>
        </section>
      </div>
      ${renderTaskQueuePersonaSelector()}
    </div>`;
}

function renderTaskQueueSurface() {
  const host = $("taskTable");
  if (!host) return;
  const reopenPersonaSidebar = Boolean(
    document.getElementById("taskQueuePersonaSidebar")?.classList.contains("is-mobile-open")
  );
  host.innerHTML = renderTaskQueueView();
  if (state.view === "tasks") {
    setPersonaMobileSidebarOpen(reopenPersonaSidebar, "taskQueuePersonaSidebar");
  }
  bindMobileTweetStreamObservers();
}

