const PUBLISH_SELECTION_LONG_PRESS_MS = 520;

function setPublishMobileSelectionExpanded(dock, expanded) {
  if (!dock) return;
  const nextExpanded = Boolean(expanded && isMobileNavMode());
  const trigger = dock.querySelector("#executeSimpleFlow");
  const strip = dock.querySelector(".publish-mobile-selection-strip");
  const clear = dock.querySelector("#clearPublishMobileSelectionEdit");
  const cancel = dock.querySelector("#cancelPublishMobileSelectionEdit");
  state.publishMobileSelectionExpanded = nextExpanded;
  dock.classList.toggle("is-selection-expanded", nextExpanded);
  trigger?.setAttribute("aria-expanded", nextExpanded ? "true" : "false");
  strip?.setAttribute("aria-hidden", nextExpanded ? "false" : "true");
  clear?.setAttribute("aria-hidden", nextExpanded ? "false" : "true");
  cancel?.setAttribute("aria-hidden", nextExpanded ? "false" : "true");
}

async function preflightSimpleFlowExecution(moduleId = state.activeModule) {
  if (moduleId !== "publishing") return {};
  const publishMode = normalizedPublishMode($("simplePublishMode")?.value || state.simpleBranches.publishing);
  if (publishMode !== "publish_now") return {};
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return false;
  }
  const account = await choosePublishPlatformAccount(persona);
  if (!account) return false;
  if (!canSubmitPublishWithAccount(account)) {
    showMsg("commandMsg", publishAccountBlockMessage(account), false);
    return false;
  }
  if (publishAccountRequiresExecutionConfirmation(account)) {
    if (!(await promptPersonaAccountBinding(persona, account))) return false;
    return { confirmedPublishAccountId: String(account.id || "").trim() };
  }
  return {};
}

function bindPublishMobileSelectionLongPress() {
  const trigger = $("executeSimpleFlow");
  const dock = trigger?.closest(".publish-command-actions");
  const strip = dock?.querySelector(".publish-mobile-selection-strip");
  if (!trigger || !dock || !strip) return;
  let timer = 0;
  let startX = 0;
  let startY = 0;
  const cancelPending = () => {
    if (timer) window.clearTimeout(timer);
    timer = 0;
  };
  trigger.addEventListener("pointerdown", (event) => {
    if (!isMobileNavMode() || trigger.disabled || event.isPrimary === false) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    cancelPending();
    startX = Number(event.clientX || 0);
    startY = Number(event.clientY || 0);
    timer = window.setTimeout(() => {
      timer = 0;
      trigger.dataset.publishSelectionLongPress = "true";
      setPublishMobileSelectionExpanded(dock, true);
    }, PUBLISH_SELECTION_LONG_PRESS_MS);
  });
  trigger.addEventListener("pointermove", (event) => {
    if (!timer) return;
    const distance = Math.hypot(Number(event.clientX || 0) - startX, Number(event.clientY || 0) - startY);
    if (distance > 10) cancelPending();
  });
  trigger.addEventListener("pointerup", () => {
    cancelPending();
    if (trigger.dataset.publishSelectionLongPress === "true") {
      window.setTimeout(() => delete trigger.dataset.publishSelectionLongPress, 700);
    }
  });
  trigger.addEventListener("pointercancel", () => {
    cancelPending();
    delete trigger.dataset.publishSelectionLongPress;
  });
  trigger.addEventListener("contextmenu", (event) => {
    if (isMobileNavMode()) event.preventDefault();
  });
}

function publishHistoryRecordTitle(record, index = 0) {
  return String(
    record?.title
    || statusLabel(record?.automation_task_type || record?.task_type || record?.taskType || "")
    || record?.platform
    || `第 ${index + 1} 条任务记录`
  ).trim();
}

function publishHistoryRecordTime(record) {
  return record?.published_at || record?.finished_at || record?.captured_at || record?.updated_at || record?.created_at || "";
}

function activePublishHistoryRecord(rows = []) {
  const list = Array.isArray(rows) ? rows : [];
  if (!list.length) {
    state.publishHistoryPreviewId = "";
    return null;
  }
  const active = list.find((record) => String(record.id || "") === String(state.publishHistoryPreviewId || "")) || list[0];
  state.publishHistoryPreviewId = String(active.id || "");
  return active;
}

function publishHistoryMetricEntries(record = {}) {
  const source = record?.hot_metrics || record || {};
  const interactions = [source.likes, source.comments, source.shares, source.reposts]
    .reduce((total, value) => total + Math.max(0, Number(value || 0)), 0);
  const viewUnavailable = source.views_available === false
    || source.views === null
    || source.views === undefined
    || (Number(source.views || 0) === 0 && interactions > 0);
  const views = viewUnavailable
    ? null
    : source.views;
  return [
    ["浏览", views],
    ["点赞", source.likes],
    ["评论", source.comments],
    ["分享", source.shares],
    ["转发", source.reposts],
  ];
}

function formatPublishHistoryMetricUnit(number, divisor, suffix) {
  const scaled = Number(number || 0) / divisor;
  const rounded = Math.round(scaled * 10) / 10;
  return `${Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1)}${suffix}`;
}

function publishHistoryMetricText(value) {
  if (value === null || value === undefined || value === "") return "—";
  if (typeof value === "string") return "—";
  const number = Number(value || 0);
  if (!Number.isFinite(number)) return "—";
  const absolute = Math.abs(number);
  if (absolute >= 100000000) return formatPublishHistoryMetricUnit(number, 100000000, "亿");
  if (absolute >= 1000000) return formatPublishHistoryMetricUnit(number, 1000000, "m");
  if (absolute >= 10000) return formatPublishHistoryMetricUnit(number, 10000, "w");
  if (absolute >= 1000) return formatPublishHistoryMetricUnit(number, 1000, "k");
  return number.toLocaleString("zh-CN");
}

function renderPublishHistoryMetrics(record = {}, className = "") {
  return `
    <div class="publish-history-metrics ${esc(className)}">
      ${publishHistoryMetricEntries(record).map(([label, value]) => `
        <span title="${esc(`${label}：${typeof value === "string" ? value : (value === null ? "—" : Number(value || 0).toLocaleString("zh-CN"))}`)}">
          <small>${esc(label)}</small>
          <strong>${esc(publishHistoryMetricText(value))}</strong>
        </span>
      `).join("")}
    </div>`;
}

function publishHistoryAccountWarning(record = {}) {
  const match = record?.account_match || {};
  const warning = String(match.warning || "").trim();
  return match.matches_current === false && warning ? warning : "";
}

function renderPublishHistoryAccountWarning(record = {}) {
  const warning = publishHistoryAccountWarning(record);
  return warning ? `<div class="publish-history-account-warning">${esc(warning)}</div>` : "";
}

