function renderConfirmSummary() {
  const module = currentModule();
  let rows = [["当前入口", module.label]];
  if (isPersonaWorkspaceModule()) {
    const persona = selectedPersona();
    const groupKey = state.personaGroup || "content";
    const profile = selectedPersonaProfile();
    const step = currentPersonaGroupStep(groupKey, profile);
    const finalAction = {
      generate: "提交人设草稿生成任务",
      media: "生成媒体或更新当前草稿媒体",
      overview: "查看当前人设资料",
      posts: "新建或选择推文草稿",
      login: "保存凭证或提交登录任务",
      reply_comment: "提交 Threads 评论回复任务",
      reply_hot: "提交 Threads 热点回复任务",
      warmup: "提交 Threads 养号任务",
    }[step] || "显示当前步骤的参数面板";
    rows = rows.concat([
      ["当前人设", persona ? persona.name : "未选择"],
      ["当前步骤", personaGroupStepLabel(groupKey, step, profile)],
      ["最终动作", finalAction],
    ]);
  } else if (state.activeModule === "publishing" || state.activeModule === "automation") {
    const persona = state.personas.find((item) => String(item.id) === String($("simplePersona")?.value || state.selectedPersonaId)) || selectedPersona();
    const automationStep = currentBranch("automation");
    const account = state.activeModule === "publishing"
      ? publishAccountForPersona(persona)
      : selectedPersonaAutomationAccount(persona, selectedPersonaAutomationPlatform());
    rows = rows.concat([
      [state.activeModule === "publishing" ? "任务方式" : "当前操作", state.activeModule === "publishing" ? publishModeLabel($("simplePublishMode")?.value || state.simpleBranches.publishing) : personaGroupStepLabel("account", automationStep, selectedPersonaProfile())],
      ...(state.activeModule === "automation" ? [["当前人设", persona ? persona.name : "未选择"]] : []),
      [state.activeModule === "publishing" ? "执行账号" : "账号", account ? String(account.username || account.id) : "未选择"],
      ["最终动作", state.activeModule === "publishing" ? "提交任务" : "在统一自动化面板执行"],
    ]);
  } else {
    rows = rows.concat([
      ["队列筛选", $("simplePrimary")?.selectedOptions?.[0]?.textContent || "-"],
      ["最终动作", "打开任务队列并执行取消或重试"],
    ]);
  }
  const host = $("confirmSummary");
  if (!host) return;
  host.innerHTML = rows.map(([label, value]) => `
    <div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>
  `).join("");
}


function appendEvent(kind, message, options = {}) {
  const localized = localizeConsoleMessage(message || "");
  if (!localized) return;
  const eventKind = String(kind || "info").trim() || "info";
  const host = $("eventStream");
  if (host) host.replaceChildren();
  const ok = !["error", "failed", "warn", "warning"].includes(eventKind);
  showToast(`${eventKindLabel(eventKind)}：${localized}`, ok, {
    key: options.key || (options.taskId ? `task:${options.taskId}` : `event:${eventKind}:${localized}`),
    kind: eventKind,
    taskId: options.taskId,
    taskPanel: options.taskPanel,
    personaId: options.personaId,
    openDetail: options.openDetail,
    target: options.target,
  });
}

function syncWatchingTaskChip(taskId = "") {
  const chip = $("watchingTask");
  if (!chip) return;
  const cleanId = String(taskId || "").trim();
  if (!cleanId) {
    chip.textContent = "";
    chip.hidden = true;
    return;
  }
  chip.textContent = `监听中 ${cleanId.slice(0, 8)}`;
  chip.hidden = false;
}

async function syncTaskBillingToast(taskId, message, options = {}, payload = {}) {
  let detail = payload;
  try {
    detail = await api(`/api/tasks/${encodeURIComponent(taskId)}`);
  } catch {}
  appendEvent("success", withBillingChargeMessage(message, detail), {
    key: `task:${taskId}`,
    taskId,
    taskPanel: options.taskPanel || "regular",
  });
  return detail;
}

function watchTask(taskId, options = {}) {
  if (state.events) state.events.close();
  const suppressDisconnectWarning = Boolean(options.suppressDisconnectWarning);
  const onDone = typeof options.onDone === "function" ? options.onDone : null;
  const onError = typeof options.onError === "function" ? options.onError : null;
  syncWatchingTaskChip(taskId);
  const source = new EventSource(adminWorkspaceUrl(`/api/tasks/${encodeURIComponent(taskId)}/events`), { withCredentials: true });
  let settled = false;
  const closeWatcher = () => {
    source.close();
    if (state.events !== source) return;
    state.events = null;
    syncWatchingTaskChip("");
  };
  const settleTask = (payload, status) => {
    if (settled) return;
    settled = true;
    closeWatcher();
    if (onDone) onDone({ ...payload, status });
    loadTasks();
  };
  state.events = source;
  const handleTaskEvent = (event) => {
    let payload = {};
    try { payload = JSON.parse(event.data || "{}"); } catch {}
    const kind = String(payload.kind || payload.status || "progress");
    const dataStatus = String(payload?.data?.status || "").trim();
    const terminalStatus = ["success", "failed", "cancelled"].includes(dataStatus) ? dataStatus : "";
    const eventKind = terminalStatus || kind;
    const taskError = eventKind === "failed"
      ? String(payload?.data?.error || payload?.error || "").trim()
      : "";
    const eventMessage = taskError || payload.message || payload.detail || eventKind;
    const toastOptions = {
      key: `task:${taskId}`,
      taskId,
      taskPanel: options.taskPanel || "regular",
    };
    if (eventKind === "success") {
      syncTaskBillingToast(taskId, eventMessage, options, payload).catch(() => {
        appendEvent("success", eventMessage, toastOptions);
      });
    } else {
      appendEvent(eventKind, eventMessage, toastOptions);
    }
    if (["success", "failed", "cancelled"].includes(eventKind)) {
      settleTask(payload, eventKind);
    }
  };
  source.onmessage = handleTaskEvent;
  ["queued", "running", "progress", "log", "done", "analysis", "warning"].forEach((eventName) => {
    source.addEventListener(eventName, handleTaskEvent);
  });
  source.onerror = async () => {
    if (settled || state.events !== source) {
      source.close();
      return;
    }
    source.close();
    try {
      const task = await api(`/api/tasks/${encodeURIComponent(taskId)}`);
      const taskStatus = String(task?.status || "").trim();
      if (["success", "failed", "cancelled"].includes(taskStatus)) {
        const taskError = taskStatus === "failed" ? String(task?.error || task?.detail || "").trim() : "";
        const terminalMessage = taskError || task?.message || `任务已${taskStatus === "success" ? "完成" : "结束"}。`;
        appendEvent(taskStatus, taskStatus === "success" ? withBillingChargeMessage(terminalMessage, task) : terminalMessage, {
          key: `task:${taskId}`,
          taskId,
          taskPanel: options.taskPanel || "regular",
        });
        settleTask({ kind: "done", data: task }, taskStatus);
        return;
      }
    } catch {}
    if (settled || state.events !== source) return;
    if (!suppressDisconnectWarning) appendEvent("warn", "事件流已断开，可在任务队列继续查看结果。");
    closeWatcher();
    if (onError) onError();
  };
}

async function openInstagramMediaGenerationPage(options = null) {
  const { persona = selectedPersona(), source = "posts", post = {} } = options || {};
  if (!persona || !post) return false;
  let targetSource = source === "favorites" ? "favorites" : "posts";
  let targetPost = post;
  if (targetSource === "favorites") {
    const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: String(post.title || "").trim(),
        content: publishContentForPost(post, persona),
        media_paths: [],
      }),
    });
    await loadPersonaDraftPosts(persona.id, { force: true });
    targetSource = "posts";
    targetPost = personaDraftPosts(persona).find((item) => String(item.id) === String(result?.id || "")) || personaDraftPosts(persona)[0] || null;
    if (!targetPost) {
      showMsg("commandMsg", "未能创建用于 AI 配图的草稿，请稍后重试。", false);
      return false;
    }
  }
  setSelectedPersonaId(persona.id);
  setPersonaPostSource(targetSource, persona);
  setSelectedPersonaPostId(targetPost.id || "");
  const form = personaFormState(persona.id);
  form.generate.composeMode = "tweet_media";
  form.media.contentMode = "draft";
  form.media.operationMode = "generate";
  setWorkspaceModule("tweet_generation");
  openPersonaDraftEditor(targetPost.id);
  return true;
}

async function requestInstagramPublishMediaResolution(options = null) {
  const { persona = selectedPersona(), source = "posts", post = {} } = options || {};
  if (state.simpleFlowPendingModule === "publishing") {
    state.simpleFlowPending = false;
    state.simpleFlowPendingModule = "";
    state.simpleFlowPendingStartedAt = 0;
    if (state.activeModule === "publishing") renderSimpleFlowModule("publishing");
  }
  const shouldNavigate = await openConsoleModal({
    title: "Instagram 发布需要媒体",
    message: "当前内容缺少图片或视频，是否前往生成页面补充媒体？",
    cancelText: "暂不处理",
    confirmText: "跳转生成页面",
    modalKey: "instagram-media-required",
  });
  if (!shouldNavigate) return false;
  return openInstagramMediaGenerationPage({ persona, source, post });
}

async function submitPersonaPublishTask() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const post = selectedPersonaPost(persona);
  if (!post) {
    showMsg("commandMsg", "请先创建并选中一条推文。", false);
    return;
  }
  const source = personaPostSource(persona);
  const sourceLabel = source === "favorites" ? "收藏推文" : "草稿";
  const account = selectedPublishAccountForPersona(persona);
  if (!account) {
    await promptPersonaAccountBinding(persona);
    return;
  }
  if (publishAccountRequiresExecutionConfirmation(account) && !(await promptPersonaAccountBinding(persona, account))) return;
  const lockParts = ["publish", source, persona.id, post.id, account.id];
  if (isActionLocked(...lockParts) || activeSocialTaskFor({ accountId: account.id, personaId: persona.id, taskType: "publish_post", postId: post.id, postSource: source })) {
    showMsg("commandMsg", `当前${sourceLabel}已有任务在队列或执行中，请等待完成后再重复提交。`, false);
    return;
  }
  const platform = String(account.platform || "instagram").trim().toLowerCase() || "instagram";
  const publishUploadState = captureUploadDropzoneState("personaPublishFiles");
  const publishFiles = publishUploadState.files;
  const readyPost = await ensurePersonaHotImportMediaReady(persona, post);
  const postMediaItems = personaPublishPostMediaItems(String(persona.id || ""), readyPost);
  if (platform === "instagram" && !publishFiles.length && !postMediaItems.length) {
    await requestInstagramPublishMediaResolution({ persona, source, post });
    return;
  }
  if (!(await ensureDailyPublishCapacity(1, { accountId: account.id, platform }))) return;
  setActionLocked(lockParts, true);
  renderPersonaDetail();
  try {
    const mediaPaths = await uploadAutomationMedia(publishFiles, "commandMsg");
    if (platform === "instagram" && !mediaPaths.length && !postMediaItems.length) {
      showMsg("commandMsg", "媒体上传失败，请重新选择文件。", false);
      return;
    }
    showMsg("commandMsg", `正在提交 ${publishPlatformLabel(account)} 任务到浏览器执行队列...`, true);
    const postSourcePath = source === "favorites" ? "favorites" : "posts";
    const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/${postSourcePath}/${encodeURIComponent(post.id)}/publish`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        account_id: account.id,
        platform,
        media_paths: mediaPaths,
        priority: 50,
        max_retries: 0,
      }),
    });
    const task = result.task || {};
    const taskId = String(task.id || "").trim();
    const waitingForSchedule = isFutureScheduledSocialTask(task);
    clearUploadDropzoneState("personaPublishFiles", publishUploadState.stateKey);
    mergeSocialTaskState(result.login_task, task);
    state.personaPublishResults[String(persona.id)] = renderPersonaPublishResult(task, []);
    updatePersonaPublishResultView(persona.id);
    if (taskId) {
      registerSocialTaskToastBatch(socialTaskToastLaneKey(task), [task]);
      syncSocialTaskToast(task, { force: true });
      if (!waitingForSchedule) refreshLiveBrowserSessionsSoon(taskId, 40, 500);
    }
    if (taskId && !waitingForSchedule) watchPersonaPublishTask(taskId, persona.id).catch((error) => {
      state.personaPublishResults[String(persona.id)] = `<div class="persona-warning-inline">${esc(error?.detail || error?.message || "任务结果轮询失败")}</div>`;
      updatePersonaPublishResultView(persona.id);
    });
    await loadSocial();
    if (taskId && !waitingForSchedule && !deferMobilePublishingBrowserView(taskId)) {
      bindPublishAssistanceContext({ accountId: account.id, personaId: persona.id });
      openPublishAssistanceView(taskId, { accountId: account.id, personaId: persona.id });
    }
  } finally {
    setActionLocked(lockParts, false);
    if (isPersonaWorkspaceModule()) renderPersonaDetail();
  }
}

async function submitPublishContentTasks(accountId = "", persona = selectedPersona(), messageId = "commandMsg", { confirmedPublishAccountId = "" } = {}) {
  const source = normalizePublishContentSource();
  if (source === "custom") {
    return createSocialTask("publish_post", accountId, persona?.id || "", messageId);
  }
  if (!persona) {
    showMsg(messageId, "请先选择一个人设。", false);
    return null;
  }
  const account = publishAccountForPersona(persona);
  const cleanAccountId = String(accountId || account?.id || "").trim();
  if (!cleanAccountId || !account) {
    await promptPersonaAccountBinding(persona);
    return null;
  }
  if (
    publishAccountRequiresExecutionConfirmation(account)
    && String(account.id || "").trim() !== String(confirmedPublishAccountId || "").trim()
    && !(await promptPersonaAccountBinding(persona, account))
  ) return null;
  const rows = publishSourceRows(persona, source);
  const selectedIds = syncPublishSelectedPostIds(persona, source, rows);
  const selectedInSourceOrder = rows.map((post) => String(post.id || "")).filter((id) => selectedIds.includes(id));
  const posts = rows.filter((post) => selectedInSourceOrder.includes(String(post.id || "")));
  if (!posts.length) {
    showMsg(messageId, `请先选择要执行的${publishContentSourceLabel(source)}。`, false);
    return null;
  }
  const platform = String(account.platform || "threads").trim().toLowerCase() || "threads";
  const batchLimit = publishBatchLimit(platform);
  if (posts.length > batchLimit) {
    await showPublishBatchLimitWarning(platform, batchLimit);
    return null;
  }
  const publishFiles = filesFromInput("simpleMediaFiles");
  if (platform === "instagram" && !publishFiles.length) {
    const missingMedia = posts.find((post) => !personaPublishPostMediaItems(String(persona.id || ""), post).length);
    if (missingMedia) {
      await requestInstagramPublishMediaResolution({ persona, source, post: missingMedia });
      return null;
    }
  }
  if (!(await ensureDailyPublishCapacity(posts.length, { accountId: cleanAccountId, platform }))) return null;
  const lockParts = ["publish_content", source, persona.id, cleanAccountId, selectedInSourceOrder.join("_"), "now"];
  const batchToastKey = socialTaskToastLaneKey({
    task_type: "publish_post",
    persona_id: persona.id,
    account_id: cleanAccountId,
  });
  if (isActionLocked(...lockParts)) {
    showMsg(messageId, "当前任务正在提交，请等待当前操作完成。", false);
    return null;
  }
  for (const post of posts) {
    if (activeSocialTaskFor({ accountId: cleanAccountId, personaId: persona.id, taskType: "publish_post", postId: post.id, postSource: source })) {
    showMsg(messageId, `已选${publishContentSourceLabel(source)}中存在正在队列或执行中的任务，请等待完成后再提交。`, false);
      return null;
    }
  }
  setActionLocked(lockParts, true);
  try {
    const mediaPaths = await uploadAutomationMedia(publishFiles, messageId);
    if (platform === "instagram") {
      const missingMedia = posts.find((post) => !mediaPaths.length && !personaPublishPostMediaItems(String(persona.id || ""), post).length);
      if (missingMedia) {
        showMsg(messageId, "媒体上传失败，请重新选择文件。", false);
        return null;
      }
    }
    const postSourcePath = source === "favorites" ? "favorites" : "posts";
    const isBatchPublish = posts.length > 1;
    const publishBatchId = isBatchPublish ? `publish_batch_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}` : "";
    const publishSequenceTargets = posts.map((_, index) => `发布第${index + 1}篇`);
    showMsg(messageId, `正在提交 ${posts.length} 条${publishContentSourceLabel(source)}任务...`, true, {
      key: batchToastKey,
      kind: "queued",
    });
    const submissions = posts.map((post, index) => {
      const sequenceMetadata = isBatchPublish ? {
        publish_batch_id: publishBatchId,
        publish_sequence_index: index + 1,
        publish_sequence_total: posts.length,
        publish_sequence_targets: publishSequenceTargets,
      } : {};
      const publishPath = `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/${postSourcePath}/${encodeURIComponent(post.id)}/publish`;
      const publishOptions = {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          account_id: cleanAccountId,
          platform,
          content_override: publishContentForPost(post, persona),
          media_paths: mediaPaths,
          priority: 50,
          max_retries: isBatchPublish ? 2 : 0,
          ...sequenceMetadata,
        }),
      };
      return api(publishPath, publishOptions)
        .catch(() => api(publishPath, publishOptions))
        .then((result) => ({ index, result, sequenceMetadata }));
    });
    const settledSubmissions = await Promise.allSettled(submissions);
    const failedSubmission = settledSubmissions.find((item) => item.status === "rejected");
    if (failedSubmission) {
      const createdTaskIds = settledSubmissions
        .filter((item) => item.status === "fulfilled")
        .map((item) => String(item.value?.result?.task?.id || "").trim())
        .filter(Boolean);
      await Promise.allSettled(createdTaskIds.map((taskId) => api(
        `/api/persona_dashboard/automation/tasks/${encodeURIComponent(taskId)}/cancel`,
        { method: "POST" },
      )));
      throw failedSubmission.reason;
    }
    const results = [];
    for (const submission of settledSubmissions) {
      const { index, result, sequenceMetadata } = submission.value;
      results.push(result);
      const task = result?.task;
      if (task?.id) {
        task.payload = {
          ...socialTaskPayload(task),
          ...sequenceMetadata,
        };
        mergeSocialTaskState(result?.login_task, task);
        state.socialTaskToastLabels[String(task.id)] = `${index + 1}/${posts.length} 篇 · ${account.username || account.display_name || ""}`;
        registerSocialTaskToastBatch(batchToastKey, results.map((item) => item?.task).filter(Boolean));
        syncSocialTaskToast(task, { force: true });
        if (!isFutureScheduledSocialTask(task)) refreshLiveBrowserSessionsSoon(String(task.id), 40, 500);
      }
    }
    const immediateTasks = results.map((item) => item?.task).filter((task) => task?.id && !isFutureScheduledSocialTask(task));
    const immediateTaskIds = immediateTasks.map((task) => String(task.id));
    if (immediateTaskIds.length) {
      watchPersonaPublishTaskSequence(immediateTaskIds, persona.id).catch((error) => {
        showMsg(messageId, error?.detail || error?.message || "连续任务状态跟踪失败", false, {
          key: socialTaskToastKey(immediateTaskIds[0]),
          kind: "failed",
        });
      });
    }
    await loadSocial();
    await loadPersonaDraftPosts(persona.id, { force: true }).catch(() => {});
    if (source === "favorites") await loadPersonaFavoritePosts(persona.id, { force: true }).catch(() => {});
    clearUploadDropzoneState("simpleMediaFiles");
    return results;
  } catch (error) {
    if (error && typeof error === "object") {
      try { error.toastKey = batchToastKey; } catch (_) {}
    }
    throw error;
  } finally {
    setActionLocked(lockParts, false);
    if (state.activeModule === "publishing") renderSimpleFlowModule("publishing");
  }
}

async function savePersonaThreadsBinding() {
  const persona = selectedPersona();
  const username = $("personaThreadsHandle")?.value.trim().replace(/^@+/, "") || "";
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  if (!username) {
    showMsg("commandMsg", "请先填写 Threads 用户名。", false);
    return;
  }
  showMsg("commandMsg", "正在保存 Threads 绑定...", true);
  await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/threads_binding`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username }),
  });
  appendEvent("persona", `${persona.name || persona.id} 已保存 Threads 绑定：${username}`);
  showMsg("commandMsg", "Threads 绑定已保存。", true);
  await loadPersonas();
  refreshAutomationWorkSurface();
}

async function unbindPersonaThreadsBinding() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  showMsg("commandMsg", "正在解绑 Threads 绑定...", true);
  await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/threads_binding`, { method: "DELETE" });
  appendEvent("persona", `${persona.name || persona.id} 已解绑 Threads 绑定`);
  showMsg("commandMsg", "Threads 绑定已解绑。", true);
  await loadPersonas();
  refreshAutomationWorkSurface();
}

async function patchPersonaProfile(payload) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return null;
  }
  const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/profile`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  state.personaProfiles[String(persona.id)] = result;
  await loadPersonas();
  return result;
}

function renderPersonaProfileEditorBackIcon() {
  return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5"></path><path d="m11 18-6-6 6-6"></path></svg>`;
}

function personaProfileEditorSummary(text, fallback) {
  const value = String(text || "").trim();
  return value ? value.slice(0, 70) : fallback;
}

function renderPersonaProfileEditorOverview(persona, profile) {
  const activePreset = activePersonaLinkPreset(profile);
  const styleSummary = String(profile?.tweet_style_profile || "").trim();
  const content = String(profile?.content || persona?.content || "").trim();
  const imageLibrary = personaImageLibraryState(persona?.id);
  const imageCount = Array.isArray(imageLibrary?.items) ? imageLibrary.items.length : 0;
  const hasReferenceImage = Boolean(
    String(imageLibrary?.current_reference_url || "").trim()
    || imageLibrary?.items?.some((item) => item && (item.is_reference || item.isReference)),
  );
  const items = [
    ["profile", "人设资料", String(profile?.name || persona?.name || "未命名人设"), content || "填写人物背景、内容方向和表达方式"],
    ["links", "链接设置", activePreset?.name || "未设置", personaProfileEditorSummary(personaLinkEndingContent(activePreset), "尚未选择结尾内容模板")],
    ["style", "推文风格", styleSummary ? "已提取风格" : "未设置", personaProfileEditorSummary(styleSummary, "尚未保存代表性推文样例")],
    ["image", "人设图", hasReferenceImage ? "已设置当前人设图" : "未设置", imageCount ? `图库中有 ${imageCount} 张图片` : "生成或上传人设图后可在此管理"],
  ];
  return `
    <div class="persona-profile-editor-overview">
      <p class="persona-profile-editor-intro">统一管理当前人设的名称、发布链接、推文风格、简介内容与人设图。</p>
      <div class="persona-profile-editor-list">
        ${items.map(([page, label, value, description]) => `
          <button type="button" class="persona-profile-editor-item${page === "profile" ? " persona-profile-editor-item--profile" : ""}" data-persona-profile-editor-page="${esc(page)}">
            <span class="persona-profile-editor-item-copy"><strong>${esc(label)}</strong><b>${esc(value)}</b><small>${esc(description)}</small></span>
            <span class="persona-profile-editor-item-arrow" aria-hidden="true">›</span>
          </button>
        `).join("")}
      </div>
    </div>`;
}

function renderPersonaProfileEditorPage(page, persona, profile) {
  if (page === "profile") {
    const content = String(profile?.content || persona?.content || "");
    return `
      <div class="persona-profile-editor-form">
        <p>名称与简介作为同一份人设资料管理，保存后会一起同步到当前人设、草稿和发布记录。</p>
        <label>人设名称<input id="personaProfileEditorName" value="${esc(profile?.name || persona?.name || "")}" maxlength="80" autocomplete="off" /></label>
        <label>简介内容<textarea id="personaProfileEditorContent" rows="12" placeholder="输入人设背景、内容方向和表达方式">${esc(content)}</textarea></label>
        <div class="row-actions persona-profile-editor-form-actions"><button type="button" data-persona-profile-editor-regenerate>AI 重新生成</button><button type="button" class="primary" data-persona-profile-editor-save="profile">保存人设资料</button></div>
      </div>`;
  }
  if (page === "style") {
    return `
      <div class="persona-profile-editor-form persona-profile-style-modal-content">
        <p>保存代表性推文样例后，系统会提取并保留当前的表达风格。</p>
        <label>风格样例<textarea id="personaProfileEditorStyle" rows="9" placeholder="粘贴一条代表性推文，保存后自动提取风格。">${esc(profile?.tweet_style_sample || "")}</textarea></label>
        <div class="flow-box"><span>当前提取结果</span><strong>${esc(profile?.tweet_style_profile || "尚未提取")}</strong></div>
        <div class="row-actions"><button type="button" class="primary" data-persona-profile-editor-save="style">保存风格</button><button type="button" class="unified-action-icon-button" data-persona-profile-editor-clear-style title="清空风格" aria-label="清空风格" ${profile?.tweet_style_sample ? "" : "disabled"}>${renderClearSelectionIcon()}</button></div>
      </div>`;
  }
  if (page === "image") {
    return `
      <div class="persona-profile-editor-image">
        <p>生成、上传、设为当前或整理人设图库，都在此处完成。</p>
        ${renderPersonaImagePanel(persona, { embedded: true })}
      </div>`;
  }
  return `<div class="persona-profile-editor-links">${renderPersonaLinkSettingsContent(profile)}</div>`;
}

function setPersonaProfileEditorHeader(modal, page) {
  const head = modal?.querySelector(".console-modal-head");
  if (!head) return;
  const labelMap = { profile: "人设资料", links: "链接设置", style: "推文风格", image: "人设图" };
  if (page === "overview") {
    head.innerHTML = `<strong id="consoleModalTitle">编辑人设档案</strong>${renderModalCloseButton()}`;
    return;
  }
  head.innerHTML = `
    <button type="button" class="persona-profile-editor-back" data-persona-profile-editor-back title="返回档案编辑" aria-label="返回档案编辑">${renderPersonaProfileEditorBackIcon()}</button>
    <strong id="consoleModalTitle">${esc(labelMap[page] || "编辑人设档案")}</strong>
    ${renderModalCloseButton()}`;
}

function renderPersonaProfileEditorModal(page = "overview") {
  const modal = $("consoleModal");
  const persona = selectedPersona();
  const profile = selectedPersonaProfile() || (persona ? fallbackPersonaProfile(persona) : null);
  const content = modal?.querySelector(".console-modal-content");
  if (!modal || modal.dataset.modalKey !== "persona-profile-editor" || !persona || !profile || !content) return false;
  const normalizedPage = ["profile", "links", "style", "image"].includes(page) ? page : "overview";
  modal.dataset.personaProfileEditorPage = normalizedPage;
  setPersonaProfileEditorHeader(modal, normalizedPage);
  content.innerHTML = normalizedPage === "overview"
    ? renderPersonaProfileEditorOverview(persona, profile)
    : renderPersonaProfileEditorPage(normalizedPage, persona, profile);
  content.querySelectorAll("strong, p, label, button, [title], [aria-label], [placeholder]").forEach(markConsoleUiElement);
  translateConsoleLanguage(content, currentLanguage());
  const focusTarget = normalizedPage === "overview"
    ? content.querySelector("[data-persona-profile-editor-page]")
    : content.querySelector("input, textarea, button");
  focusTarget?.focus();
  return true;
}

async function regeneratePersonaProfileEditorContent() {
  const persona = selectedPersona();
  const profile = selectedPersonaProfile() || (persona ? fallbackPersonaProfile(persona) : null);
  const name = String($("personaProfileEditorName")?.value || profile?.name || persona?.name || "").trim();
  const prompt = String($("personaProfileEditorContent")?.value || "").trim();
  if (!persona || !name || !prompt) {
    showMsg("commandMsg", "请先填写人设名称和简介内容。", false);
    return;
  }
  const button = $("consoleModal")?.querySelector("[data-persona-profile-editor-regenerate]");
  if (button) button.disabled = true;
  try {
    const result = await api("/api/persona_dashboard/personas/ai_profile", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, prompt }),
    });
    const nextContent = String(result?.content || "").trim();
    if (!nextContent) throw new Error("AI 没有返回可用简介，请稍后重试。");
    const input = $("personaProfileEditorContent");
    if (input) input.value = nextContent;
    showMsg("commandMsg", withBillingChargeMessage("简介已重新生成，请确认后保存。", result), true);
  } finally {
    if (button) button.disabled = false;
  }
}

async function openPersonaProfileEditorModal() {
  return openPersonaProfileEditorModalWithOptions();
}

async function openPersonaProfileEditorModalWithOptions({ immediate = false } = {}) {
  const persona = selectedPersona();
  const profile = selectedPersonaProfile() || (persona ? (immediate ? fallbackPersonaProfile(persona) : await loadPersonaProfile(persona.id)) : null);
  if (!persona || !profile) return;
  if (!immediate) await loadPersonaImageLibrary(persona.id).catch(() => {});
  const request = openConsoleModal({
    title: "编辑人设档案",
    contentHtml: " ",
    showCancel: false,
    showConfirm: false,
    modalKey: "persona-profile-editor",
  });
  const modal = $("consoleModal");
  const dialog = modal?.querySelector(".console-modal-dialog");
  dialog?.classList.add("persona-profile-editor-modal");
  renderPersonaProfileEditorModal();
  modal?.addEventListener("click", (event) => {
    // This dialog reuses controls that also exist on the main persona panel.
    // Keep its actions inside the dialog so document-level handlers cannot
    // submit the same action a second time against stale panel state.
    event.stopPropagation();
    const run = async (action, page = String(modal.dataset.personaProfileEditorPage || "overview")) => {
      try {
        await action();
        renderPersonaProfileEditorModal(page);
      } catch (error) {
        showMsg("commandMsg", error?.detail || error?.message || "人设档案保存失败", false);
      }
    };
    const previewButton = event.target.closest("[data-media-preview-group]");
    if (previewButton) {
      openPersonaMediaLightbox(
        previewButton.dataset.mediaPreviewGroup || "",
        Number(previewButton.dataset.mediaPreviewIndex || 0),
      );
      return;
    }
    const imageSelection = event.target.closest("[data-persona-image-select]");
    if (imageSelection) return togglePersonaImageSelection(imageSelection.dataset.personaImageSelect || "");
    // The modal itself records the active page with this data attribute. Limit
    // the selector to actual navigation buttons so save/upload actions do not
    // get mistaken for a request to redraw the current page.
    const pageButton = event.target.closest("button[data-persona-profile-editor-page]");
    if (pageButton) {
      renderPersonaProfileEditorModal(pageButton.dataset.personaProfileEditorPage || "overview");
      return;
    }
    if (event.target.closest("[data-persona-profile-editor-back]")) {
      renderPersonaProfileEditorModal();
      return;
    }
    const saveButton = event.target.closest("[data-persona-profile-editor-save]");
    if (saveButton) {
      const field = saveButton.dataset.personaProfileEditorSave || "";
      if (field === "profile") {
        const name = String($("personaProfileEditorName")?.value || "").trim();
        const content = String($("personaProfileEditorContent")?.value || "").trim();
        if (!name) return showMsg("commandMsg", "人设名称不能为空。", false);
        if (!content) return showMsg("commandMsg", "人设简介不能为空。", false);
        run(async () => {
          await patchPersonaProfile({ name, content });
          renderPersonaDetail();
          renderConfirmSummary();
          showMsg("commandMsg", "人设资料已保存。", true);
        }, "profile");
      }
      if (field === "style") {
        run(async () => {
          await patchPersonaProfile({ tweet_style_sample: $("personaProfileEditorStyle")?.value || "" });
          renderPersonaDetail();
          renderConfirmSummary();
          showMsg("commandMsg", "推文风格已保存，提取结果已更新。", true);
        }, "style");
      }
      return;
    }
    if (event.target.closest("[data-persona-profile-editor-regenerate]")) {
      regeneratePersonaProfileEditorContent().catch((error) => showMsg("commandMsg", error?.detail || error?.message || "AI 生成简介失败", false));
      return;
    }
    if (event.target.closest("[data-persona-profile-editor-clear-style]")) {
      run(async () => {
        await patchPersonaProfile({ tweet_style_sample: "" });
        renderPersonaDetail();
        renderConfirmSummary();
        showMsg("commandMsg", "推文风格已清空。", true);
      }, "style");
      return;
    }
    if (event.target.closest("[data-persona-generate-image]")) {
      return run(() => submitPersonaImageGeneration(), "image");
    }
    if (event.target.closest("[data-persona-upload-image-trigger]")) {
      const input = $("personaImageUploadFile");
      if (input) {
        delete input.dataset.personaReplaceImage;
        input.click();
      }
      return;
    }
    const applyImage = event.target.closest("[data-persona-apply-image]");
    if (applyImage) return run(() => applyPersonaReferenceImage(applyImage.dataset.personaApplyImage || ""), "image");
    const deleteImage = event.target.closest("[data-persona-delete-image]");
    if (deleteImage) {
      const imageId = String(deleteImage.dataset.personaDeleteImage || "").trim();
      const isCurrent = deleteImage.closest(".persona-image-library-card")?.classList.contains("is-reference");
      const message = isCurrent
        ? "确定删除当前人设图吗？系统会自动切换到最新的历史图；没有历史图时将清空当前参考图。"
        : "确定删除这张历史人设图吗？删除后不可恢复。";
      confirmDangerAction(message, { title: "删除人设图", confirmText: "删除图片" })
        .then((ok) => (ok ? deletePersonaLibraryImage(imageId) : null))
        .then((result) => {
          if (!result) return;
          return openPersonaProfileEditorModal();
        })
        .catch((error) => showMsg("commandMsg", error?.detail || error?.message || "删除人设图失败", false));
      return;
    }
    const pageControl = event.target.closest("[data-persona-link-page]");
    if (pageControl) {
      const pageInfo = personaLinkPresetPage(personaProfilePresets(selectedPersonaProfile()).length);
      const action = String(pageControl.dataset.personaLinkPage || "");
      if (action === "first") setPersonaLinkPresetPage(1);
      if (action === "prev") setPersonaLinkPresetPage(pageInfo.page - 1);
      if (action === "next") setPersonaLinkPresetPage(pageInfo.page + 1);
      if (action === "last") setPersonaLinkPresetPage(pageInfo.totalPages);
      renderPersonaProfileEditorModal("links");
      return;
    }
    const activateRow = event.target.closest("[data-persona-activate-preset-id]");
    if (activateRow) return run(() => activatePersonaPreset(activateRow.dataset.personaActivatePresetId || ""), "links");
    const deleteRow = event.target.closest("[data-persona-delete-preset-id]");
    if (deleteRow) return run(() => deletePersonaPreset(deleteRow.dataset.personaDeletePresetId || ""), "links");
    const select = event.target.closest("[data-persona-select-preset]");
    if (select) {
      state.personaLinkPresetId = select.dataset.personaSelectPreset || "";
      renderPersonaProfileEditorModal("links");
      return;
    }
    if (event.target.closest("[data-persona-add-preset]")) return run(() => addPersonaPreset(), "links");
    if (event.target.closest("[data-persona-save-preset]")) return run(() => savePersonaPreset(), "links");
    if (event.target.closest("[data-persona-delete-preset]")) return run(() => deletePersonaPreset(), "links");
    if (event.target.closest("[data-persona-activate-preset]")) return run(() => activatePersonaPreset(), "links");
  });
  modal?.addEventListener("input", (event) => {
    if (event.target?.matches?.("[data-persona-image-prompt]")) syncPersonaImagePromptState(event.target);
  });
  modal?.addEventListener("change", (event) => {
    const input = event.target?.matches?.("[data-persona-upload-image-file]") ? event.target : null;
    if (!input) return;
    const file = input.files?.[0] || null;
    const imageId = String(input.dataset.personaReplaceImage || "").trim();
    input.value = "";
    delete input.dataset.personaReplaceImage;
    if (!file) return;
    const action = imageId ? replacePersonaLibraryImage(imageId, file) : uploadPersonaReferenceImage(file);
    action.then(() => renderPersonaProfileEditorModal("image"))
      .catch((error) => showMsg("commandMsg", error?.detail || error?.message || "上传人设图失败", false));
  });
  await request;
}

async function openPersonaTweetStyleModal() {
  const profile = selectedPersonaProfile();
  if (!profile) return;
  const request = openConsoleModal({
    title: "推文风格设置",
    message: "保存代表性推文样例后，系统会提取并在基础资料中显示当前风格。",
    contentHtml: renderPersonaTweetStyleSettingsContent(profile),
    confirmText: "完成",
    showCancel: false,
    showConfirm: false,
    modalKey: "persona-tweet-style",
  });
  const modal = $("consoleModal");
  modal?.querySelector(".console-modal-dialog")?.classList.add("persona-settings-modal");
  modal?.addEventListener("click", (event) => {
    if (event.target.closest("[data-persona-save-style]")) {
      savePersonaTweetStyle().catch((error) => showMsg("commandMsg", error.detail || error.message || "保存推文风格失败", false));
    }
    if (event.target.closest("[data-persona-clear-style]")) {
      clearPersonaTweetStyle().catch((error) => showMsg("commandMsg", error.detail || error.message || "清空推文风格失败", false));
    }
  });
  await request;
}

function refreshPersonaLinkSettingsModal() {
  const modal = $("consoleModal");
  if (modal?.dataset.modalKey !== "persona-link-settings") return false;
  const content = modal.querySelector(".console-modal-content");
  const profile = selectedPersonaProfile();
  if (!content || !profile) return false;
  content.innerHTML = renderPersonaLinkSettingsContent(profile);
  content.querySelectorAll("strong, p, label, button, [title], [aria-label], [placeholder]").forEach(markConsoleUiElement);
  translateConsoleLanguage(content, currentLanguage());
  return true;
}

async function openPersonaLinkSettingsModal() {
  const persona = selectedPersona();
  const profile = selectedPersonaProfile() || (persona ? await loadPersonaProfile(persona.id) : null);
  if (!profile) return;
  const request = openConsoleModal({
    title: "链接设置",
    message: "管理发布时使用的结尾内容，当前启用模板会同步显示在基础资料中。",
    contentHtml: renderPersonaLinkSettingsContent(profile),
    confirmText: "完成",
    showCancel: false,
    showConfirm: false,
    modalKey: "persona-link-settings",
  });
  const modal = $("consoleModal");
  modal?.querySelector(".console-modal-dialog")?.classList.add("persona-settings-modal", "persona-link-settings-modal");
  modal?.addEventListener("click", (event) => {
    const run = (action) => action.catch((error) => showMsg("commandMsg", error.detail || error.message || "链接设置操作失败", false));
    const pageButton = event.target.closest("[data-persona-link-page]");
    if (pageButton) {
      const currentProfile = selectedPersonaProfile();
      const pageInfo = personaLinkPresetPage(personaProfilePresets(currentProfile).length);
      const action = String(pageButton.dataset.personaLinkPage || "");
      if (action === "first") setPersonaLinkPresetPage(1);
      if (action === "prev") setPersonaLinkPresetPage(pageInfo.page - 1);
      if (action === "next") setPersonaLinkPresetPage(pageInfo.page + 1);
      if (action === "last") setPersonaLinkPresetPage(pageInfo.totalPages);
      refreshPersonaLinkSettingsModal();
      return;
    }
    const activateRow = event.target.closest("[data-persona-activate-preset-id]");
    if (activateRow) return run(activatePersonaPreset(activateRow.dataset.personaActivatePresetId || ""));
    const deleteRow = event.target.closest("[data-persona-delete-preset-id]");
    if (deleteRow) return run(deletePersonaPreset(deleteRow.dataset.personaDeletePresetId || ""));
    const select = event.target.closest("[data-persona-select-preset]");
    if (select) {
      state.personaLinkPresetId = select.dataset.personaSelectPreset || "";
      refreshPersonaLinkSettingsModal();
      return;
    }
    if (event.target.closest("[data-persona-add-preset]")) return run(addPersonaPreset());
    if (event.target.closest("[data-persona-save-preset]")) return run(savePersonaPreset());
    if (event.target.closest("[data-persona-delete-preset]")) return run(deletePersonaPreset());
    if (event.target.closest("[data-persona-activate-preset]")) return run(activatePersonaPreset());
  });
  await request;
}

async function regeneratePersonaProfileContent() {
  const busyKind = personaCreateBusyKind();
  if (busyKind) {
    showMsg("commandMsg", `${busyKind}正在执行，请等待当前任务完成。`, false);
    return;
  }
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const draft = snapshotPersonaProfileEditDraft();
  if (!draft || draft.field !== "content") {
    beginPersonaProfileEdit("content");
    return;
  }
  const profile = selectedPersonaProfile() || fallbackPersonaProfile(persona);
  const name = String(draft.name || profile?.name || persona.name || "").trim();
  const prompt = draft.content.trim();
  if (!name || !prompt) {
    showMsg("commandMsg", "请先填写人设名称和生成方向。", false);
    return;
  }
  state.personaCreateBusy.profileContent = true;
  renderPersonaDetail();
  try {
    showMsg("commandMsg", "正在重新生成人设简介...", true);
    const result = await api("/api/persona_dashboard/personas/ai_profile", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, prompt }),
    });
    const nextContent = String(result.content || "").trim();
    if (!nextContent) {
      showMsg("commandMsg", "AI 没有返回可用简介，请调整当前简介后再试。", false);
      return;
    }
    state.personaProfileEditDrafts[String(persona.id)] = { field: "content", name, content: nextContent };
    showMsg("commandMsg", withBillingChargeMessage("简介已重新生成并回填，请确认后保存。", result), true);
  } finally {
    state.personaCreateBusy.profileContent = false;
    if (isPersonaWorkspaceModule()) renderPersonaDetail();
  }
}

async function savePersonaTweetStyle() {
  const result = await patchPersonaProfile({ tweet_style_sample: $("personaTweetStyleSample")?.value || "" });
  if (result) {
    if ($("consoleModal")?.dataset.modalKey === "persona-tweet-style") closeConsoleModal(true);
    renderPersonaDetail();
    renderConfirmSummary();
    showMsg("commandMsg", "推文风格已保存，提取结果已更新。", true);
  }
}

async function clearPersonaTweetStyle() {
  const result = await patchPersonaProfile({ tweet_style_sample: "" });
  if (result) {
    if ($("consoleModal")?.dataset.modalKey === "persona-tweet-style") closeConsoleModal(true);
    renderPersonaDetail();
    renderConfirmSummary();
    showMsg("commandMsg", "推文风格已清空。", true);
  }
}

function draftPersonaPresetList(profile, mutate) {
  const presets = personaProfilePresets(profile).map((item) => ({
    id: item.id,
    name: item.name || "",
    link_url: item.link_url || "",
    ending_text: item.ending_text || "",
    enabled: item.enabled !== false,
  }));
  mutate(presets);
  return presets;
}

function readPersonaPresetForm() {
  return {
    name: $("personaLinkPresetName")?.value.trim() || "",
    link_url: "",
    ending_text: $("personaLinkPresetEnding")?.value.trim() || "",
  };
}

async function savePersonaPresetList(nextPresets, activeId = null) {
  const payload = { link_presets: nextPresets };
  if (activeId !== null) payload.active_link_preset_id = activeId;
  const result = await patchPersonaProfile(payload);
  if (result) {
    const selectedId = String(state.personaLinkPresetId || "");
    state.personaLinkPresetId = nextPresets.some((item) => String(item.id || "") === selectedId)
      ? selectedId
      : String(result.active_link_preset_id || nextPresets[0]?.id || "");
    const refreshedModal = refreshPersonaLinkSettingsModal();
    if (!refreshedModal) renderPersonaDetail();
    renderConfirmSummary();
    showMsg("commandMsg", "链接模板已保存。", true);
  }
}

async function addPersonaPreset() {
  const profile = selectedPersonaProfile();
  if (!profile) return;
  const form = readPersonaPresetForm();
  if (!form.ending_text) {
    showMsg("commandMsg", "请先填写结尾内容。", false);
    return;
  }
  const nextId = `preset-${Date.now().toString(36)}`;
  const nextPresets = draftPersonaPresetList(profile, (presets) => {
    presets.push({
      id: nextId,
      name: form.name || "结尾内容模板",
      link_url: "",
      ending_text: form.ending_text,
      enabled: true,
    });
  });
  state.personaLinkPresetId = nextId;
  setPersonaLinkPresetPage(Math.ceil(nextPresets.length / 20));
  await savePersonaPresetList(nextPresets, String(profile.active_link_preset_id || ""));
}

async function savePersonaPreset() {
  const profile = selectedPersonaProfile();
  const preset = selectedPersonaPreset(profile);
  if (!profile || !preset) return;
  const form = readPersonaPresetForm();
  if (!form.ending_text) {
    showMsg("commandMsg", "请先填写结尾内容。", false);
    return;
  }
  const nextPresets = draftPersonaPresetList(profile, (presets) => {
    const index = presets.findIndex((item) => String(item.id) === String(preset.id));
    if (index >= 0) {
      presets[index] = {
        ...presets[index],
        name: form.name || presets[index].name || "结尾内容模板",
        link_url: "",
        ending_text: form.ending_text,
      };
    }
  });
  await savePersonaPresetList(nextPresets, String(profile.active_link_preset_id || ""));
}

async function deletePersonaPreset(presetId = "") {
  const profile = selectedPersonaProfile();
  const preset = personaPresetById(profile, presetId) || selectedPersonaPreset(profile);
  if (!profile || !preset) return;
  const nextPresets = draftPersonaPresetList(profile, (presets) => {
    const index = presets.findIndex((item) => String(item.id) === String(preset.id));
    if (index >= 0) presets.splice(index, 1);
  });
  const nextActive = nextPresets.some((item) => String(item.id) === String(profile.active_link_preset_id || ""))
    ? String(profile.active_link_preset_id || "")
    : "";
  state.personaLinkPresetId = nextPresets[0]?.id || "";
  await savePersonaPresetList(nextPresets, nextActive);
}

async function activatePersonaPreset(presetId = "") {
  const profile = selectedPersonaProfile();
  const preset = personaPresetById(profile, presetId) || selectedPersonaPreset(profile);
  if (!profile || !preset) return;
  const isActive = (
    preset?.enabled !== false
    && String(profile.active_link_preset_id || "") === String(preset.id || "")
  );
  const nextPresets = draftPersonaPresetList(profile, (presets) => {
    if (!isActive) {
      const target = presets.find((item) => String(item.id || "") === String(preset.id || ""));
      if (target) target.enabled = true;
    }
  });
  state.personaLinkPresetId = String(preset.id || "");
  await savePersonaPresetList(nextPresets, isActive ? "" : String(preset.id));
}

async function deleteSelectedPersona(personaId = "") {
  const persona = personaId
    ? state.personas.find((item) => String(item.id) === String(personaId || ""))
    : selectedPersona();
  if (!persona) return;
  state.personaListEditorId = "";
  state.personaListEditorMode = "";
  removePersonaCardEditorPortal();
  const confirmed = await openConsoleModal({
    title: "删除人设",
    message: `确认删除人设「${persona.name || persona.id}」？删除后不可恢复。`,
    confirmText: "删除",
    danger: true,
  });
  if (!confirmed) return;
  await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}`, { method: "DELETE" });
  showMsg("commandMsg", "人设已删除。", true);
  if (String(state.selectedPersonaId || "") === String(persona.id || "")) {
    setSelectedPersonaId("");
    setSelectedPersonaPostId("");
    state.personaCreateMode = false;
  }
  if (String(state.personaListEditorId || "") === String(persona.id || "")) {
    state.personaListEditorId = "";
    state.personaListEditorMode = "";
  }
  await loadPersonas();
}

async function deleteBulkSelectedPersonaEntries() {
  if (state.personaBulkDeleting) return;
  const personaIds = Array.from(personaBulkSelectedSet());
  const groupIds = Array.from(personaBulkSelectedGroupSet());
  const selectedCount = personaIds.length + groupIds.length;
  if (!selectedCount) return;
  const confirmed = await openConsoleModal({
    title: "批量删除",
    message: `确认删除已选的 ${personaIds.length} 个人设和 ${groupIds.length} 个分组？人设相关数据将一并清理；仅删除分组时，组内未删除的人设会转为未分组。此操作不可恢复。`,
    confirmText: `删除 ${selectedCount} 项`,
    danger: true,
  });
  if (!confirmed) return;

  state.personaBulkDeleting = true;
  renderPersonaModule();
  try {
    const result = await api("/api/persona_dashboard/selection/batch-delete", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ persona_ids: personaIds, group_ids: groupIds }),
    });
    const deletedIds = new Set(
      (result.deleted_persona_ids || personaIds).map((id) => String(id || "")),
    );
    const deletedPersonaCount = Number(result.deleted_persona_count || deletedIds.size);
    const deletedGroupCount = Number(result.deleted_group_count || groupIds.length);
    if (deletedIds.size) {
      [
        state.personaProfiles,
        state.personaMemories,
        state.personaImageLibraries,
        state.personaDraftPosts,
        state.personaFavoritePosts,
        state.personaSelectedPostIds,
        state.personaPostSources,
        state.personaPostPages,
        state.personaPublishHistories,
        state.personaPublishAccountIds,
        state.personaPublishResults,
        state.personaAutomationResults,
      ].forEach((cache) => {
        if (!cache || typeof cache !== "object") return;
        deletedIds.forEach((id) => delete cache[id]);
      });
      Object.values(state.personaFetches || {}).forEach((cache) => {
        deletedIds.forEach((id) => delete cache?.[id]);
      });
      if (deletedIds.has(String(state.selectedPersonaId || ""))) {
        setSelectedPersonaId("");
        setSelectedPersonaPostId("");
        state.personaCreateMode = false;
      }
    }
    state.personaBulkSelectedIds = new Set();
    state.personaBulkSelectedGroupIds = new Set();
    state.personaBulkMode = false;
    await loadPersonas();
    showMsg("commandMsg", `已删除 ${deletedPersonaCount} 个人设和 ${deletedGroupCount} 个分组。`, true);
  } finally {
    state.personaBulkDeleting = false;
    if (state.personaBulkMode) renderPersonaModule();
  }
}

async function duplicatePersonaArchive(personaId = "") {
  const cleanId = String(personaId || "").trim();
  const persona = state.personas.find((item) => String(item.id || "") === cleanId);
  if (!persona) return;
  state.personaListEditorId = "";
  state.personaListEditorMode = "";
  removePersonaCardEditorPortal();
  const confirmed = await openConsoleModal({
    title: "复制人设",
    message: `确认复制人设「${persona.name || persona.id}」？系统会直接拷贝当前人设数据并生成一份副本。`,
    confirmText: "复制",
  });
  if (!confirmed) return;
  showMsg("commandMsg", "正在复制人设...", true);
  const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(cleanId)}/duplicate`, { method: "POST" });
  const profile = result?.profile && typeof result.profile === "object" ? result.profile : null;
  if (profile?.id) {
    const newId = String(profile.id);
    setSelectedPersonaId(newId);
    setSelectedPersonaPostId("");
    delete state.personaDraftPosts[newId];
    delete state.personaFavoritePosts[newId];
    delete state.personaPublishHistories[newId];
    delete state.personaMemories[newId];
    delete state.personaImageLibraries[newId];
  }
  await loadPersonas();
  if (profile?.id) setSelectedPersonaId(profile.id);
  renderActivePersonaListSurface();
  renderConfirmSummary();
  showMsg("commandMsg", `已复制人设：${profile?.name || `${persona.name || persona.id} 副本`}`, true);
}

async function createPersonaAutomationAccount() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const platform = selectedPersonaAutomationPlatform();
  openAccountPoolCreateModal({ platform, personaId: persona.id });
}

function buildPersonaThreadsTaskPayload(kind, platform = selectedPersonaAutomationPlatform()) {
  const strategyGroup = kind === "reply_hot"
    ? "threads_hot_reply"
    : kind === "warmup"
      ? `${String(platform || "").trim().toLowerCase() === "instagram" ? "instagram" : "threads"}_warmup`
      : "threads_comment_reply";
  const strategy = personaThreadsStrategy(strategyGroup);
  const payload = { ...(strategy?.payload || {}) };
  if (kind === "reply_comment" || kind === "reply_hot") {
    if (personaThreadsStrategyIsCustom(strategyGroup)) {
      payload.max_age_days = numberField("personaAutoMaxAgeDays", payload.max_age_days || (kind === "reply_hot" ? 30 : 2));
      payload.max_posts = numberField("personaAutoMaxPosts", payload.max_posts || 5);
      payload.max_replies = numberField("personaAutoMaxReplies", payload.max_replies || 3);
      if (kind === "reply_hot") {
        payload.min_views = numberField("personaAutoMinViews", payload.min_views || 0);
        const targetUrls = splitLines($("personaAutoTargetUrls")?.value || "");
        if (targetUrls.length) payload.target_urls = targetUrls;
      }
    }
    const replyTemplates = splitLines($("personaAutoReplyText")?.value || "");
    if (replyTemplates.length) payload.reply_templates = replyTemplates;
    return payload;
  }
  if (personaThreadsStrategyIsCustom(strategyGroup)) {
    payload.browse_limit = numberField("personaAutoBrowseLimit", payload.browse_limit || payload.scroll_times || 80);
    payload.scroll_times = payload.browse_limit;
    payload.like_limit = Math.max(0, Math.min(16, numberField("personaAutoLikeLimit", payload.like_limit || 0)));
    payload.max_comments = Math.max(0, Math.min(6, numberField("personaAutoMaxComments", payload.max_comments || 0)));
    payload.comment_chance = Number(payload.max_comments || 0) > 0 ? 100 : 0;
  }
  const replyTemplates = splitLines($("personaAutoReplyText")?.value || "");
  if (replyTemplates.length) payload.reply_templates = replyTemplates;
  return payload;
}

async function runPersonaThreadsTask(kind) {
  const persona = selectedPersona();
  const platform = selectedPersonaAutomationPlatform();
  const account = selectedPersonaAutomationAccount(persona, platform);
  if (!persona || !account) {
    showMsg("commandMsg", `请先绑定并选择 ${platformLabel(platform)} 执行账号。`, false);
    return;
  }
  const taskType = kind === "warmup"
    ? (platform === "instagram" ? "instagram_warmup" : "threads_warmup")
    : (platform === "instagram" ? "instagram_auto_reply" : "threads_auto_reply");
  const lockParts = ["social", account.id, taskType];
  if (isActionLocked(...lockParts) || activeSocialTaskFor({ accountId: account.id, taskType })) {
    showMsg("commandMsg", `该账号已有${kind === "warmup" ? "养号" : "自动回复"}任务在队列或执行中，请等待完成。`, false);
    return;
  }
  setActionLocked(lockParts, true);
  refreshAutomationWorkSurface();
  try {
    const result = await api("/api/persona_dashboard/automation/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        persona_id: persona.id,
        account_id: account.id,
        platform,
        task_type: taskType,
        priority: 50,
        max_retries: 2,
        payload: buildPersonaThreadsTaskPayload(kind, platform),
      }),
    });
    showMsg("commandMsg", `${kind === "warmup" ? "养号" : "自动回复"}任务已提交：${result.task?.id || ""}`, true, {
      key: result.task?.id ? socialTaskToastKey(result.task.id, result.task) : undefined,
      kind: "queued",
      taskId: result.task?.id || "",
      taskPanel: "persona",
      personaId: persona.id,
    });
  } finally {
    setActionLocked(lockParts, false);
    refreshAutomationWorkSurface();
  }
}

async function clearPersonaAutomationTasks() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  await clearPersonaAutomationTasksFor(persona.id, "commandMsg");
}

async function clearPersonaAutomationTasksFor(personaId, messageId = "commandMsg") {
  const cleanPersonaId = String(personaId || "").trim();
  if (!cleanPersonaId) {
    showMsg(messageId, "请先选择一个人设。", false);
    return;
  }
  await api(`/api/persona_dashboard/automation/tasks?persona_id=${encodeURIComponent(cleanPersonaId)}`, { method: "DELETE" });
  showMsg(messageId, "该人设的自动化队列记录已删除。", true);
  await loadSocial();
  if (state.view === "tasks") await loadTasks().catch(() => {});
}

async function openPersonaAccountBindingPage(persona = selectedPersona(), account = null) {
  const personaId = String(persona?.id || state.selectedPersonaId || "").trim();
  const targetAccount = account || publishAccountForPersona(persona) || accountForPersona(persona);
  if (personaId) {
    setSelectedPersonaId(personaId);
    state.accountPoolPersonaId = personaId;
  }
  if (targetAccount?.platform) state.accountPoolPlatform = normalizeAccountPoolPlatform(targetAccount.platform);
  if (targetAccount?.id) {
    state.accountPoolAccountId = String(targetAccount.id || "");
    state.accountPoolSelectedAccountIds = [String(targetAccount.id || "")];
  }
  state.accountBrowserPanel = "accounts";
  setView("accounts");
  await loadSocial().catch(() => {});
  renderWorkspace();
  renderSocialAccounts();
  window.requestAnimationFrame(() => {
    const target = targetAccount?.id
      ? Array.from(document.querySelectorAll("[data-account-pool-account]")).find((item) => String(item.dataset.accountPoolAccount || "") === String(targetAccount.id))
      : document.querySelector("[data-account-pool-create]");
    target?.scrollIntoView({ block: "center", behavior: "smooth" });
    target?.focus({ preventScroll: true });
  });
  return true;
}

async function promptPersonaAccountBinding(persona = selectedPersona(), requestedAccount = null) {
  const account = requestedAccount || publishAccountForPersona(persona);
  const confirmed = await openConsoleModal({
    title: account ? "确认继续发布" : "绑定发布账号",
    message: account ? publishAccountBlockMessage(account) : "当前人设还没有绑定 Threads 或 Instagram 执行账号。请到账号管理绑定账号后再发布。",
    confirmText: account ? "继续执行" : "绑定账号",
    cancelText: "取消",
  });
  if (!confirmed) return false;
  if (account) return account;
  return openPersonaAccountBindingPage(persona, account);
}

function deferMobilePublishingBrowserView(taskIds = "", startedAt = 0) {
  const cleanTaskIds = (Array.isArray(taskIds) ? taskIds : [taskIds])
    .map((taskId) => String(taskId || "").trim())
    .filter(Boolean);
  if (!cleanTaskIds.length) return false;
  state.mobilePublishingTaskIds = Array.from(new Set(cleanTaskIds));
  state.mobilePublishingTaskId = state.mobilePublishingTaskIds[0];
  state.mobilePublishingTaskStartedAt = toastTimestampMs(startedAt) || Date.now();
  state.publishAssistanceDismissed = false;
  return false;
}

function bindPublishAssistanceContext(options = {}) {
  const accountId = String(options.accountId || "").trim();
  const personaId = String(options.personaId || "").trim();
  if (accountId) state.publishAssistanceAccountId = accountId;
  if (personaId) state.publishAssistancePersonaId = personaId;
}

function isPublishAssistanceOpen() {
  return Boolean(document.getElementById("loginAssistanceModal")?.classList.contains("is-publish-assistance"));
}

function shouldShowPublishAssistanceRestore() {
  if (!state.publishAssistanceDismissed) return false;
  if (isPublishAssistanceOpen()) return false;
  return Boolean(mobilePublishingTask());
}

function hidePublishAssistanceRestore() {
  state.publishAssistanceDismissed = false;
  document.querySelectorAll("[data-restore-publish-assistance]").forEach((node) => node.remove());
}

function renderPublishAssistanceRestoreButton() {
  if (!shouldShowPublishAssistanceRestore()) return "";
  return `<button type="button" class="publish-assistance-restore" data-restore-publish-assistance title="打开发布助手" aria-label="打开发布助手">发布助手</button>`;
}

function restorePublishAssistanceView() {
  const task = mobilePublishingTask();
  const taskId = String(task?.id || state.mobilePublishingTaskId || "").trim();
  if (!taskId) return;
  hidePublishAssistanceRestore();
  openPublishAssistanceView(taskId, {
    accountId: state.publishAssistanceAccountId || task?.account_id || "",
    personaId: state.publishAssistancePersonaId || task?.persona_id || "",
  });
}

function syncPublishAssistanceRestore() {
  if (state.activeModule === "publishing") {
    renderSimpleFlowModule("publishing");
    return;
  }
  if (isPersonaWorkspaceModule()) renderPersonaDetail();
}

function bindPublishAssistanceRestore(root = document) {
  root.querySelector("[data-restore-publish-assistance]")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    restorePublishAssistanceView();
  });
}

async function executeSimpleFlow({ confirmedPublishAccountId = "" } = {}) {
  if (state.activeModule === "queue") {
    setView("tasks");
    await loadTasks();
    await loadSocial();
    showMsg("commandMsg", "已打开任务队列。取消、重试和日志都在对应任务行内执行。", true);
    return;
  }
  if (state.activeModule === "publishing" || state.activeModule === "automation") {
    let accountId = $("simpleAccount")?.value || "";
    const personaId = state.activeModule === "publishing"
      ? (selectedPersona()?.id || "")
      : ($("simplePersona")?.value || selectedPersona()?.id || "");
    if (state.activeModule === "publishing") {
      const currentPublishMode = normalizedPublishMode($("simplePublishMode")?.value || state.simpleBranches.publishing);
      if (currentPublishMode === "publish_history") {
        showMsg("commandMsg", "任务历史仅用于查看记录，不会创建任务。", false);
        return;
      }
      if (currentPublishMode === "matrix_start") {
        await submitMatrixPublishTask("commandMsg");
        return;
      }
      const persona = state.personas.find((item) => String(item.id) === String(personaId)) || selectedPersona();
      accountId = selectedPublishAccountForPersona(persona)?.id || "";
      if (normalizePublishContentSource() !== "custom") {
        const result = await submitPublishContentTasks(accountId, persona, "commandMsg", { confirmedPublishAccountId });
        const resultItems = Array.isArray(result) ? result : (result ? [result] : []);
        const resultTasks = resultItems.map((item) => item?.task).filter((task) => task?.id);
        const createdTasks = Array.isArray(result?.created) ? result.created : [];
        const immediateTaskIds = [...resultTasks, ...createdTasks]
          .filter((task) => task?.id && !isFutureScheduledSocialTask(task))
          .map((task) => String(task.id || "").trim())
          .filter(Boolean);
        const immediateTaskId = immediateTaskIds[0] || "";
        if (immediateTaskId && !deferMobilePublishingBrowserView(immediateTaskIds, state.simpleFlowPendingStartedAt)) {
          bindPublishAssistanceContext({ accountId, personaId: persona?.id || "" });
          openPublishAssistanceView(immediateTaskId, { accountId });
        }
        return;
      }
    }
    if (!accountId) {
      if (state.activeModule === "publishing") {
        const persona = state.personas.find((item) => String(item.id) === String(personaId)) || selectedPersona();
        await promptPersonaAccountBinding(persona);
        return;
      }
      showMsg("commandMsg", "请先选择执行账号。", false);
      return;
    }
    const taskType = $("simplePrimary")?.value || selectedBranch(state.activeModule);
    const result = await createSocialTask(taskType, accountId, personaId, "commandMsg", { confirmedPublishAccountId });
    const taskId = String(result?.task?.id || "").trim();
    if (taskId) {
      appendEvent("queued", `${taskType} 已提交到指纹浏览器任务队列`, {
        key: socialTaskToastKey(taskId, result?.task),
        taskId,
        taskPanel: personaId ? "persona" : "regular",
        personaId,
      });
      if (taskType === "publish_post" && !isFutureScheduledSocialTask(result?.task) && !deferMobilePublishingBrowserView(taskId)) {
        bindPublishAssistanceContext({ accountId, personaId });
        openPublishAssistanceView(taskId, { accountId, personaId });
      }
    }
    return;
  }
  setView("workspace");
}

async function loadMe() {
  const meName = $("consoleMeName");
  try {
    const me = await api("/api/me");
    if (me.must_change_password) {
      handleSessionBoundary(428);
      return null;
    }
    state.currentUser = me;
    if (me.publish_policy) updateDailyPublishPolicy(me.publish_policy, { notify: false, requestSeq: beginDailyPublishPolicyRequest(), force: true });
    if (meName) meName.textContent = me.full_name || me.username || "-";
    window.VectoSiteNavigation?.setAccount(me);
    const openAdmin = $("openAdmin") || document.querySelector("[data-site-admin-entry]");
    if (openAdmin) openAdmin.hidden = !me.is_admin;
    return me;
  } catch (error) {
    state.currentUser = null;
    window.VectoSiteNavigation?.setAccount(null);
    if (meName) meName.textContent = "本地控制台";
    const openAdmin = $("openAdmin") || document.querySelector("[data-site-admin-entry]");
    if (openAdmin) openAdmin.hidden = true;
    if (!consoleBoundaryNavigationActive) {
      appendEvent("error", error.detail || error.message || "本地控制台会话不可用");
    }
    throw error;
  }
}

async function revalidateConsoleIdentity() {
  if (!consoleIdentityReady || consoleBoundaryNavigationActive) return null;
  maskConsoleForIdentityRevalidation();
  if (identityRevalidationPromise) return identityRevalidationPromise;
  const expectedUserId = consoleUserId(state.currentUser?.id);
  identityRevalidationPromise = api("/api/me")
    .then((me) => {
      if (me.must_change_password) {
        handleSessionBoundary(428);
        return null;
      }
      if (!expectedUserId || consoleUserId(me.id) !== expectedUserId) {
        reloadForIdentityChange();
        return null;
      }
      state.currentUser = me;
      if (me.publish_policy) updateDailyPublishPolicy(me.publish_policy, { notify: false, requestSeq: beginDailyPublishPolicyRequest(), force: true });
      const meName = $("consoleMeName");
      if (meName) meName.textContent = me.full_name || me.username || "-";
      window.VectoSiteNavigation?.setAccount(me);
      unmaskConsoleAfterIdentityRevalidation();
      return me;
    })
    .catch((error) => {
      if (!consoleBoundaryNavigationActive && !error?.stale) {
        appendEvent("warning", error.detail || error.message || "会话身份校验失败");
      }
      unmaskConsoleAfterIdentityRevalidation();
      return null;
    })
    .finally(() => {
      identityRevalidationPromise = null;
    });
  return identityRevalidationPromise;
}

let consoleLogoutPending = false;

async function logoutConsoleSession() {
  if (consoleLogoutPending || consoleBoundaryNavigationActive) return;
  consoleLogoutPending = true;
  window.VectoSiteNavigation?.setLogoutPending(true);
  try {
    await api("/api/auth/logout", { method: "POST" });
    window.VectoSiteNavigation?.announceAuthSessionChange?.("logout");
    const logoutFeedback = window.VectoSiteNavigation?.authFeedbackCopyByTime?.("logout") || {
      kind: "logout",
      title: "退出成功，再见",
      message: "辛苦了，期待下次见面。",
      actionText: "知道了",
    };
    await window.VectoSiteNavigation?.showAuthFeedback?.(logoutFeedback);
    consoleBoundaryNavigationActive = true;
    clearTenantInMemoryState();
    purgeLegacyTenantContentCaches();
    if (ADMIN_CONSOLE_SESSION) clearStoredAdminWorkspaceContext();
    window.VectoSiteNavigation?.setAccount(null);
    window.location.replace("/");
  } catch (error) {
    consoleLogoutPending = false;
    const message = error?.detail || error?.message || "退出失败，请重试。";
    window.VectoSiteNavigation?.setLogoutPending(false, message);
    await window.VectoSiteNavigation?.showAuthFeedback?.({
      kind: "error",
      title: "退出未完成",
      message,
    });
  }
}

