async function deletePersonaMemoryEntry(memoryId = "") {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const cleanMemoryId = String(memoryId || "").trim();
  const row = personaMemoryRows(persona).find((item) => String(item.id || "").trim() === cleanMemoryId);
  if (!cleanMemoryId || !row) {
    showMsg("commandMsg", "当前记忆不存在或已删除。", false);
    return;
  }
  const confirmed = await openConsoleModal({
    title: "删除记忆",
    message: `确认删除“${String(row.summary || "未命名记忆").trim() || "未命名记忆"}”吗？这条内容会从可选记忆里移除。`,
    confirmText: "删除",
    cancelText: "取消",
    danger: true,
  });
  if (!confirmed) return;
  showMsg("commandMsg", "正在删除记忆...", true);
  await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/memories/${encodeURIComponent(cleanMemoryId)}`, {
    method: "DELETE",
  });
  const generateForm = personaFormState(persona.id).generate;
  generateForm.selectedMemoryIds = (Array.isArray(generateForm.selectedMemoryIds) ? generateForm.selectedMemoryIds : [])
    .filter((item) => String(item || "").trim() !== cleanMemoryId);
  await loadPersonaMemories(persona.id, { force: true });
  renderPersonaDetail();
  renderConfirmSummary();
  showMsg("commandMsg", "记忆已删除。", true);
}

async function viewPersonaMemoryEntry(memoryId = "") {
  const persona = selectedPersona();
  const cleanMemoryId = String(memoryId || "").trim();
  const row = personaMemoryRows(persona).find((item) => String(item.id || "").trim() === cleanMemoryId);
  if (!persona || !cleanMemoryId || !row) {
    showMsg("commandMsg", "当前记忆不存在或已删除。", false);
    return;
  }
  const content = String(row.summary || row.content || "").trim() || "暂无内容。";
  await openConsoleModal({
    title: "人设记忆",
    contentHtml: `
      <div class="console-modal-detail persona-draft-detail-modal">
        <div><span>记录时间</span><strong>${esc(formatTime(row.date || row.updated_at || row.created_at || ""))}</strong></div>
        <div class="persona-draft-detail-content">
          <span>记忆内容</span>
          <p>${esc(content)}</p>
        </div>
      </div>
    `,
    confirmText: "关闭",
    showCancel: false,
  });
}

async function createPersonaMemoryEntry() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const values = await openConsoleModal({
    title: "新建人设记忆",
    message: "记忆只需要填写记忆内容，它会作为 AI 生成时可选的人设背景或写作约束。",
    fields: [{
      name: "summary",
      label: "记忆内容（必填）",
      multiline: true,
      required: true,
      placeholder: "例如：回答专业问题时先给结论，再给一个具体案例；语气克制、清晰。",
    }],
    confirmText: "保存记忆",
    cancelText: "取消",
  });
  if (values === null) return;
  const cleanSummary = String(values?.summary || "").trim();
  if (!cleanSummary) {
    showMsg("commandMsg", "人设记忆内容不能为空。", false);
    return;
  }
  showMsg("commandMsg", "正在保存人设记忆...", true);
  const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/memories`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ summary: cleanSummary }),
  });
  const memoryId = String(result.memory?.id || "").trim();
  const generateForm = personaFormState(persona.id).generate;
  if (memoryId) {
    generateForm.selectedMemoryIds = Array.from(new Set([
      ...(Array.isArray(generateForm.selectedMemoryIds) ? generateForm.selectedMemoryIds : []),
      memoryId,
    ]));
  }
  await loadPersonaMemories(persona.id, { force: true });
  renderPersonaDetail();
  renderConfirmSummary();
  showMsg("commandMsg", "人设记忆已新建并选中。", true);
}

async function loadPersonaImageLibrary(personaId, { force = false, throwOnError = false } = {}) {
  const key = String(personaId || "").trim();
  if (!key) return null;
  if (!force && state.personaImageLibraries[key]) return state.personaImageLibraries[key];
  const request = api(`/api/persona_dashboard/personas/${encodeURIComponent(key)}/images`);
  const data = throwOnError
    ? await request
    : await request.catch(() => ({ ok: true, items: [], current_reference_url: "" }));
  state.personaImageLibraries[key] = data;
  schedulePersonaDetailRender(key);
  return data;
}

function personaReferenceImageCandidate(library) {
  const items = Array.isArray(library?.items) ? library.items : [];
  const currentReferenceUrl = String(library?.current_reference_url || "").trim();
  const current = items.find((item) => item && (item.is_reference || item.isReference))
    || items.find((item) => currentReferenceUrl && String(item?.image_url || "").trim() === currentReferenceUrl)
    || null;
  if (!currentReferenceUrl) return { status: "missing", url: "" };
  const url = directMediaPreviewUrl(current?.preview_url || current?.image_url || currentReferenceUrl);
  if (!url || current?.unavailable || state.failedMediaPreviewUrls.has(url)) {
    return { status: "invalid", url };
  }
  return { status: "ready", url };
}

function verifyPersonaReferenceImage(url, timeoutMs = 5000) {
  const cleanUrl = String(url || "").trim();
  if (!cleanUrl || state.failedMediaPreviewUrls.has(cleanUrl)) return Promise.resolve(false);
  return new Promise((resolve) => {
    const image = new Image();
    let settled = false;
    const finish = (available) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      if (!available) state.failedMediaPreviewUrls.add(cleanUrl);
      resolve(Boolean(available));
    };
    const timer = window.setTimeout(() => finish(false), timeoutMs);
    image.onload = () => finish(image.naturalWidth > 0 && image.naturalHeight > 0);
    image.onerror = () => finish(false);
    image.decoding = "async";
    image.src = cleanUrl;
  });
}

async function ensurePersonaReferenceImageForMediaTask(persona) {
  const personaId = String(persona?.id || "").trim();
  if (!personaId) return false;
  const library = await loadPersonaImageLibrary(personaId, { force: true });
  const candidate = personaReferenceImageCandidate(library);
  if (candidate.status === "ready" && await verifyPersonaReferenceImage(candidate.url)) return true;
  const invalid = candidate.status !== "missing";
  const goToPersonaImage = await openConsoleModal({
    title: "请先生成人设图",
    message: invalid
      ? "当前人设图已失效或无法加载。请重新生成人设图，再继续生成推文配图。"
      : "当前人设还没有可用人设图。请先生成人设图，再继续生成推文配图。",
    confirmText: "去生成人设图",
    cancelText: "取消",
    modalKey: "persona-media-image-required",
  });
  if (goToPersonaImage) await openPersonaImageGeneration(personaId);
  return false;
}

async function loadPersonaPublishHistory(personaId, { force = false } = {}) {
  const key = String(personaId || "").trim();
  if (!key) return [];
  if (!force && Array.isArray(state.personaPublishHistories[key])) return state.personaPublishHistories[key];
  if (!force && state.personaFetches.publishHistories[key]) return state.personaFetches.publishHistories[key];
  const fallbackPersona = state.personas.find((item) => String(item.id) === key) || null;
  const fallbackRows = sortPersonaPublishHistory(Array.isArray(fallbackPersona?.publish_history) ? fallbackPersona.publish_history : []);
  const request = api(`/api/persona_dashboard/personas/${encodeURIComponent(key)}/publish_history`)
    .catch(() => ({ publish_history: fallbackRows }))
    .then((data) => {
      const apiRows = Array.isArray(data.publish_history) ? data.publish_history : [];
      const rows = sortPersonaPublishHistory(apiRows.length ? apiRows : fallbackRows);
      state.personaPublishHistories[key] = rows;
      schedulePersonaDetailRender(key);
      return rows;
    })
    .finally(() => {
      if (state.personaFetches.publishHistories[key] === request) delete state.personaFetches.publishHistories[key];
    });
  state.personaFetches.publishHistories[key] = request;
  return request;
}

async function loadAutomationTasksShared({ force = false } = {}) {
  if (state.socialTasksFetch) {
    if (!force) return state.socialTasksFetch;
    await state.socialTasksFetch.catch(() => {});
  }
  const previousById = new Map((state.socialTasks || []).map((task) => [String(task?.id || ""), task]));
  const publishPolicyRequestSeq = beginDailyPublishPolicyRequest();
  const request = api("/api/persona_dashboard/automation/tasks?limit=80")
    .catch((error) => ({ tasks: tenantArrayFallback(error, state.socialTasks) }))
    .then(async (data) => {
      const tasks = Array.isArray(data.tasks) ? data.tasks : [];
      state.socialTasks = tasks;
      const mobilePublishWasTracked = Boolean(state.mobilePublishingTaskId);
      const mobilePublishStillActive = Boolean(mobilePublishingTask());
      if (data?.publish_policy) updateDailyPublishPolicy(data.publish_policy, { requestSeq: publishPolicyRequestSeq });
      syncSocialTaskToasts(tasks);
      updateAccountStatusViews();
      await refreshPersonaAfterPublishTasks(tasks, previousById);
      if (mobilePublishWasTracked && !mobilePublishStillActive && state.activeModule === "publishing") {
        window.setTimeout(() => renderSimpleFlowModule("publishing"), 0);
      }
      return { tasks };
    })
    .finally(() => {
      if (state.socialTasksFetch === request) state.socialTasksFetch = null;
    });
  state.socialTasksFetch = request;
  return request;
}

async function loadAutomationPlansShared({ force = false } = {}) {
  if (state.automationPlansFetch) {
    if (!force) return state.automationPlansFetch;
    await state.automationPlansFetch.catch(() => {});
  }
  state.automationPlansLoading = true;
  state.automationPlansError = "";
  const request = api("/api/persona_dashboard/automation/plans")
    .then((data) => {
      state.automationPlans = Array.isArray(data.plans) ? data.plans : [];
      state.automationPlansLoaded = true;
      return state.automationPlans;
    })
    .catch((error) => {
      state.automationPlans = tenantArrayFallback(error, state.automationPlans);
      state.automationPlansLoaded = true;
      state.automationPlansError = String(error?.detail || error?.message || "请稍后重试");
      throw error;
    })
    .finally(() => {
      state.automationPlansLoading = false;
      if (state.automationPlansFetch === request) state.automationPlansFetch = null;
      if (state.activeModule === "publishing" && normalizedPublishMode(state.simpleBranches.publishing) === "automation_tasks") {
        renderSimpleFlowModule("publishing");
      }
    });
  state.automationPlansFetch = request;
  return request;
}

function automationPlanSubmissionItem(item = {}, platform = "threads") {
  let params = cloneAutomationPlanPayload(item.params || {});
  let taskType = item.taskType === "threads_reply_comment" || item.taskType === "threads_reply_hot"
    ? "threads_auto_reply"
    : item.taskType;
  taskType = automationPlanTaskTypeForPlatform(taskType, platform);
  if (["threads_auto_reply", "instagram_auto_reply"].includes(taskType)) {
    params.reply_scope = String(params.reply_scope || (item.taskType === "threads_reply_hot" ? "hot_posts" : "comments"));
  }
  if (taskType === "normal_publish") {
    params = { publish_count: automationPlanNormalPublishCount(item) };
  }
  return {
    reservation_minutes: Number(item.reservationMinutes || 0),
    task_type: taskType,
    payload: params,
    priority: 50,
    max_retries: 2,
  };
}

function validateAutomationPlanDraft(draft, account) {
  const items = normalizeAutomationPlanReservations(draft?.items || []);
  if (!items.length) return "请至少添加一项自动化任务。";
  if (items.length > 49) return "单个自动化计划最多包含 49 项任务。";
  const platform = String(account?.platform || "").trim().toLowerCase();
  const allowed = new Set(automationPlanTaskOptions(platform).map(([value]) => value));
  const taskTypes = new Set();
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index];
    const taskType = String(item.taskType || "");
    const effectiveTaskType = automationPlanTaskTypeForPlatform(taskType, platform);
    const params = item.params || {};
    if (!taskType) return `请选择第 ${index + 1} 项要执行的任务。`;
    if (!allowed.has(effectiveTaskType)) return `第 ${index + 1} 项任务不适用于当前执行账号。`;
    const conflictKey = automationPlanConflictKey(effectiveTaskType);
    if (conflictKey && taskTypes.has(conflictKey)) return `同一账号不能重复添加${automationPlanTaskLabel(taskType)}。`;
    if (conflictKey) taskTypes.add(conflictKey);
    if (Number(item.reservationMinutes) < 0 || Number(item.reservationMinutes) > 1440 || Number(item.reservationMinutes) % 30 !== 0) {
      return `第 ${index + 1} 项预约时间无效。`;
    }
    if (index > 0 && Number(item.reservationMinutes) <= Number(items[index - 1].reservationMinutes)) {
      return "预约时间必须按列表顺序每次至少向后 30 分钟。";
    }
    if (["threads_reply_comment", "threads_reply_hot", "threads_warmup", "instagram_warmup"].includes(taskType) && !item.configured) {
      return `请先打开第 ${index + 1} 项的原任务配置并点击“添加该任务”。`;
    }
    if (taskType === "normal_publish" && (!item.configured || !Number.isInteger(Number(params.publish_count)) || Number(params.publish_count) < 1 || Number(params.publish_count) > 5)) {
      return `请设置第 ${index + 1} 项普通任务的发布数量。`;
    }
    if (taskType === "publish_post" && !String(params.content || "").trim()) {
      return `请填写第 ${index + 1} 项发布内容。`;
    }
    if (["browse_profile", "comment_post", "reply_comment", "like_post", "share_post", "repost_post"].includes(taskType)
      && !String(params.target_url || "").trim()) {
      return `请填写第 ${index + 1} 项任务的目标 URL 或用户名。`;
    }
    if (["comment_post", "reply_comment"].includes(taskType) && !String(params.content || "").trim()) {
      return `请填写第 ${index + 1} 项任务的执行内容。`;
    }
  }
  return "";
}

async function submitAutomationPlan() {
  if (state.automationPlanPending) return;
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择人设。", false);
    return;
  }
  const { draft, key } = currentAutomationPlanDraft(persona);
  const account = await choosePublishPlatformAccount(persona, {
    title: "选择执行平台",
    message: "选择本次自动化计划的执行平台，确认后才会创建并开始执行。",
    confirmText: "创建并执行",
    modalKey: "automation-plan-platform-picker",
    persistSelection: false,
    confirmOnPlatformSelect: false,
  });
  if (!account) return;
  const validationError = validateAutomationPlanDraft(draft, account);
  if (validationError) {
    const invalidIndex = draft.items.findIndex((item) => (
      (item.taskType === "normal_publish" && (!item.configured || automationPlanNormalPublishCount(item) < 1))
      || (item.taskType === "publish_post" && !String(item.params?.content || "").trim())
      || (["browse_profile", "comment_post", "reply_comment", "like_post", "share_post", "repost_post"].includes(item.taskType)
        && !String(item.params?.target_url || "").trim())
      || (["comment_post", "reply_comment"].includes(item.taskType) && !String(item.params?.content || "").trim())
    ));
    if (invalidIndex >= 0) draft.items[invalidIndex].expanded = true;
    renderSimpleFlowModule("publishing");
    showMsg("commandMsg", validationError, false);
    return;
  }
  state.automationPlanPending = true;
  renderSimpleFlowModule("publishing");
  try {
    const result = await api("/api/persona_dashboard/automation/plans", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        persona_id: persona.id,
        account_id: account.id,
        platform: account.platform || "threads",
        mode: draft.mode,
        items: draft.items.map((item) => automationPlanSubmissionItem(item, account.platform || "threads")),
      }),
    });
    state.automationPlans = [result.plan, ...state.automationPlans.filter((plan) => String(plan.id) !== String(result.plan?.id))].filter(Boolean);
    state.personaPublishAccountIds[String(persona.id || "")] = String(account.id || "");
    delete state.automationPlanDrafts[key];
    const selectedKey = automationPlanDraftKey(persona.id, account.id);
    state.automationPlanDrafts[selectedKey] = createAutomationPlanDraft(account.id);
    state.automationPlanDrafts[selectedKey].mode = draft.mode;
    showMsg("commandMsg", `${draft.mode === "loop" ? "循环" : "列表"}自动化计划已创建。`, true);
    await loadAutomationPlansShared({ force: true });
  } finally {
    state.automationPlanPending = false;
    renderSimpleFlowModule("publishing");
  }
}

async function cancelAutomationPlan(planId = "") {
  const cleanPlanId = String(planId || "").trim();
  if (!cleanPlanId) return;
  const confirmed = await openConsoleModal({
    title: "停止自动化计划？",
    message: "未执行的预约任务会一并停止；正在执行的任务会收到停止指令。",
    confirmText: "停止计划",
    cancelText: "继续执行",
    modalKey: `cancel-automation-plan-${cleanPlanId}`,
  });
  if (!confirmed) return;
  const result = await api(`/api/persona_dashboard/automation/plans/${encodeURIComponent(cleanPlanId)}/cancel`, { method: "POST" });
  await Promise.all([
    loadAutomationTasksShared({ force: true }),
    loadAutomationPlansShared({ force: true }),
  ]);
  if (result?.plan) {
    state.automationPlans = [
      result.plan,
      ...state.automationPlans.filter((plan) => String(plan?.id || "") !== cleanPlanId),
    ];
    if (state.activeModule === "publishing" && normalizedPublishMode(state.simpleBranches.publishing) === "automation_tasks") {
      renderSimpleFlowModule("publishing");
    }
  }
  showMsg("commandMsg", "自动化计划已停止。", true);
}

async function deleteAutomationPlanRecord(planId = "") {
  const cleanPlanId = String(planId || "").trim();
  const plan = state.automationPlans.find((item) => String(item?.id || "") === cleanPlanId);
  if (!cleanPlanId || !plan || !automationPlanCanDelete(plan) || state.automationPlanDeleting) return;
  const confirmed = await openConsoleModal({
    title: "删除计划记录？",
    message: "该计划及关联的任务、执行日志会一并删除，此操作不可恢复。",
    confirmText: "删除记录",
    cancelText: "取消",
    danger: true,
    modalKey: `delete-automation-plan-${cleanPlanId}`,
  });
  if (!confirmed) return;
  state.automationPlanDeleting = true;
  renderSimpleFlowModule("publishing");
  try {
    await api(`/api/persona_dashboard/automation/plans/${encodeURIComponent(cleanPlanId)}`, { method: "DELETE" });
    state.automationPlanSelectedIds.delete(cleanPlanId);
    state.automationPlans = state.automationPlans.filter((item) => String(item?.id || "") !== cleanPlanId);
    await Promise.all([
      loadAutomationTasksShared({ force: true }).catch(() => {}),
      loadAutomationPlansShared({ force: true }).catch(() => {}),
    ]);
    showMsg("commandMsg", "计划记录已删除。", true);
  } finally {
    state.automationPlanDeleting = false;
    renderSimpleFlowModule("publishing");
  }
}

async function deleteSelectedAutomationPlanRecords() {
  if (state.automationPlanDeleting) return;
  const summary = automationPlanSelectionSummary(selectedPersona());
  const planIds = summary.selectedIds;
  if (!planIds.length) {
    showMsg("commandMsg", "请先选择要删除的计划记录。", false);
    return;
  }
  const confirmed = await openConsoleModal({
    title: "批量删除计划记录？",
    message: `确认删除已选的 ${planIds.length} 条计划记录？关联任务和执行日志会一并删除，此操作不可恢复。`,
    confirmText: `删除 ${planIds.length} 条`,
    cancelText: "取消",
    danger: true,
    modalKey: "delete-selected-automation-plans",
  });
  if (!confirmed) return;
  state.automationPlanDeleting = true;
  renderSimpleFlowModule("publishing");
  try {
    await api("/api/persona_dashboard/automation/plans/batch-delete", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ plan_ids: planIds }),
    });
    const deletedIds = new Set(planIds);
    state.automationPlans = state.automationPlans.filter((plan) => !deletedIds.has(String(plan?.id || "")));
    planIds.forEach((id) => state.automationPlanSelectedIds.delete(id));
    await Promise.all([
      loadAutomationTasksShared({ force: true }).catch(() => {}),
      loadAutomationPlansShared({ force: true }).catch(() => {}),
    ]);
    showMsg("commandMsg", `已删除 ${planIds.length} 条计划记录。`, true);
  } finally {
    state.automationPlanDeleting = false;
    renderSimpleFlowModule("publishing");
  }
}

async function activateCreatedPersona(personaId, { group = "settings", step = "profile" } = {}) {
  setSelectedPersonaId(personaId || state.selectedPersonaId);
  setSelectedPersonaPostId("");
  state.personaGroup = group;
  if (group === "settings") state.personaPanels.settings = step;
  if (group === "content") state.personaPanels.content = step;
  state.personaCreateMode = false;
  await loadPersonas();
  await loadPersonaProfile(state.selectedPersonaId, { force: true }).catch(() => {});
  await loadPersonaDraftPosts(state.selectedPersonaId, { force: true }).catch(() => {});
  if (group === "settings" && step === "profile") {
    await loadPersonaImageLibrary(state.selectedPersonaId, { force: true }).catch(() => {});
  }
  renderConfirmSummary();
}

function scrollToPersonaImageGeneration() {
  window.requestAnimationFrame(() => {
    const target = $("personaImageGenerationSection") || document.querySelector("[data-persona-image-generation-section]");
    if (!target) return;
    target.scrollIntoView({ block: "start", behavior: "smooth" });
    target.querySelector("[data-persona-generate-image]")?.focus({ preventScroll: true });
  });
}

async function openPersonaImageGeneration(personaId) {
  const cleanPersonaId = String(personaId || state.selectedPersonaId || "").trim();
  if (!cleanPersonaId) {
    showMsg("commandMsg", "还没有可生成图片的人设。", false);
    return;
  }
  state.activeModule = "personas";
  const knownPersona = state.personas.some((persona) => String(persona?.id || "") === cleanPersonaId);
  if (!knownPersona) {
    await activateCreatedPersona(cleanPersonaId, { group: "settings", step: "profile" });
    await openPersonaProfileEditorModal();
    renderPersonaProfileEditorModal("image");
    return;
  }
  setSelectedPersonaId(cleanPersonaId);
  setSelectedPersonaPostId("");
  state.personaGroup = "settings";
  state.personaPanels.settings = "profile";
  state.personaCreateMode = false;
  await openPersonaProfileEditorModalWithOptions({ immediate: true });
  renderPersonaProfileEditorModal("image");
  void Promise.allSettled([
    loadPersonas(),
    loadPersonaProfile(cleanPersonaId, { force: true }),
    loadPersonaDraftPosts(cleanPersonaId, { force: true }),
    loadPersonaImageLibrary(cleanPersonaId, { force: true }),
  ]).then(() => {
    if (String(state.selectedPersonaId || "") !== cleanPersonaId) return;
    const modal = $("consoleModal");
    if (modal?.dataset.modalKey === "persona-profile-editor") renderPersonaProfileEditorModal("image");
    renderConfirmSummary();
  });
}

async function createPersonaArchive() {
  const busyKind = personaCreateBusyKind();
  if (busyKind) {
    showMsg("commandMsg", `${busyKind}正在执行，请等待当前任务完成。`, false);
    return;
  }
  const createState = snapshotPersonaCreateInputs();
  const name = String(createState.aiName || "").trim();
  const content = String(createState.aiPrompt || "").trim();
  if (!name) {
    showMsg("commandMsg", "请先填写人设名称。", false);
    return;
  }
  if (!content) {
    showMsg("commandMsg", "请先填写人设简介。", false);
    return;
  }
  state.personaCreateBusy.manual = true;
  state.personaCreateBusy.manualStartedAt = Date.now();
  renderPersonaCreateSurface();
  try {
    showMsg("commandMsg", "正在新建人设...", true);
    const result = await api("/api/persona_dashboard/personas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, content }),
    });
    state.personaCreate = defaultPersonaCreateState();
    showMsg("commandMsg", `人设已创建：${result.name || result.id || "-"}`, true);
    state.personaCreateMode = false;
    if (isPersonaCreateModalOpen()) closeConsoleModal(true);
    await activateCreatedPersona(result.id || state.selectedPersonaId, { group: "settings", step: "profile" });
    renderWorkspace();
  } finally {
    state.personaCreateBusy.manual = false;
    state.personaCreateBusy.manualStartedAt = 0;
    if (state.personaCreateMode) renderPersonaCreateSurface();
  }
}

async function suggestPersonaCreateKeywords() {
  const busyKind = personaCreateBusyKind();
  if (busyKind) {
    showMsg("commandMsg", `${busyKind}正在执行，请等待当前任务完成。`, false);
    return;
  }
  const createState = snapshotPersonaCreateInputs();
  const name = String(createState.aiName || "").trim();
  const prompt = String(createState.aiPrompt || "").trim();
  if (!name) {
    showMsg("commandMsg", "请先填写人设名称。", false);
    return;
  }
  if (!prompt) {
    showMsg("commandMsg", "请先填写人设提示词。", false);
    return;
  }
  const requestPayload = { name, prompt };
  const operationKey = personaStepOperationKey(
    "keywords",
    requestPayload,
    createState.aiKeywordOperationKey,
  );
  createState.aiKeywordOperationKey = operationKey;
  state.personaCreateBusy.keywords = true;
  state.personaCreateBusy.keywordsStartedAt = Date.now();
  state.personaCreateKeywordController = new AbortController();
  renderPersonaCreateSurface();
  try {
    showMsg("commandMsg", "正在提炼人设方向关键词...", true);
    const result = await apiWithTimeout("/api/persona_dashboard/personas/ai_keywords", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Idempotency-Key": operationKey,
      },
      body: JSON.stringify(requestPayload),
      signal: state.personaCreateKeywordController.signal,
    }, 90000);
    createState.aiStep = "keywords";
    createState.aiKeywords = Array.isArray(result.keywords) ? result.keywords : [];
    createState.aiSelectedKeywords = [];
    createState.aiResult = null;
    clearPersonaStepOperationKey("keywords", operationKey);
    createState.aiKeywordOperationKey = "";
    renderPersonaCreateSurface();
    showMsg("commandMsg", withBillingChargeMessage("已提炼出人设方向关键词。", result), true);
  } catch (error) {
    if (!personaStepErrorKeepsOperationKey(error)) {
      clearPersonaStepOperationKey("keywords", operationKey);
      createState.aiKeywordOperationKey = "";
    }
    if (error?.name === "AbortError" || error?.status === 499) {
      showMsg("commandMsg", "已取消关键词提炼。", true);
    } else {
      showMsg("commandMsg", error?.detail || "关键词提炼失败，请稍后重试。", false);
    }
  } finally {
    state.personaCreateBusy.keywords = false;
    state.personaCreateBusy.keywordsStartedAt = 0;
    state.personaCreateKeywordController = null;
    if (state.personaCreateMode) renderPersonaCreateSurface();
  }
}

function cancelPersonaCreateKeywords() {
  const controller = state.personaCreateKeywordController;
  if (controller && !controller.signal.aborted) {
    controller.abort(new DOMException("Request cancelled", "AbortError"));
  }
  state.personaCreateBusy.keywords = false;
  state.personaCreateBusy.keywordsStartedAt = 0;
  state.personaCreateKeywordController = null;
  showMsg("commandMsg", "已取消关键词提炼。", true);
  if (state.personaCreateMode) renderPersonaCreateSurface();
}

async function createPersonaArchiveWithAi() {
  const busyKind = personaCreateBusyKind();
  if (busyKind) {
    showMsg("commandMsg", `${busyKind}正在执行，请等待当前任务完成。`, false);
    return;
  }
  const createState = snapshotPersonaCreateInputs();
  const name = String(createState.aiName || "").trim();
  const prompt = String(createState.aiPrompt || "").trim();
  if (!name) {
    showMsg("commandMsg", "请先填写人设名称。", false);
    return;
  }
  if (!prompt) {
    showMsg("commandMsg", "请先填写人设提示词。", false);
    return;
  }
  const requestPayload = {
    name,
    prompt,
    selected_keywords: Array.isArray(createState.aiSelectedKeywords) ? createState.aiSelectedKeywords : [],
  };
  const operationKey = personaStepOperationKey(
    "create",
    requestPayload,
    createState.aiCreateOperationKey,
  );
  createState.aiCreateOperationKey = operationKey;
  state.personaCreateBusy.aiCreate = true;
  state.personaCreateBusy.aiCreateStartedAt = Date.now();
  renderPersonaCreateSurface();
  try {
    showMsg("commandMsg", "正在根据提示词生成人设...", true);
    const result = await api("/api/persona_dashboard/personas/ai_create", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Idempotency-Key": operationKey,
      },
      body: JSON.stringify(requestPayload),
    });
    const profile = result.profile || {};
    createState.aiStep = "created";
    createState.aiResult = {
      id: profile.id || "",
      name: profile.name || name,
      content: profile.content || "",
      selectedKeywords: Array.isArray(result.selected_keywords) ? result.selected_keywords : [],
    };
    await loadPersonas();
    if (createState.aiResult.id) {
      setSelectedPersonaId(createState.aiResult.id);
      await loadPersonaProfile(createState.aiResult.id, { force: true }).catch(() => {});
    }
    clearPersonaStepOperationKey("create", operationKey);
    createState.aiCreateOperationKey = "";
    renderPersonaCreateSurface();
    showMsg("commandMsg", withBillingChargeMessage(`AI 人设已创建：${createState.aiResult.name || "-"}`, result), true);
  } catch (error) {
    if (!personaStepErrorKeepsOperationKey(error)) {
      clearPersonaStepOperationKey("create", operationKey);
      createState.aiCreateOperationKey = "";
    }
    throw error;
  } finally {
    state.personaCreateBusy.aiCreate = false;
    state.personaCreateBusy.aiCreateStartedAt = 0;
    if (state.personaCreateMode) renderPersonaCreateSurface();
  }
}

function generatePersonaPayloadFromState(persona, profile = selectedPersonaProfile()) {
  const personaForm = personaFormState(persona.id);
  const form = personaForm.generate;
  const draft = normalizePersonaDraftForm(personaForm.draft);
  const defaults = personaGenerateDefaults();
  const batchMode = String(form.composeMode || "tweet") === "tweet_media";
  const count = batchMode
    ? Math.min(Math.max(Number(form.count || defaults.count), 1), PERSONA_GENERATE_MAX_COUNT)
    : PERSONA_GENERATE_DEFAULT_COUNT;
  const targetWords = Math.min(Math.max(Number(form.targetWords || defaults.targetWords), 10), 2000);
  form.count = count;
  form.targetWords = targetWords;
  const payload = {
    count,
    prompt: [String(draft.title || "").trim(), String(draft.content || "").trim()]
      .filter(Boolean)
      .join("\n"),
    platform: personaContentPlatform(persona),
    target_words: targetWords,
    content_time_slot: String(form.contentTimeSlot || "").trim(),
    writing_locale: PERSONA_WRITING_LOCALES.some(([value]) => value === String(form.writingLocale || ""))
      ? String(form.writingLocale)
      : PERSONA_DEFAULT_WRITING_LOCALE,
    selected_memory_ids: Array.isArray(form.selectedMemoryIds) ? form.selectedMemoryIds : [],
    selected_directions: personaPostDirectionState(persona.id, form.composeMode).selectedKeywords.slice(0, PERSONA_POST_DIRECTION_COUNT),
    selection_required: String(form.composeMode || "tweet") === "tweet",
  };
  const rewriteSourcePostId = String(draft.rewriteSourcePostId || draft.editingPostId || "").trim();
  const rewriteSourceContent = String(draft.content || "").trim();
  if (rewriteSourcePostId || rewriteSourceContent) {
    payload.rewrite_source_post_id = rewriteSourcePostId;
    payload.rewrite_source_title = String(draft.title || draft.originalTitle || "").trim();
    payload.rewrite_source_content = rewriteSourceContent || String(draft.originalContent || "").trim();
  }
  return payload;
}

function personaWritingLocaleLabel(locale, language = "zh-Hans") {
  const row = PERSONA_WRITING_LOCALES.find(([value]) => value === String(locale || ""))
    || PERSONA_WRITING_LOCALES[0];
  return String(language === "zh-Hant" ? row[2] : row[1]);
}

function renderPersonaWritingLocaleSelect(selectedLocale = PERSONA_DEFAULT_WRITING_LOCALE, disabled = false) {
  const normalized = PERSONA_WRITING_LOCALES.some(([value]) => value === String(selectedLocale || ""))
    ? String(selectedLocale)
    : PERSONA_DEFAULT_WRITING_LOCALE;
  const label = personaWritingLocaleLabel(normalized);
  return `<span class="persona-writing-locale" title="按当地常用口吻、节奏和排版生成推文">
    <label class="persona-writing-locale-select">
      <span class="sr-only">推文语言与地区口吻</span>
      <select id="personaWritingLocale" aria-label="推文语言与地区口吻" ${disabled ? "disabled" : ""}>
        ${PERSONA_WRITING_LOCALES.map(([value]) => `<option value="${esc(value)}" ${value === normalized ? "selected" : ""}>${esc(personaWritingLocaleLabel(value))}</option>`).join("")}
      </select>
    </label>
    <button type="button" class="persona-writing-locale-mobile" data-persona-writing-locale-open aria-label="选择推文语言与地区口吻" ${disabled ? "disabled" : ""}>${esc(label)}</button>
  </span>`;
}

async function openPersonaWritingLocalePicker() {
  const persona = selectedPersona();
  if (!persona) return;
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id).generate;
  const selectedLocale = PERSONA_WRITING_LOCALES.some(([value]) => value === String(form.writingLocale || ""))
    ? String(form.writingLocale)
    : PERSONA_DEFAULT_WRITING_LOCALE;
  const request = openConsoleModal({
    title: "选择推文语言",
    message: "生成或 AI 重写时，将按所选地区的日常口吻、节奏和排版表达。",
    contentHtml: `<div class="persona-writing-locale-options" role="listbox" aria-label="推文语言与地区口吻">
      ${PERSONA_WRITING_LOCALES.map(([value]) => `<button type="button" class="persona-writing-locale-option ${value === selectedLocale ? "is-selected" : ""}" data-persona-writing-locale-choice="${esc(value)}" role="option" aria-selected="${value === selectedLocale ? "true" : "false"}">
        <span>${esc(personaWritingLocaleLabel(value))}</span>
        ${value === selectedLocale ? renderAutomationPlanCheckIcon() : ""}
      </button>`).join("")}
    </div>`,
    cancelText: "取消",
    showConfirm: false,
    modalKey: "persona-writing-locale-picker",
  });
  const modal = $("consoleModal");
  modal?.addEventListener("click", (event) => {
    const option = event.target.closest("[data-persona-writing-locale-choice]");
    if (!option) return;
    closeConsoleModal(option.dataset.personaWritingLocaleChoice || null, modal);
  });
  const nextLocale = await request;
  if (!PERSONA_WRITING_LOCALES.some(([value]) => value === String(nextLocale || ""))) return;
  form.writingLocale = String(nextLocale);
  if ($("personaWritingLocale")) $("personaWritingLocale").value = String(nextLocale);
  renderPersonaDetail();
  renderConfirmSummary();
}

function personaGenerateRunState(personaId) {
  return state.personaGenerateRuns[String(personaId || "").trim()] || null;
}

function personaPostGenerationInteractionLocked() {
  return Object.keys(state.actionLocks || {}).some((key) => key.endsWith(":generate_posts"));
}

function personaPostGenerationConflictSelector() {
  return [
    "[data-view]",
    "[data-module]",
    "[data-workspace-view]",
    "[data-persona-select]",
    "[data-persona-group]",
    "[data-persona-step]",
    "[data-persona-content-tab]",
    "[data-persona-content-platform]",
    "[data-persona-compose-mode]",
    "[data-persona-generate-mode]",
    "[data-persona-route-step]",
    "[data-persona-create-post]",
    "[data-persona-open-publishing]",
    '[data-persona-post-bulk="execute"]',
    "[data-persona-run-automation]",
    "[data-persona-run-media-task]",
    "[data-persona-fetch-hot]",
    "[data-persona-import-hot-drafts]",
  ].join(",");
}

function syncPersonaPostGenerationInteractionLock() {
  const locked = personaPostGenerationInteractionLocked();
  document.querySelectorAll(personaPostGenerationConflictSelector()).forEach((button) => {
    if (!(button instanceof HTMLButtonElement)) return;
    if (locked) {
      if (button.getAttribute("data-persona-generation-locked") !== "true") {
        button.setAttribute("data-persona-generation-locked", "true");
        button.dataset.personaGenerationPreviousDisabled = button.disabled ? "true" : "false";
        button.dataset.personaGenerationPreviousTitle = button.getAttribute("title") || "";
        button.dataset.personaGenerationHadTitle = button.hasAttribute("title") ? "true" : "false";
        button.dataset.personaGenerationPreviousAriaDisabled = button.getAttribute("aria-disabled") || "";
        button.dataset.personaGenerationHadAriaDisabled = button.hasAttribute("aria-disabled") ? "true" : "false";
      }
      button.disabled = true;
      button.setAttribute("aria-disabled", "true");
      button.setAttribute("title", "AI 正在生成推文，完成后可继续操作");
      return;
    }
    if (button.getAttribute("data-persona-generation-locked") !== "true") return;
    button.disabled = button.dataset.personaGenerationPreviousDisabled === "true";
    if (button.dataset.personaGenerationHadAriaDisabled === "true") {
      button.setAttribute("aria-disabled", button.dataset.personaGenerationPreviousAriaDisabled || "false");
    } else {
      button.removeAttribute("aria-disabled");
    }
    if (button.dataset.personaGenerationHadTitle === "true") {
      button.setAttribute("title", button.dataset.personaGenerationPreviousTitle || "");
    } else {
      button.removeAttribute("title");
    }
    button.removeAttribute("data-persona-generation-locked");
    delete button.dataset.personaGenerationPreviousDisabled;
    delete button.dataset.personaGenerationPreviousTitle;
    delete button.dataset.personaGenerationHadTitle;
    delete button.dataset.personaGenerationPreviousAriaDisabled;
    delete button.dataset.personaGenerationHadAriaDisabled;
  });
}

function guardPersonaPostGenerationInteraction(target) {
  if (!personaPostGenerationInteractionLocked()) return false;
  const conflict = target?.closest?.(personaPostGenerationConflictSelector());
  if (!conflict) return false;
  showMsg("commandMsg", "AI 正在生成推文，请等待当前任务完成后再切换页面或执行其他任务。", false);
  return true;
}

function normalizePersonaGeneratedPreviewComposeMode(composeMode) {
  const mode = String(composeMode || "").trim();
  return mode === "tweet_media" ? "tweet_media" : (mode === "tweet" ? "tweet" : "");
}

function personaGeneratedPreviewKey(personaId, composeMode) {
  const cleanPersonaId = String(personaId || "").trim();
  const cleanComposeMode = normalizePersonaGeneratedPreviewComposeMode(composeMode);
  return cleanPersonaId && cleanComposeMode ? `${cleanPersonaId}:${cleanComposeMode}` : "";
}

function resolvedPersonaGeneratedPreviewComposeMode(personaId, composeMode = "") {
  const requestedMode = normalizePersonaGeneratedPreviewComposeMode(composeMode);
  if (requestedMode) return requestedMode;
  const formMode = normalizePersonaGeneratedPreviewComposeMode(
    personaFormState(personaId)?.generate?.composeMode,
  );
  return formMode || "tweet";
}

function personaGeneratedPreviewState(personaId, composeMode = "") {
  const previewKey = personaGeneratedPreviewKey(
    personaId,
    resolvedPersonaGeneratedPreviewComposeMode(personaId, composeMode),
  );
  return previewKey ? (state.personaGeneratedPreviews[previewKey] || null) : null;
}

function deletePersonaGeneratedPreview(personaId, composeMode = "") {
  const previewKey = personaGeneratedPreviewKey(
    personaId,
    resolvedPersonaGeneratedPreviewComposeMode(personaId, composeMode),
  );
  if (previewKey) delete state.personaGeneratedPreviews[previewKey];
}

function setPersonaGenerateRunState(personaId, patch = {}) {
  const key = String(personaId || "").trim();
  if (!key) return null;
  const isMediaRun = String(patch.kind || "").trim() === "media";
  const runStates = isMediaRun ? state.personaMediaRuns : state.personaGenerateRuns;
  const current = runStates[key] || {};
  const suppressToast = Boolean(patch.suppressToast || patch.silent);
  const nextPatch = { ...patch };
  delete nextPatch.suppressToast;
  delete nextPatch.silent;
  if (
    nextPatch.status === "running"
    && !nextPatch.startedAt
    && (current.status !== "running" || String(current.kind || "") !== String(nextPatch.kind || current.kind || ""))
  ) {
    nextPatch.startedAt = new Date().toISOString();
  }
  runStates[key] = {
    ...current,
    ...nextPatch,
    updatedAt: new Date().toISOString(),
  };
  const nextState = runStates[key];
  if (String(nextState.kind || "") === "draft") {
    const previewComposeMode = resolvedPersonaGeneratedPreviewComposeMode(
      key,
      nextState.composeMode || current.composeMode,
    );
    const previewKey = personaGeneratedPreviewKey(key, previewComposeMode);
    if (previewKey && String(nextState.status || "") === "running") {
      delete state.personaGeneratedPreviews[previewKey];
    } else if (previewKey && String(nextState.status || "") === "success") {
      state.personaGeneratedPreviews[previewKey] = {
        ...nextState,
        composeMode: previewComposeMode,
        visible: true,
      };
    }
  }
  if (!suppressToast) showPersonaGenerateRunToast(key, nextState);
  return nextState;
}

function clearPersonaGenerateRunState(personaId, composeMode = "") {
  const key = String(personaId || "").trim();
  if (!key) return;
  const runState = state.personaGenerateRuns[key] || null;
  const previewKey = personaGeneratedPreviewKey(
    key,
    resolvedPersonaGeneratedPreviewComposeMode(key, composeMode || runState?.composeMode),
  );
  if (String(state.personaGenerateRuns[key]?.kind || "") === "draft") {
    delete state.personaGenerateRuns[key];
  }
  if (previewKey && state.personaGeneratedPreviews[previewKey]) {
    state.personaGeneratedPreviews[previewKey].visible = false;
  }
}

function personaGenerateRunDisplay(persona, runState) {
  if (!persona || !runState) return null;
  const status = String(runState.status || "").trim();
  const kind = String(runState.kind || "draft").trim();
  const isRunning = status === "running";
  const isError = status === "error";
  const isSuccess = status === "success";
  const isDraft = kind === "draft";
  const rows = isSuccess && isDraft ? personaGeneratedPreviewPosts(persona, runState) : [];
  const fallbackSuccess = isDraft
    ? `图文草稿已生成 ${Number(runState.generatedCount || rows.length || 0)} 条`
    : "操作已完成";
  const label = String(runState.message || "").trim() || (isRunning
    ? (isDraft ? "图文草稿生成中" : "处理中")
    : (isError ? (isDraft ? "图文草稿生成失败" : "操作失败") : fallbackSuccess));
  const title = isRunning && isDraft
    ? `预计生成 ${Number(runState.count || 0) || personaGenerateDefaults().count} 条，目标约 ${Number(runState.targetWords || 0) || personaGenerateDefaults().targetWords} 字`
    : (isError ? String(runState.error || "请稍后重试。") : label);
  return { status, kind, isRunning, isError, isSuccess, isDraft, label, title };
}

function showPersonaGenerateRunToast(personaId, runState) {
  const persona = state.personas.find((item) => String(item?.id || "") === String(personaId || ""));
  const display = personaGenerateRunDisplay(persona, runState);
  if (!display?.label) return;
  const kind = String(runState?.kind || "").trim();
  const target = kind === "persona_image"
    ? {
      view: "workspace",
      module: "personas",
      personaId,
      action: "persona_image_generation",
    }
    : {
      view: "workspace",
      module: "tweet_generation",
      personaId,
    };
  const ok = !display.isError;
  const message = display.isError && runState?.error
    ? `${display.label}：${runState.error}`
    : display.label;
  showToast(message, ok, {
    key: `persona-generate:${personaId}:${display.kind}`,
    kind: display.isRunning ? "running" : (display.isError ? "error" : "success"),
    target,
  });
}

async function applyPersonaGeneratedCandidateTitle(personaId, post, requestedTitle = "") {
  const cleanPersonaId = String(personaId || "").trim();
  const cleanPostId = String(post?.id || "").trim();
  const title = String(requestedTitle || post?.title || "").trim();
  const content = String(post?.content || post?.full_content || "").trim();
  if (!cleanPersonaId || !cleanPostId || (!content && !title)) return post;
  return api(`/api/persona_dashboard/personas/${encodeURIComponent(cleanPersonaId)}/posts/${encodeURIComponent(cleanPostId)}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, content, media_paths: [], media_ops: [] }),
  });
}

async function applyPersonaGeneratedBatchTitles(personaId, posts = [], requestedTitle = "") {
  const rows = Array.isArray(posts) ? posts.filter((post) => String(post?.id || "").trim()) : [];
  const title = String(requestedTitle || "").trim();
  if (!rows.length || !title) return;
  for (const post of rows) {
    await applyPersonaGeneratedCandidateTitle(personaId, post, title);
  }
}

let pendingPersonaMediaScrollId = "";

function scrollPersonaMediaComposerIntoView(personaId, { focusEditPrompt = false } = {}) {
  const cleanPersonaId = String(personaId || "");
  if (String(pendingPersonaMediaScrollId) !== cleanPersonaId) return;
  window.requestAnimationFrame(() => {
    if (String(pendingPersonaMediaScrollId) !== cleanPersonaId) return;
    pendingPersonaMediaScrollId = "";
    if (!isPersonaWorkspaceModule() || String(selectedPersona()?.id || "") !== cleanPersonaId) return;
    const action = document.querySelector("[data-persona-run-media-task]");
    const composer = action?.closest(".persona-compose-media-side");
    if (!composer) return;
    const editPrompt = focusEditPrompt
      ? composer.querySelector(".persona-media-prompt-field.is-image-editing")
      : null;
    const target = editPrompt || composer;
    const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    const focusTarget = editPrompt?.querySelector("textarea") || action;
    focusTarget.focus({ preventScroll: true });
    const targetRect = target.getBoundingClientRect();
    const headerBottom = document.querySelector("[data-site-header]")?.getBoundingClientRect().bottom || 0;
    const lowerObstructions = [
      document.querySelector("[data-persona-draft-save-dock]")?.getBoundingClientRect().top,
      document.querySelector(".mobile-task-dock")?.getBoundingClientRect().top,
    ].filter((value) => Number.isFinite(value) && value > 0 && value < window.innerHeight);
    const viewportTop = headerBottom + 12;
    const viewportBottom = Math.min(window.innerHeight, ...lowerObstructions) - 12;
    const fullyVisible = targetRect.top >= viewportTop && targetRect.bottom <= viewportBottom;
    if (!fullyVisible) {
      target.scrollIntoView({
        block: editPrompt ? "center" : "start",
        behavior: reduceMotion ? "auto" : "smooth",
      });
    }
  });
}

async function resolvePersonaOrdinaryGeneratedCandidates(persona, taskId, generatedPosts = [], requestedTitle = "") {
  const rows = Array.isArray(generatedPosts) ? generatedPosts.filter((post) => String(post?.id || "").trim()) : [];
  const cleanTaskId = String(taskId || "").trim();
  if (!persona || !cleanTaskId || !rows.length) return { action: "", postId: "" };
  const selection = await openPersonaGeneratedSelectionModal(persona, rows);
  const selectedPost = rows.find((post) => String(post?.id || "").trim() === String(selection.postId || "").trim()) || null;
  const selectedPostId = selection.action && selectedPost ? String(selectedPost.id || "").trim() : "";
  const finalizePayload = { selected_post_id: selectedPostId };
  if (selectedPostId && String(requestedTitle || "").trim()) {
    finalizePayload.title = String(requestedTitle || "").trim();
  }
  let finalized;
  try {
    finalized = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/generate_posts/tasks/${encodeURIComponent(cleanTaskId)}/resolve`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(finalizePayload),
    });
  } catch (error) {
    if (Number(error?.status) === 409) {
      clearStoredPersonaPostGenerationTask(persona.id, cleanTaskId);
      clearPersonaGenerateRunState(persona.id);
      deletePersonaGeneratedPreview(persona.id, "tweet");
      personaFormState(persona.id).media.focusPostId = "";
      await loadPersonaDraftPosts(persona.id, { force: true }).catch(() => {});
      setPersonaPostSource("posts", persona);
      setSelectedPersonaPostId(personaDraftPosts(persona)[0]?.id || "");
      state.personaPanels.content = "posts";
      showMsg("commandMsg", "候选状态已失效，已刷新草稿库，请重新生成后再选择。", false);
      renderConfirmSummary();
      return { action: "conflict", postId: "" };
    }
    if (error && typeof error === "object") {
      error.personaCandidateResolutionPending = true;
      throw error;
    }
    throw { detail: String(error || "候选结果保存失败"), personaCandidateResolutionPending: true };
  }
  clearPersonaGenerateRunState(persona.id);
  deletePersonaGeneratedPreview(persona.id, "tweet");
  await loadPersonaDraftPosts(persona.id, { force: true });
  setPersonaPostSource("posts", persona);
  const finalizedPostId = String(finalized?.selected_post?.id || selectedPostId || "").trim();
  setSelectedPersonaPostId(finalizedPostId || personaDraftPosts(persona)[0]?.id || "");
  if (selection.action === "media" && selectedPostId) {
    const personaForm = personaFormState(persona.id);
    personaForm.generate.composeMode = "tweet";
    personaForm.media.operationMode = "generate";
    personaForm.media.contentMode = "draft";
    personaForm.media.focusPostId = finalizedPostId;
    state.personaPanels.content = "generate";
    pendingPersonaMediaScrollId = String(persona.id || "");
    showMsg("commandMsg", "已保留所选草稿，可以继续生成配图。", true);
  } else if (selection.action === "save" && selectedPostId) {
    personaFormState(persona.id).media.focusPostId = "";
    state.personaPanels.content = "posts";
    showMsg("commandMsg", "已保存所选草稿，其他候选已清理。", true);
  } else {
    personaFormState(persona.id).media.focusPostId = "";
    state.personaPanels.content = "generate";
    showMsg("commandMsg", "本次生成候选已放弃。", true);
  }
  renderConfirmSummary();
  return { action: selection.action, postId: finalizedPostId };
}

function personaPostGenerationTaskStorageKey(personaId) {
  const workspaceUserId = consoleUserId(ADMIN_WORKSPACE_USER_ID || state.currentUser?.id);
  const cleanPersonaId = String(personaId || "").trim();
  return workspaceUserId && cleanPersonaId
    ? `${PERSONA_POST_GENERATION_TASK_STORAGE_PREFIX}:${workspaceUserId}:${cleanPersonaId}`
    : "";
}

function storedPersonaPostGenerationComposeMode(record = {}) {
  const explicitMode = String(record?.context?.composeMode || "").trim();
  if (["tweet", "tweet_media"].includes(explicitMode)) return explicitMode;
  return record?.payload?.selection_required ? "tweet" : "tweet_media";
}

function storedPersonaPostGenerationTask(personaId) {
  const key = personaPostGenerationTaskStorageKey(personaId);
  if (!key) return null;
  try {
    const stored = JSON.parse(window.localStorage.getItem(key) || "null");
    const createdAt = Number(stored?.createdAt || 0);
    if (
      !stored
      || !String(stored.operationKey || "").trim()
      || !Number.isFinite(createdAt)
      || Date.now() - createdAt > 24 * 60 * 60 * 1000
    ) {
      window.localStorage.removeItem(key);
      return null;
    }
    return stored;
  } catch {
    try { window.localStorage.removeItem(key); } catch {}
    return null;
  }
}

function storePersonaPostGenerationTask(personaId, record = {}) {
  const key = personaPostGenerationTaskStorageKey(personaId);
  if (!key) return null;
  const stored = {
    ...record,
    personaId: String(personaId || "").trim(),
    operationKey: String(record.operationKey || "").trim(),
    taskId: String(record.taskId || "").trim(),
    createdAt: Number(record.createdAt || Date.now()),
    updatedAt: Date.now(),
  };
  try { window.localStorage.setItem(key, JSON.stringify(stored)); } catch {}
  return stored;
}

function clearStoredPersonaPostGenerationTask(personaId, taskId = "") {
  const key = personaPostGenerationTaskStorageKey(personaId);
  if (!key) return;
  try {
    if (taskId) {
      const stored = JSON.parse(window.localStorage.getItem(key) || "null");
      if (String(stored?.taskId || "").trim() !== String(taskId || "").trim()) return;
    }
    window.localStorage.removeItem(key);
  } catch {
    try { window.localStorage.removeItem(key); } catch {}
  }
}

function newPersonaPostGenerationOperationKey(personaId) {
  const randomPart = globalThis.crypto?.randomUUID?.()
    || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
  return `persona-post:${String(personaId || "").trim()}:${randomPart}`;
}

function personaPostGenerationErrorIsTransient(error) {
  const status = Number(error?.status);
  if (!Number.isFinite(status)) return true;
  return status === 0 || status === 408 || status === 429 || status === 499 || status >= 500;
}

async function preparePersonaPostDirections() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id);
  const composeMode = personaComposeDraftInputKey(form.generate.composeMode) || "tweet";
  const directionState = personaPostDirectionState(persona.id, composeMode);
  const requestSourceFingerprint = personaPostDirectionSourceFingerprint(form);
  const lockParts = ["persona", persona.id, "post_directions"];
  if (isActionLocked(...lockParts)) return;
  const payload = {
    input_title: String(form.draft?.title || "").trim(),
    input_content: String(form.draft?.content || "").trim(),
    platform: personaContentPlatform(persona),
    writing_locale: PERSONA_WRITING_LOCALES.some(([value]) => value === String(form.generate.writingLocale || ""))
      ? String(form.generate.writingLocale)
      : PERSONA_DEFAULT_WRITING_LOCALE,
    interface_language: currentLanguage(),
    previous_keywords: directionState.keywords.slice(0, PERSONA_POST_DIRECTION_COUNT),
  };
  const operationStep = `post-directions:${persona.id}:${composeMode}`;
  const operationKey = personaStepOperationKey(operationStep, payload);
  setActionLocked(lockParts, true);
  clearMsg("commandMsg");
  renderPersonaDetail();
  try {
    const result = await apiWithTimeout(
      `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/post_directions`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json", "Idempotency-Key": operationKey },
        body: JSON.stringify(payload),
      },
      120000,
    );
    const keywords = Array.isArray(result?.keywords)
      ? result.keywords.map((item) => String(item || "").trim()).filter(Boolean).slice(0, PERSONA_POST_DIRECTION_COUNT)
      : [];
    if (keywords.length !== PERSONA_POST_DIRECTION_COUNT) {
      throw { detail: "模型未返回 10 个有效推文方向，请重试。", status: 502 };
    }
    const latestForm = personaFormState(persona.id);
    const latestComposeMode = personaComposeDraftInputKey(latestForm.generate.composeMode) || "tweet";
    if (
      latestComposeMode !== composeMode
      || personaPostDirectionSourceFingerprint(latestForm) !== requestSourceFingerprint
    ) {
      clearPersonaStepOperationKey(operationStep, operationKey);
      showMsg("commandMsg", "输入内容已变化，本次方向结果未采用，请重新点击 AI 生成。", false);
      return;
    }
    const targetState = personaPostDirectionState(persona.id, composeMode);
    targetState.keywords = keywords;
    targetState.selectedKeywords = [];
    targetState.sourceFingerprint = requestSourceFingerprint;
    clearPersonaStepOperationKey(operationStep, operationKey);
    showMsg("commandMsg", withBillingChargeMessage("已生成 10 个推文方向，可单选或多选。", result), true);
  } catch (error) {
    if (!personaStepErrorKeepsOperationKey(error)) clearPersonaStepOperationKey(operationStep, operationKey);
    throw error;
  } finally {
    setActionLocked(lockParts, false);
    renderPersonaDetail();
  }
}

async function handlePersonaGeneratePrimaryAction() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const form = personaFormState(persona.id);
  const editingPost = Boolean(String(form.draft?.editingPostId || "").trim());
  const storedTask = storedPersonaPostGenerationTask(persona.id);
  const directionState = personaPostDirectionState(persona.id, form.generate.composeMode);
  if (editingPost || storedTask || directionState.selectedKeywords.length) {
    await generatePersonaDraftPosts();
    return;
  }
  await preparePersonaPostDirections();
}

async function generatePersonaDraftPosts() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const lockParts = ["persona", persona.id, "generate_posts"];
  if (isActionLocked(...lockParts)) {
    showMsg("commandMsg", "当前人设正在生成草稿，请等待本次生成完成。", false);
    return;
  }
  snapshotPersonaCurrentForm();
  const profile = selectedPersonaProfile();
  const preflight = personaGeneratePreflight();
  if (!preflight.ready) {
    showMsg("commandMsg", `${preflight.issues.join(" / ")}，请先补齐配置。`, false);
    return;
  }
  const currentPayload = generatePersonaPayloadFromState(persona, profile);
  const storedTask = storedPersonaPostGenerationTask(persona.id);
  const payload = storedTask?.payload && typeof storedTask.payload === "object"
    ? storedTask.payload
    : currentPayload;
  const composeMode = storedTask
    ? storedPersonaPostGenerationComposeMode(storedTask)
    : String(personaFormState(persona.id).generate.composeMode || "tweet");
  const requestedTitle = String(storedTask?.context?.requestedTitle || personaFormState(persona.id).draft.title || "").trim();
  const isRewriteRun = Boolean(storedTask?.context?.isRewriteRun ?? String(payload.rewrite_source_content || "").trim());
  const operationKey = String(storedTask?.operationKey || newPersonaPostGenerationOperationKey(persona.id));
  const taskContext = {
    composeMode,
    requestedTitle,
    isRewriteRun,
    count: payload.count,
    targetWords: payload.target_words,
    prompt: payload.prompt,
    selectionRequired: Boolean(payload.selection_required),
  };
  setPersonaGenerateRunState(persona.id, {
    kind: isRewriteRun ? "rewrite" : "draft",
    status: "running",
    message: isRewriteRun ? "正在 AI 重写当前推文" : "正在按当前人设生成图文草稿",
    count: payload.count,
    targetWords: payload.target_words,
    prompt: payload.prompt,
    composeMode,
    posts: [],
    postIds: [],
    error: "",
    startedAt: new Date().toISOString(),
  });
  clearMsg("commandMsg");
  setActionLocked(lockParts, true);
  try {
    const generateButton = document.querySelector("[data-persona-generate-posts]");
    if (generateButton) {
      generateButton.disabled = true;
      generateButton.setAttribute("aria-busy", "true");
      generateButton.innerHTML = renderBusyButtonContent(
        isRewriteRun ? "正在重新生成" : "正在生成草稿",
        true,
        actionLockStartedAt(...lockParts),
      );
    }
    let taskRecord = storePersonaPostGenerationTask(persona.id, {
      ...(storedTask || {}),
      operationKey,
      payload,
      context: taskContext,
    });
    let task = null;
    if (!String(taskRecord?.taskId || "").trim()) {
      const accepted = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/generate_posts`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Idempotency-Key": operationKey },
        body: JSON.stringify(payload),
      });
      const taskId = String(accepted?.task_id || accepted?.task?.id || "").trim();
      if (!taskId) throw { detail: "生成任务已提交，但服务端未返回任务编号。", status: 502 };
      task = accepted?.task || null;
      taskRecord = storePersonaPostGenerationTask(persona.id, { ...taskRecord, taskId });
    }
    await watchPersonaPostGenerationTask(persona, taskRecord, task);
  } catch (error) {
    if (error?.stale) return;
    if (error?.personaCandidateResolutionPending) {
      setPersonaGenerateRunState(persona.id, {
        kind: isRewriteRun ? "rewrite" : "draft",
        status: "error",
        message: "候选结果尚未保存，点击生成按钮可重新选择",
        error: error.detail || error.message || "候选结果保存失败",
      });
      return;
    }
    if (personaPostGenerationErrorIsTransient(error)) {
      setPersonaGenerateRunState(persona.id, {
        kind: isRewriteRun ? "rewrite" : "draft",
        status: "running",
        message: "连接暂时中断，后台仍可能在生成；再次点击可恢复同一任务",
        error: "",
      });
      return;
    }
    clearStoredPersonaPostGenerationTask(persona.id);
    setPersonaGenerateRunState(persona.id, {
      kind: isRewriteRun ? "rewrite" : "draft",
      status: "error",
      message: "图文草稿生成失败",
      error: error.detail || error.message || "生成失败",
    });
    throw error;
  } finally {
    setActionLocked(lockParts, false);
    if (isPersonaWorkspaceModule()) {
      cancelScheduledPersonaDetailRender();
      renderPersonaDetail();
    }
    scrollPersonaMediaComposerIntoView(persona.id);
  }
}

async function completePersonaPostGenerationTask(persona, task, context = {}) {
  const result = {
    ...(task?.output && typeof task.output === "object" ? task.output : {}),
    billing: task?.output?.billing || task?.billing || {},
  };
  const generatedPosts = Array.isArray(result.posts) ? result.posts : [];
  const generatedIds = new Set(generatedPosts.map((post) => String(post?.id || "")).filter(Boolean));
  const selectionRequired = Boolean(context.selectionRequired)
    || generatedPosts.some((post) => Boolean(post?.generation_candidate));
  const isRewriteRun = Boolean(context.isRewriteRun);
  const composeMode = String(context.composeMode || (selectionRequired ? "tweet" : "tweet_media"));
  const requestedTitle = String(context.requestedTitle || "").trim();
  const isActivePersona = String(selectedPersona()?.id || "").trim() === String(persona.id || "").trim();
  setPersonaGenerateRunState(persona.id, {
    kind: isRewriteRun ? "rewrite" : "draft",
    status: "success",
    message: withBillingChargeMessage(
      isRewriteRun
        ? `已重写生成 ${result.generated_count || generatedPosts.length || 0} 条推文候选`
        : `已生成 ${result.generated_count || generatedPosts.length || 0} 条图文草稿`,
      result,
    ),
    generatedCount: result.generated_count || generatedPosts.length || 0,
    posts: generatedPosts,
    postIds: Array.from(generatedIds),
    composeMode,
    selectionRequired,
    error: "",
  });
  if (generatedPosts.length) clearPersonaDraftComposerInputs(persona.id, composeMode);
  if (selectionRequired && generatedPosts.length) {
    await resolvePersonaOrdinaryGeneratedCandidates(persona, task?.id, generatedPosts, requestedTitle);
  } else {
    await applyPersonaGeneratedBatchTitles(persona.id, generatedPosts, requestedTitle);
    await loadPersonaDraftPosts(persona.id, { force: true });
    const latestGenerated = personaDraftPosts(persona).find((post) => generatedIds.has(String(post?.id || "")));
    if (isActivePersona) {
      setSelectedPersonaPostId(latestGenerated?.id || generatedPosts[0]?.id || "");
      setPersonaPostSource("posts", persona);
    }
  }
  if (isActivePersona) renderConfirmSummary();
}

async function watchPersonaPostGenerationTask(persona, record, initialTask = null) {
  const personaId = String(persona?.id || record?.personaId || "").trim();
  const taskId = String(record?.taskId || initialTask?.id || "").trim();
  if (!personaId || !taskId) throw { detail: "缺少推文生成任务编号。", status: 502 };
  if (state.personaGenerateTaskWatchers[personaId]) {
    return state.personaGenerateTaskWatchers[personaId];
  }
  const requestGeneration = tenantStateGeneration;
  const watcher = (async () => {
    let task = initialTask;
    while (requestGeneration === tenantStateGeneration && !consoleBoundaryNavigationActive) {
      if (!task) {
        try {
          const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(personaId)}/generate_posts/tasks/${encodeURIComponent(taskId)}`);
          task = result?.task || null;
        } catch (error) {
          if (!personaPostGenerationErrorIsTransient(error)) throw error;
          setPersonaGenerateRunState(personaId, {
            kind: record?.context?.isRewriteRun ? "rewrite" : "draft",
            status: "running",
            message: "连接暂时中断，后台仍在生成，正在恢复任务状态",
            error: "",
            suppressToast: true,
          });
          await sleep(1500);
          continue;
        }
      }
      const status = String(task?.status || "queued").trim();
      if (status === "success") {
        await completePersonaPostGenerationTask(persona, task, record?.context || {});
        clearStoredPersonaPostGenerationTask(personaId, taskId);
        return task;
      }
      if (status === "failed" || status === "cancelled") {
        clearStoredPersonaPostGenerationTask(personaId, taskId);
        throw {
          detail: String(task?.error || (status === "cancelled" ? "推文生成任务已取消。" : "推文生成失败。")),
          status: 422,
        };
      }
      setPersonaGenerateRunState(personaId, {
        kind: record?.context?.isRewriteRun ? "rewrite" : "draft",
        status: "running",
        message: status === "running"
          ? "AI 正在后台生成推文，可安全切换页面"
          : "推文生成任务已进入队列",
        count: Number(record?.context?.count || 0),
        targetWords: Number(record?.context?.targetWords || 0),
        prompt: String(record?.context?.prompt || ""),
        composeMode: storedPersonaPostGenerationComposeMode(record),
        error: "",
        suppressToast: true,
      });
      task = null;
      await sleep(1200);
    }
    throw { detail: "会话已切换，停止跟踪原任务。", status: 409, stale: true };
  })();
  state.personaGenerateTaskWatchers[personaId] = watcher;
  try {
    return await watcher;
  } finally {
    if (state.personaGenerateTaskWatchers[personaId] === watcher) {
      delete state.personaGenerateTaskWatchers[personaId];
    }
  }
}

function restorePersonaPostGenerationTasks(personaId = "") {
  const cleanPersonaId = String(personaId || state.selectedPersonaId || "").trim();
  const persona = state.personas.find((item) => String(item?.id || "").trim() === cleanPersonaId);
  const record = persona ? storedPersonaPostGenerationTask(cleanPersonaId) : null;
  const taskId = String(record?.taskId || "").trim();
  if (!persona || !taskId || state.personaGenerateTaskWatchers[cleanPersonaId]) return null;
  const lockParts = ["persona", cleanPersonaId, "generate_posts"];
  setActionLocked(lockParts, true, record?.createdAt);
  setPersonaGenerateRunState(cleanPersonaId, {
    kind: record?.context?.isRewriteRun ? "rewrite" : "draft",
    status: "running",
    message: "正在恢复后台推文生成任务",
    count: Number(record?.context?.count || 0),
    targetWords: Number(record?.context?.targetWords || 0),
    prompt: String(record?.context?.prompt || ""),
    composeMode: storedPersonaPostGenerationComposeMode(record),
    error: "",
    suppressToast: true,
  });
  if (isPersonaWorkspaceModule()) renderPersonaDetail();
  return watchPersonaPostGenerationTask(persona, record)
    .catch((error) => {
      if (!error?.stale) {
        setPersonaGenerateRunState(cleanPersonaId, {
          kind: record?.context?.isRewriteRun ? "rewrite" : "draft",
          status: "error",
          message: "图文草稿生成失败",
          error: error?.detail || error?.message || "生成失败",
        });
      }
    })
    .finally(() => {
      setActionLocked(lockParts, false);
      if (isPersonaWorkspaceModule()) {
        cancelScheduledPersonaDetailRender();
        renderPersonaDetail();
      }
      scrollPersonaMediaComposerIntoView(cleanPersonaId);
    });
}

async function createPersonaDraftPost() {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id).draft;
  const title = String(form.title || "").trim();
  const content = String(form.content || "").trim();
  const editingPostId = String(form.editingPostId || "").trim();
  const editingSource = form.editingSource === "favorites" ? "favorites" : "posts";
  const queuedMediaOps = editingPostId && Array.isArray(form.mediaOps) ? [...form.mediaOps] : [];
  const pendingUploadState = captureUploadDropzoneState("personaPostMediaUploadFiles");
  const pendingTaskUploadState = captureUploadDropzoneState("personaMediaTaskFiles");
  const pendingMediaFiles = [];
  const seenPendingMedia = new Set();
  for (const file of [
    ...pendingUploadState.files,
    ...(!editingPostId ? pendingTaskUploadState.files : []),
  ]) {
    const signature = uploadFileSignature(file);
    if (!file || (signature && seenPendingMedia.has(signature))) continue;
    if (signature) seenPendingMedia.add(signature);
    pendingMediaFiles.push(file);
  }
  const currentMediaItems = editingPostId && Array.isArray(form.mediaItems) ? form.mediaItems : [];
  const hasExistingMedia = Boolean(editingPostId && currentMediaItems.length);
  const hasMediaContent = pendingMediaFiles.length > 0 || hasExistingMedia;
  if (!content && !hasMediaContent) {
    showMsg("commandMsg", "请填写推文正文或上传至少一个媒体文件。", false);
    return;
  }
  const initialMediaPaths = !editingPostId && pendingMediaFiles.length
    ? await uploadAutomationMedia(pendingMediaFiles, "commandMsg")
    : [];
  if (!editingPostId && pendingMediaFiles.length && !initialMediaPaths.length) {
    showMsg("commandMsg", "媒体上传失败，请重新选择文件后再保存。", false);
    return;
  }
  const preparedMediaOps = editingPostId
    ? await preparePersonaDraftMediaOps(queuedMediaOps, pendingMediaFiles)
    : [];
  showMsg("commandMsg", editingPostId ? `正在保存${editingSource === "favorites" ? "收藏" : "草稿"}修改...` : "正在保存推文草稿...", true);
  const createPath = `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts`;
  const updatePath = editingPostId
    ? `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/${editingSource === "favorites" ? "favorites" : "posts"}/${encodeURIComponent(editingPostId)}`
    : "";
  let recreatedMissingEdit = false;
  let result;
  try {
    result = await api(editingPostId ? updatePath : createPath, {
      method: editingPostId ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title,
        content,
        platform: personaContentPlatform(persona),
        media_paths: initialMediaPaths,
        media_ops: preparedMediaOps,
      }),
    });
  } catch (error) {
    const missingEdit = editingPostId
      && Number(error?.status || 0) === 404
      && /(?:post not found|草稿已发布|草稿.*不存在)/i.test(String(error?.detail || error?.message || ""));
    if (!missingEdit) throw error;
    let recreatedMediaPaths = [];
    try {
      recreatedMediaPaths = JSON.parse(String(form.originalMediaSignature || ""))
        .map((item) => String(item?.url || "").trim())
        .filter((path) => path && !/^(?:blob:|data:|https?:|\/api\/)/i.test(path));
    } catch (_) {
      recreatedMediaPaths = [];
    }
    for (const op of preparedMediaOps) {
      const paths = Array.from(op.media_paths || []).map((path) => String(path || "").trim()).filter(Boolean);
      const index = Number(op.index ?? -1);
      if (op.type === "append") paths.forEach((path) => { if (!recreatedMediaPaths.includes(path)) recreatedMediaPaths.push(path); });
      else if (op.type === "replace" && paths.length && index >= 0 && index < recreatedMediaPaths.length) recreatedMediaPaths.splice(index, 1, ...paths);
      else if (op.type === "delete" && index >= 0 && index < recreatedMediaPaths.length) recreatedMediaPaths.splice(index, 1);
      else if (op.type === "move") {
        const fromIndex = Number(op.from_index ?? -1);
        const toIndex = Number(op.to_index ?? -1);
        if (fromIndex >= 0 && toIndex >= 0 && fromIndex < recreatedMediaPaths.length && toIndex < recreatedMediaPaths.length && fromIndex !== toIndex) {
          recreatedMediaPaths.splice(toIndex, 0, recreatedMediaPaths.splice(fromIndex, 1)[0]);
        }
      }
    }
    result = await api(createPath, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title,
        content,
        platform: personaContentPlatform(persona),
        media_paths: recreatedMediaPaths,
        media_ops: [],
      }),
    });
    recreatedMissingEdit = true;
  }
  const savedPostId = result.id || editingPostId || "";
  clearUploadDropzoneState("personaPostMediaUploadFiles", pendingUploadState.stateKey);
  if (!editingPostId) clearUploadDropzoneState("personaMediaTaskFiles", pendingTaskUploadState.stateKey);
  setSelectedPersonaPostId(savedPostId);
  setPersonaPostSource(editingPostId && !recreatedMissingEdit ? editingSource : "posts", persona);
  state.personaPanels.content = "posts";
  clearPersonaDraftComposerInputs(persona.id, personaFormState(persona.id).generate.composeMode);
  await Promise.all([
    loadPersonaDraftPosts(persona.id, { force: true }),
    loadPersonaFavoritePosts(persona.id, { force: true }).catch(() => []),
  ]);
  renderPersonaDetail();
  renderConfirmSummary();
  const mediaSuffix = queuedMediaOps.length
    ? `，并更新 ${queuedMediaOps.length} 项媒体操作`
    : (pendingMediaFiles.length ? `，并追加 ${pendingMediaFiles.length} 个媒体文件` : "");
  showMsg("commandMsg", recreatedMissingEdit
    ? `原草稿已结束，修改内容已另存为新草稿：${result.title || result.id || "-"}${mediaSuffix}`
    : (editingPostId ? `${editingSource === "favorites" ? "收藏" : "草稿"}已更新：${result.title || result.id || "-"}${mediaSuffix}` : `草稿已保存：${result.title || result.id || "-"}${mediaSuffix}`), true);
}

async function stashPersonaDraftEdit() {
  const persona = selectedPersona();
  if (!persona) return;
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id).draft;
  if (!String(form.editingPostId || "").trim()) return;
  form.stagedReferenceContent = String(form.content || "");
  renderPersonaDetail();
  showMsg("commandMsg", "\u5df2\u6682\u5b58\u4e3a\u914d\u56fe\u53c2\u8003\u6b63\u6587\uff1b\u4fee\u6539\u5c1a\u672a\u4fdd\u5b58\u3002", true);
}

async function preparePersonaHotKeywords(refresh = false) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return [];
  }
  const lockParts = ["persona", persona.id, "hot_keywords"];
  if (isActionLocked(...lockParts)) {
    showMsg("commandMsg", "热点抓取正在准备，请等待当前任务完成。", false);
    return [];
  }
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id).generate;
  form.hotSearchMode = normalizePersonaHotSearchMode(form.hotSearchMode);
  const existingKeywords = parsePersonaHotKeywordText(personaHotKeywordText(form, state.personaHotCandidateResults[String(persona.id)] || {}));
  const firstGenerate = existingKeywords.length < 6;
  setPersonaGenerateRunState(persona.id, {
    kind: "hot",
    status: "running",
    message: firstGenerate
      ? "首次生成搜索词，大约需要 10–20 秒，请稍候"
      : "正在复用已缓存的搜索词",
    error: "",
  });
  if (firstGenerate) {
    showMsg("commandMsg", "此人人设还没有搜索词。第一次会现场生成，大约 10–20 秒，请不要离开或重复点击。", true);
  }
  setActionLocked(lockParts, true);
  renderPersonaDetail();
  try {
    const result = await apiWithTimeout(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_keywords`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: String(form.hotPrompt || "").trim(),
        refresh: Boolean(refresh),
        search_mode: form.hotSearchMode,
        writing_locale: PERSONA_WRITING_LOCALES.some(([value]) => value === String(form.writingLocale || ""))
          ? String(form.writingLocale)
          : PERSONA_DEFAULT_WRITING_LOCALE,
        platform: personaContentPlatform(persona),
      }),
    }, 35000);
    const keywords = Array.isArray(result.keywords) ? result.keywords.map((item) => String(item || "").trim()).filter(Boolean) : [];
    const allKeywords = Array.isArray(result.all_keywords) ? result.all_keywords.map((item) => String(item || "").trim()).filter(Boolean) : keywords;
    form.hotKeywordText = formatPersonaHotKeywordText(keywords);
    state.personaHotCandidateResults[String(persona.id)] = {
      ...(state.personaHotCandidateResults[String(persona.id)] || {}),
      keywords,
      all_keywords: allKeywords,
      batch_index: Number(result.batch_index || 1),
      batch_count: Number(result.batch_count || 1),
      batch_uses: Number(result.batch_uses || 0),
      batch_max_uses: Number(result.batch_max_uses || 2),
      cycle: Number(result.cycle || 0),
      max_cycles: Number(result.max_cycles || 1),
      search_mode: normalizePersonaHotSearchMode(result.search_mode || form.hotSearchMode),
      warnings: Array.isArray(result.warnings) ? result.warnings : [],
      keyword_prepared_at: new Date().toISOString(),
    };
    setPersonaGenerateRunState(persona.id, {
      kind: "hot",
      status: keywords.length ? "success" : "error",
      message: keywords.length
        ? (firstGenerate ? `搜索词已生成 ${keywords.length} 个` : `已复用缓存搜索词 ${keywords.length} 个`)
        : "热点抓取准备失败",
      error: keywords.length ? "" : ((Array.isArray(result.warnings) && result.warnings[0]) || "未能生成有效的抓取策略"),
    });
    return keywords;
  } catch (error) {
    const detail = String(error?.detail || error?.message || "");
    setPersonaGenerateRunState(persona.id, {
      kind: "hot",
      status: "error",
      message: "热点抓取准备失败",
      error: /<\s*(?:!doctype|html|head|body|title)\b|\b(?:502|503|504)\b|bad gateway|gateway timeout|service unavailable/i.test(detail)
        ? "热点抓取准备服务暂时不可用，请稍后重试。"
        : (detail || "热点抓取准备失败"),
    });
    throw error;
  } finally {
    setActionLocked(lockParts, false);
    if (isPersonaWorkspaceModule()) {
      renderPersonaDetail();
      renderConfirmSummary();
    }
  }
}

async function fetchPersonaHotCandidates(refresh = false) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const lockParts = ["persona", persona.id, "hot_candidates"];
  if (isActionLocked(...lockParts) || isActionLocked("persona", persona.id, "hot_keywords")) {
    showMsg("commandMsg", "热点候选正在抓取，请等待当前抓取完成。", false);
    return;
  }
  const personaKey = String(persona.id || "").trim();
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id).generate;
  const previousCandidates = personaHotAllCandidates(persona);
  form.hotSearchMode = normalizePersonaHotSearchMode(form.hotSearchMode);
  let hotState = state.personaHotCandidateResults[String(persona.id)] || {};
  let keywords = parsePersonaHotKeywordText(personaHotKeywordText(form, hotState));
  const cooldown = await apiWithTimeout(
    `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_candidates/cooldown`,
    {},
    10000,
  );
  hotState = {
    ...hotState,
    cooldown: cooldown && typeof cooldown === "object" ? cooldown : {},
  };
  state.personaHotCandidateResults[String(persona.id)] = hotState;
  if (Boolean(cooldown?.active) && Number(cooldown?.remaining_seconds || 0) > 0) {
    showMsg("commandMsg", `热点抓取冷却中，请在 ${Number(cooldown.remaining_seconds)} 秒后重试。`, false);
    renderPersonaDetail();
    return;
  }
  try {
    const preparedKeywords = await preparePersonaHotKeywords(false);
    if (preparedKeywords.length) keywords = parsePersonaHotKeywordText(formatPersonaHotKeywordText(preparedKeywords));
  } catch (error) {
    if (!keywords.length) throw error;
  }
  if (!keywords.length) {
    const prepareError = String(personaGenerateRunState(persona.id)?.error || "").trim();
    showMsg("commandMsg", prepareError || "热点抓取准备失败，请稍后重试。", false);
    return;
  }
  const controller = new AbortController();
  state.personaHotFetchControllers[personaKey]?.abort?.(new DOMException("Request replaced", "AbortError"));
  state.personaHotFetchControllers[personaKey] = controller;
  form.hotKeywordText = formatPersonaHotKeywordText(keywords);
  setPersonaGenerateRunState(persona.id, {
    kind: "hot",
    status: "running",
    message: refresh ? "搜索词已就绪，正在抓取帖子" : "搜索词已就绪，正在抓取帖子",
    error: "",
  });
  clearMsg("commandMsg");
  setActionLocked(lockParts, true);
  renderPersonaDetail();
  try {
    const task = await apiWithTimeout(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_candidates/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: controller.signal,
      body: JSON.stringify({
        refresh: Boolean(refresh),
        limit: 10,
        keywords,
        search_mode: form.hotSearchMode,
        writing_locale: PERSONA_WRITING_LOCALES.some(([value]) => value === String(form.writingLocale || ""))
          ? String(form.writingLocale)
          : PERSONA_DEFAULT_WRITING_LOCALE,
        // Keep the source live and the 500 heat floor strict. The collector
        // accepts posts from the latest 30 days and returns newer posts first.
        freshness_days: 30,
        freshness_policy: "strict",
        platform: personaContentPlatform(persona),
      }),
    }, 15000);
    const taskId = String(task?.id || "").trim();
    if (!taskId) throw { detail: "热点抓取任务创建失败。", status: 500 };
    const pollDeadline = Date.now() + 165000;
    let result = null;
    while (Date.now() < pollDeadline) {
      await sleep(1000);
      const current = await apiWithTimeout(
        `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_candidates/tasks/${encodeURIComponent(taskId)}`,
        { signal: controller.signal },
        15000,
      );
      const status = String(current?.status || "").trim().toLowerCase();
      if (status === "success") {
        result = current.result && typeof current.result === "object" ? current.result : {};
        break;
      }
      if (status === "failed") {
        throw { detail: current.error || "热点候选抓取失败。", status: 500 };
      }
      if (status === "cancelled") {
        throw { detail: "热点抓取已取消。", status: 499 };
      }
    }
    if (!result) throw { detail: "热点抓取超时，请稍后重试。", status: 408 };
    const fetchedCandidates = Array.isArray(result.candidates) ? result.candidates : [];
    const currentPlatform = personaContentPlatform(persona);
    const previousOther = previousCandidates.filter((candidate) => (
      normalizePersonaContentPlatform(candidate?.platform) !== currentPlatform
    ));
    const platformCandidates = fetchedCandidates.filter((candidate) => (
      normalizePersonaContentPlatform(candidate?.platform || "threads") === currentPlatform
    ));
    const mergedCandidates = [...previousOther, ...platformCandidates];
    const unreadCounts = {
      ...(state.personaHotCandidateResults[String(persona.id)]?.unread_counts || {}),
    };
    accountPoolPlatforms.forEach(([platform]) => {
      if (!(platform in unreadCounts)) unreadCounts[platform] = 0;
    });
    unreadCounts[currentPlatform] = platformCandidates.length;
    const previousHot = state.personaHotCandidateResults[String(persona.id)] || {};
    state.personaHotCandidateResults[String(persona.id)] = {
      ...previousHot,
      candidates: mergedCandidates,
      keywords,
      all_keywords: Array.isArray(previousHot.all_keywords) && previousHot.all_keywords.length ? previousHot.all_keywords : keywords,
      cookie_statuses: Array.isArray(result.cookie_statuses) ? result.cookie_statuses : [],
      warnings: Array.isArray(result.warnings) ? result.warnings : [],
      search_mode: normalizePersonaHotSearchMode(result.search_mode || form.hotSearchMode),
      cooldown: result.cooldown && typeof result.cooldown === "object" ? result.cooldown : {},
      unread_counts: unreadCounts,
      fetched_at: new Date().toISOString(),
    };
    form.hotKeywordText = formatPersonaHotKeywordText(keywords);
    const nextCandidates = personaHotAllCandidates(persona);
    reconcilePersonaHotMediaStateAfterRefresh(persona.id, previousCandidates, nextCandidates);
    state.transientWorkspaceLeaveAcknowledgement = "";
    const candidateIds = nextCandidates.map((item) => String(item.candidate_id || "").trim()).filter(Boolean);
    const candidateIdSet = new Set(candidateIds);
    form.hotSelectedIds = (form.hotSelectedIds || []).filter((item) => candidateIds.includes(String(item || "").trim()));
    form.hotPreviewId = candidateIds.includes(String(form.hotPreviewId || "").trim()) ? String(form.hotPreviewId || "").trim() : (candidateIds[0] || "");
    if (!candidateIdSet.has(String(form.hotEditingCandidateId || "").trim())) form.hotEditingCandidateId = "";
    Object.keys(form.hotReplacementFilesByCandidate || {}).forEach((candidateId) => {
      if (!candidateIdSet.has(candidateId)) clearPersonaHotReplacementFiles(persona.id, candidateId);
    });
    Object.keys(form.hotReplacementPoolByCandidate || {}).forEach((candidateId) => {
      if (!candidateIdSet.has(candidateId)) clearPersonaHotReplacementPool(persona.id, candidateId);
    });
    Object.keys(form.hotMediaDraftsByCandidate || {}).forEach((candidateId) => {
      if (!candidateIdSet.has(candidateId)) clearPersonaHotMediaDraft(persona.id, candidateId);
    });
    ["hotDeletedMediaByCandidate", "hotEditedContentByCandidate", "hotRewrittenByCandidate", "hotSelectedMediaIndexByCandidate", "hotSelectedReplacementPoolIdByCandidate"].forEach((field) => {
      const current = form[field] && typeof form[field] === "object" ? form[field] : {};
      form[field] = Object.fromEntries(Object.entries(current).filter(([candidateId]) => candidateIdSet.has(candidateId)));
    });
    setPersonaGenerateRunState(persona.id, {
      kind: "hot",
      status: "success",
      message: `热点候选已获取 ${candidateIds.length} 条`,
      generatedCount: candidateIds.length,
      error: "",
    });
  } catch (error) {
    if (Number(error?.status || 0) === 499) {
      setPersonaGenerateRunState(persona.id, {
        kind: "hot",
        status: "idle",
        message: "热点抓取已取消",
        error: "",
      });
      return;
    }
    setPersonaGenerateRunState(persona.id, {
      kind: "hot",
      status: "error",
      message: "热点候选抓取失败",
      error: error.detail || error.message || "抓取失败",
    });
    throw error;
  } finally {
    if (state.personaHotFetchControllers[personaKey] === controller) {
      delete state.personaHotFetchControllers[personaKey];
    }
    setActionLocked(lockParts, false);
    if (isPersonaWorkspaceModule()) {
      renderPersonaDetail();
      renderConfirmSummary();
    }
  }
}

async function cancelPersonaHotCandidates() {
  const persona = selectedPersona();
  if (!persona) return;
  const personaKey = String(persona.id || "").trim();
  const controller = state.personaHotFetchControllers[personaKey];
  const cancellation = apiWithTimeout(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_candidates/cancel`, {
    method: "POST",
  }, 10000);
  controller?.abort?.(new DOMException("Request cancelled", "AbortError"));
  if (state.personaHotFetchControllers[personaKey] === controller) {
    delete state.personaHotFetchControllers[personaKey];
  }
  setPersonaGenerateRunState(persona.id, {
    kind: "hot",
    status: "idle",
    message: "热点抓取已取消",
    error: "",
  });
  setActionLocked(["persona", persona.id, "hot_candidates"], false);
  if (isPersonaWorkspaceModule()) {
    renderPersonaDetail();
    renderConfirmSummary();
  }
  showMsg("commandMsg", "热点抓取已取消。", true);
  await cancellation;
}

async function submitPersonaHotDraftImport(persona, selected, {
  replacementOpsByCandidate = {},
  preparedMediaOpsByCandidate = {},
  leftoverCandidates = [],
  targetPlatform = personaContentPlatform(persona),
} = {}) {
  const leftover = Array.isArray(leftoverCandidates) ? leftoverCandidates : [];
  const resolvedTargetPlatform = normalizePersonaContentPlatform(targetPlatform);
  if (selected.some((candidate) => normalizePersonaContentPlatform(candidate?.platform) !== resolvedTargetPlatform)) {
    throw { detail: "热点推文只能保存到对应的平台。", status: 400 };
  }
  const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/hot_candidates/import`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      platform: resolvedTargetPlatform,
      recycle_candidates: leftover.map((candidate) => ({
        id: candidate.id || candidate.candidate_id,
        platform: candidate.platform,
        author: candidate.author || "",
        sourceUrl: candidate.source_url,
        content: candidate.full_content || candidate.content || "",
        hotScore: Number(candidate.hot_score || candidate.score || 0),
        metrics: candidate.metrics || {},
        engagement: candidate.engagement || {},
        publishedAt: candidate.published_at || "",
        capturedAt: candidate.captured_at || "",
        media: Array.isArray(candidate.media_items) ? candidate.media_items.map((item) => ({
          url: item.url || item.preview_url || "",
          type: item.type || "",
        })) : [],
      })),
      candidates: selected.map((candidate) => ({
        id: candidate.id || candidate.candidate_id,
        platform: candidate.platform,
        author: candidate.author || "",
        sourceUrl: candidate.source_url,
        content: candidate.full_content || candidate.content || "",
        hotScore: Number(candidate.hot_score || candidate.score || 0),
        metrics: candidate.metrics || {},
        engagement: candidate.engagement || {},
        publishedAt: candidate.published_at || "",
        capturedAt: candidate.captured_at || "",
        warnings: Array.isArray(candidate.warnings) ? candidate.warnings : [],
        media: Array.isArray(candidate.media_items) ? candidate.media_items.map((item) => ({
          url: item.url || item.preview_url || "",
          type: item.type || "",
        })) : [],
      })),
    }),
  });
  const createdIds = Array.isArray(result.posts) ? result.posts.map((item) => String(item?.id || "").trim()).filter(Boolean) : [];
  const form = personaFormState(persona.id).generate;
  let replacementCount = 0;
  let editedMediaCount = 0;
  try {
    for (let index = 0; index < selected.length; index += 1) {
      const candidateId = personaHotCandidateKey(selected[index]);
      const operations = Array.isArray(replacementOpsByCandidate[candidateId])
        ? replacementOpsByCandidate[candidateId].filter((item) => item?.file && Number.isInteger(item?.replaceIndex) && item.replaceIndex >= 0)
        : [];
      const postId = createdIds[index] || "";
      if (!postId) continue;
      for (const operation of operations) {
        let lastError = null;
        for (let attempt = 1; attempt <= 3; attempt += 1) {
          try {
            await savePersonaPostMediaFiles({
              persona,
              postId,
              source: "posts",
              files: [operation.file],
              replaceIndex: operation.replaceIndex,
            });
            lastError = null;
            break;
          } catch (error) {
            lastError = error;
            if (attempt < 3) await sleep(300 * (2 ** (attempt - 1)));
          }
        }
        if (lastError) throw lastError;
        replacementCount += 1;
      }
      const preparedMediaOps = Array.isArray(preparedMediaOpsByCandidate[candidateId])
        ? preparedMediaOpsByCandidate[candidateId]
        : [];
      if (postId && preparedMediaOps.length) {
        await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts/${encodeURIComponent(postId)}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            title: String(selected[index]?.title || ""),
            content: String(selected[index]?.full_content || selected[index]?.content || ""),
            media_paths: [],
            media_ops: preparedMediaOps,
          }),
        });
        editedMediaCount += preparedMediaOps.length;
      }
    }
  } catch (error) {
    const rollbackResults = await Promise.allSettled(createdIds.map((postId) => api(
      `/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts/by_id/${encodeURIComponent(postId)}`,
      { method: "DELETE" },
    )));
    await loadPersonaDraftPosts(persona.id, { force: true }).catch(() => []);
    const rollbackFailures = rollbackResults.filter((item) => item.status === "rejected").length;
    const wrapped = new Error(
      rollbackFailures
        ? `媒体替换失败，且有 ${rollbackFailures} 条草稿未能自动撤销，请检查草稿库后再重试。`
        : "媒体替换连续失败，已自动撤销本次草稿导入，可以直接重试。",
    );
    wrapped.detail = wrapped.message;
    wrapped.cause = error;
    throw wrapped;
  }
  const importedIds = new Set(selected.map(personaHotCandidateKey).filter(Boolean));
  form.hotSelectedIds = [];
  if (!form.hotPreviewId) form.hotPreviewId = personaHotCandidateKey(selected[0]);
  if (importedIds.has(String(form.hotEditingCandidateId || "").trim())) form.hotEditingCandidateId = "";
  importedIds.forEach((candidateId) => {
    delete form.hotDeletedMediaByCandidate?.[candidateId];
    delete form.hotEditedContentByCandidate?.[candidateId];
    delete form.hotRewrittenByCandidate?.[candidateId];
    delete form.hotSelectedMediaIndexByCandidate?.[candidateId];
    clearPersonaHotReplacementFiles(persona.id, candidateId);
    clearPersonaHotReplacementPool(persona.id, candidateId);
    clearPersonaHotMediaDraft(persona.id, candidateId);
  });
  state.transientWorkspaceLeaveAcknowledgement = "";
  await loadPersonaDraftPosts(persona.id, { force: true });
  watchPersonaHotImportMedia(persona.id, createdIds);
  setPersonaContentPlatform(resolvedTargetPlatform, persona);
  const importedCount = result.imported_count || createdIds.length || 0;
  setPersonaGenerateRunState(persona.id, {
    kind: "hot_import",
    status: "success",
    message: `热点草稿已导入 ${importedCount} 条`,
    generatedCount: importedCount,
    postIds: createdIds,
    error: "",
  });
  renderPersonaDetail();
  renderConfirmSummary();
  return { ...result, createdIds, replacementCount, editedMediaCount };
}

async function importPersonaHotDrafts(candidateIds = null, {
  showCompletionModal = true,
  applyStoredEdits = false,
  targetPlatform = "",
} = {}) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const form = personaFormState(persona.id).generate;
  const lockParts = ["persona", persona.id, "hot_import"];
  if (isActionLocked(...lockParts)) {
    showMsg("commandMsg", "热点草稿正在导入，请等待当前导入完成。", false);
    return;
  }
  const requestedIds = Array.isArray(candidateIds)
    ? candidateIds.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const selected = (requestedIds.length
    ? personaHotCandidates(persona).filter((item) => requestedIds.includes(String(item.candidate_id || item.id || "").trim()))
    : personaHotSelectedCandidates(persona))
    .filter((item) => String(item.full_content || item.content || "").trim());
  if (!selected.length) {
    showMsg("commandMsg", "请先勾选至少一条带正文的热点候选。", false);
    return;
  }
  const resolvedTargetPlatform = normalizePersonaContentPlatform(targetPlatform || personaContentPlatform(persona));
  if (selected.some((candidate) => normalizePersonaContentPlatform(candidate.platform) !== resolvedTargetPlatform)) {
    showMsg("commandMsg", "热点推文只能保存到对应的平台。", false);
    return null;
  }
  const applyCurrentEdits = requestedIds.length === 0 || applyStoredEdits;
  if (requestedIds.length === 0) snapshotPersonaHotPreviewContent();
  const replacementOpsByCandidate = {};
  const preparedMediaOpsByCandidate = {};
  const prepared = selected.map((candidate) => {
    if (!applyCurrentEdits) return candidate;
    const candidateId = personaHotCandidateKey(candidate);
    const deleted = personaHotDeletedMediaSet(persona.id, candidateId);
    const originalMediaItems = personaHotCandidateMediaItems(candidate);
    const mediaItems = originalMediaItems.filter((_, index) => !deleted.has(index));
    const sourceToEffectiveIndex = new Map();
    let effectiveIndex = 0;
    originalMediaItems.forEach((_, sourceIndex) => {
      if (deleted.has(sourceIndex)) return;
      sourceToEffectiveIndex.set(sourceIndex, effectiveIndex);
      effectiveIndex += 1;
    });
    const replacementOps = personaHotReplacementEntries(persona.id, candidateId)
      .map((entry) => ({
        file: entry.file,
        replaceIndex: sourceToEffectiveIndex.get(entry.index),
      }))
      .filter((entry) => entry.file && Number.isInteger(entry.replaceIndex));
    if (replacementOps.length) replacementOpsByCandidate[candidateId] = replacementOps;
    const editedContent = personaHotEditedContent(persona.id, candidate).trim();
    return {
      ...candidate,
      content: editedContent.slice(0, 280),
      full_content: editedContent,
      media_items: mediaItems,
    };
  });
  for (const candidate of selected) {
    const candidateId = personaHotCandidateKey(candidate);
    const operations = Array.isArray(form.hotMediaOpsByCandidate?.[candidateId])
      ? form.hotMediaOpsByCandidate[candidateId]
      : [];
    if (applyCurrentEdits && operations.length) {
      preparedMediaOpsByCandidate[candidateId] = await preparePersonaDraftMediaOps(operations);
    }
  }
  setPersonaGenerateRunState(persona.id, {
    kind: "hot_import",
    status: "running",
    message: `热点草稿导入中 ${selected.length} 条`,
    error: "",
  });
  clearMsg("commandMsg");
  setActionLocked(lockParts, true);
  renderPersonaDetail();
  let importResult = null;
  try {
    const selectedKeys = new Set(prepared.map((item) => personaHotCandidateKey(item)));
    const leftoverCandidates = personaHotCandidates(persona).filter((item) => !selectedKeys.has(personaHotCandidateKey(item)));
    importResult = await submitPersonaHotDraftImport(persona, prepared, {
      replacementOpsByCandidate,
      preparedMediaOpsByCandidate,
      leftoverCandidates,
      targetPlatform: resolvedTargetPlatform,
    });
  } catch (error) {
    setPersonaGenerateRunState(persona.id, {
      kind: "hot_import",
      status: "error",
      message: "热点草稿导入失败",
      error: error.detail || error.message || "导入失败",
    });
    throw error;
  } finally {
    setActionLocked(lockParts, false);
    if (isPersonaWorkspaceModule()) renderPersonaDetail();
  }
  if (importResult && showCompletionModal) {
    const importedCount = Number(importResult.imported_count || 0) || (importResult.createdIds || []).length || 0;
    const replacementCount = Number(importResult.replacementCount || 0);
    const editedMediaCount = Number(importResult.editedMediaCount || 0);
    await openConsoleModal({
      title: "热点草稿已导入",
      message: `已将 ${importedCount} 条热点推文保存到当前人设草稿库${replacementCount ? `，并替换 ${replacementCount} 个媒体文件` : ""}${editedMediaCount ? `，完成 ${editedMediaCount} 项媒体编辑` : ""}。页面会保持在热点处理区，你可以继续选择或编辑热点。`,
      confirmText: "继续处理热点",
      showCancel: false,
    });
  }
  return importResult;
}

function resetPersonaDraftEditor(personaId) {
  resetPersonaNewDraftComposer(personaId);
}

function discardPersonaDraftEdit(personaId) {
  const form = personaFormState(personaId);
  form.generate.mode = "custom";
  form.draft = defaultPersonaDraftForm();
}

function clearPersonaDraftEdit(personaId) {
  if (String(state.renderedPersonaId || "") === String(personaId || "")) {
    state.renderedPersonaId = "";
  }
  const form = personaFormState(personaId);
  form.generate.mode = "custom";
  form.draft = normalizePersonaDraftForm(form.draft);
  form.draft.title = "";
  form.draft.content = "";
  if ($("personaDraftTitle")) $("personaDraftTitle").value = "";
  if ($("personaDraftContent")) $("personaDraftContent").value = "";
  syncPersonaDraftDirty(form.draft);
  updatePersonaDraftEditVisualState();
}

function cancelPersonaDraftEditChanges(personaId) {
  const persona = selectedPersona();
  const form = personaFormState(personaId);
  form.draft = normalizePersonaDraftForm(form.draft);
  const draft = form.draft;
  const source = draft.editingSource === "favorites" ? "favorites" : "posts";
  const post = persona && String(persona.id || "") === String(personaId || "")
    ? personaSourcePosts(persona, source).find((item) => String(item.id || "") === String(draft.editingPostId || ""))
    : null;
  if (!post) return false;
  const originalMediaItems = personaEditablePostMediaItems(personaId, post).map(clonePersonaDraftMediaItem);
  form.generate.mode = "custom";
  form.draft = defaultPersonaDraftForm({
    title: String(post.title || "").trim(),
    content: String(post.content || ""),
    editingPostId: String(post.id || "").trim(),
    editingSource: source,
    originalTitle: String(post.title || "").trim(),
    originalContent: String(post.content || ""),
    originalMediaSignature: personaMediaSignature(originalMediaItems),
    mediaItems: originalMediaItems,
    mediaOps: [],
    dirty: false,
  });
  return true;
}

async function exitPersonaDraftEdit(personaId) {
  if (String(state.renderedPersonaId || "") === String(personaId || "")) {
    snapshotPersonaCurrentForm();
  }
  const status = personaDraftEditState(personaId);
  if (status.dirty) {
    const action = await confirmSaveDraftEditBeforeLeave();
    if (action === "save") createPersonaDraftPost().catch((error) => showMsg("commandMsg", error.detail || error.message || "保存修改失败", false));
    if (action === "discard") {
      discardPersonaDraftEdit(personaId);
      state.personaPanels.content = "posts";
      return true;
    }
    return false;
  }
  discardPersonaDraftEdit(personaId);
  state.personaPanels.content = "posts";
  return true;
}

function resetPersonaNewDraftComposer(personaId) {
  const form = personaFormState(personaId);
  form.generate.mode = "ai";
  const composeDraftInputs = ensurePersonaComposeDraftInputs(form);
  composeDraftInputs.tweet = defaultPersonaComposeDraftInput();
  composeDraftInputs.tweet_media = defaultPersonaComposeDraftInput();
  form.generate.prompt = "";
  ["tweet", "tweet_media"].forEach((composeMode) => {
    clearUploadDropzoneState(
      "personaPostMediaUploadFiles",
      personaComposePendingMediaStateKey({ id: personaId }, composeMode),
    );
  });
  form.draft = defaultPersonaDraftForm();
  form.media.focusPostId = "";
  setSelectedPersonaPostId("");
  if (String(state.renderedPersonaId || "") === String(personaId || "")) {
    if ($("personaDraftTitle")) $("personaDraftTitle").value = "";
    if ($("personaDraftContent")) $("personaDraftContent").value = "";
    syncPersonaGenerateActionState();
  }
}

function openPersonaDraftEditor(postId) {
  const persona = selectedPersona();
  if (!persona) return;
  const source = personaPostSource(persona);
  const post = personaSourcePosts(persona, source).find((item) => String(item.id) === String(postId || "").trim());
  if (!post) {
    showMsg("commandMsg", source === "favorites" ? "当前收藏不存在或已移出。" : "当前草稿不存在或已被删除。", false);
    return;
  }
  closePersonaDraftMenus();
  const form = personaFormState(persona.id);
  const originalMediaItems = personaEditablePostMediaItems(persona.id, post).map(clonePersonaDraftMediaItem);
  form.generate.mode = "custom";
  form.draft = defaultPersonaDraftForm({
    title: String(post.title || "").trim(),
    content: String(post.content || ""),
    editingPostId: String(post.id || "").trim(),
    editingSource: source,
    originalTitle: String(post.title || "").trim(),
    originalContent: String(post.content || ""),
    originalMediaSignature: personaMediaSignature(originalMediaItems),
    mediaItems: originalMediaItems,
    mediaOps: [],
    dirty: false,
  });
  if (form.media?.customModifySource) {
    if (String(form.media.customModifySource.previewUrl || "").startsWith("blob:")) {
      URL.revokeObjectURL(form.media.customModifySource.previewUrl);
    }
    delete form.media.customModifySource;
  }
  const existingTask = personaMediaTaskState(persona.id, post.id);
  if (existingTask) existingTask.modifyMediaKey = "";
  setPersonaPostSource(source, persona);
  setSelectedPersonaPostId(post.id || state.selectedPersonaPostId || "");
  state.personaGroup = "content";
  state.personaPanels.content = "generate";
  renderPersonaDetail();
  renderConfirmSummary();
}

async function deletePersonaDraftPost(postId = "") {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const source = personaFormState(persona.id).draft.editingSource === "favorites" || personaPostSource(persona) === "favorites" ? "favorites" : "posts";
  if (source === "favorites") {
    await deletePersonaFavoritePost(postId);
    return;
  }
  const cleanPostId = String(postId || state.selectedPersonaPostId || "").trim();
  const post = personaDraftPosts(persona).find((item) => String(item.id) === cleanPostId);
  if (!post) {
    showMsg("commandMsg", "当前草稿不存在或已被删除。", false);
    return;
  }
  const confirmed = await openConsoleModal({
    title: "删除草稿",
    message: `确认删除“${personaDraftDisplayTitleForPost(post, personaDraftPosts(persona))}”吗？`,
    confirmText: "删除",
    cancelText: "取消",
    danger: true,
  });
  if (!confirmed) return;
  showMsg("commandMsg", "正在删除草稿...", true);
  await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts/by_id/${encodeURIComponent(cleanPostId)}`, {
    method: "DELETE",
  });
  deletePersonaHotImportMeta(persona.id, cleanPostId);
  resetPersonaDraftEditor(persona.id);
  if ($("personaDraftTitle")) $("personaDraftTitle").value = "";
  if ($("personaDraftContent")) $("personaDraftContent").value = "";
  await Promise.all([
    loadPersonaDraftPosts(persona.id, { force: true }),
    loadPersonaPublishHistory(persona.id, { force: true }).catch(() => []),
  ]);
  state.personaPanels.content = personaDraftPosts(persona).length ? "posts" : "generate";
  renderPersonaDetail();
  renderConfirmSummary();
  showMsg("commandMsg", "草稿已删除。", true);
}

async function deletePersonaSelectedPosts(source = personaPostSource(), ids = []) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const cleanSource = source === "favorites" ? "favorites" : "posts";
  const rows = personaSourcePosts(persona, cleanSource);
  const selectedIds = Array.from(new Set((ids && ids.length ? ids : personaSelectedPostIds(persona, cleanSource))
    .map((item) => String(item || "").trim())
    .filter((id) => rows.some((post) => String(post.id || "").trim() === id))));
  if (!selectedIds.length) {
    showMsg("commandMsg", cleanSource === "favorites" ? "请先勾选要移出的收藏。" : "请先勾选要删除的草稿。", false);
    return;
  }
  const confirmed = await openConsoleModal({
    title: cleanSource === "favorites" ? "批量移出收藏" : "批量删除草稿",
    message: cleanSource === "favorites"
      ? `确认将已勾选的 ${selectedIds.length} 条收藏移出吗？原草稿不会被删除。`
      : `确认删除已勾选的 ${selectedIds.length} 条草稿吗？`,
    confirmText: cleanSource === "favorites" ? "批量移出" : "批量删除",
    cancelText: "取消",
    danger: true,
  });
  if (!confirmed) return;
  showMsg("commandMsg", cleanSource === "favorites" ? "正在批量移出收藏..." : "正在批量删除草稿...", true);
  for (const postId of selectedIds) {
    if (cleanSource === "favorites") {
      await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/favorites/${encodeURIComponent(postId)}`, {
        method: "DELETE",
      });
    } else {
      await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/posts/by_id/${encodeURIComponent(postId)}`, {
        method: "DELETE",
      });
      deletePersonaHotImportMeta(persona.id, postId);
    }
  }
  setPersonaSelectedPostIds(persona, cleanSource, []);
  resetPersonaDraftEditor(persona.id);
  if ($("personaDraftTitle")) $("personaDraftTitle").value = "";
  if ($("personaDraftContent")) $("personaDraftContent").value = "";
  if (cleanSource === "favorites") {
    await loadPersonaFavoritePosts(persona.id, { force: true });
    const favoriteRows = personaFavoritePosts(persona);
    setSelectedPersonaPostId(favoriteRows[0]?.id || "", { auto: true });
    setPersonaPostSource(favoriteRows.length ? "favorites" : "posts", persona);
  } else {
    await Promise.all([
      loadPersonaDraftPosts(persona.id, { force: true }),
      loadPersonaPublishHistory(persona.id, { force: true }).catch(() => []),
    ]);
    const draftRows = personaDraftPosts(persona);
    setSelectedPersonaPostId(draftRows[0]?.id || "", { auto: true });
    if (!draftRows.length && personaPostSource(persona) === "posts" && personaFavoritePosts(persona).length) {
      setPersonaPostSource("favorites", persona);
      setSelectedPersonaPostId(personaFavoritePosts(persona)[0]?.id || "", { auto: true });
    }
  }
  state.personaPanels.content = personaDraftPosts(persona).length || personaFavoritePosts(persona).length ? "posts" : "generate";
  renderPersonaDetail();
  renderConfirmSummary();
  showMsg("commandMsg", cleanSource === "favorites" ? "已批量移出收藏。" : "已批量删除草稿。", true);
}

async function addPersonaFavoritePost(postId = "", { preserveSource = false } = {}) {
  const persona = selectedPersona();
  if (!persona) {
    showMsg("commandMsg", "请先选择一个人设。", false);
    return;
  }
  const cleanPostId = String(postId || state.selectedPersonaPostId || "").trim();
  const post = personaDraftPosts(persona).find((item) => String(item.id) === cleanPostId);
  if (!post) {
    showMsg("commandMsg", "当前草稿不存在或已被删除。", false);
    return;
  }
  const lockParts = ["persona", persona.id, "favorite_post", cleanPostId];
  if (isActionLocked(...lockParts)) return;
  setActionLocked(lockParts, true);
  try {
    const result = await api(`/api/persona_dashboard/personas/${encodeURIComponent(persona.id)}/favorites/${encodeURIComponent(cleanPostId)}`, {
      method: "POST",
    });
    const nextFavorites = sortPersonaDraftPosts(Array.isArray(result.favorites) ? result.favorites : []);
    state.personaFavoritePosts[String(persona.id)] = nextFavorites;
    syncPersonaSelectedPostIds(persona, "favorites", nextFavorites);
    if (!preserveSource) {
      setPersonaPostSource("favorites", persona);
      setSelectedPersonaPostId(result.post?.id || nextFavorites[0]?.id || state.selectedPersonaPostId || "");
    } else {
      setPersonaPostSource("posts", persona);
      setSelectedPersonaPostId(cleanPostId);
    }
    state.personaPanels.content = "posts";
    renderPersonaDetail();
    renderConfirmSummary();
    showMsg("commandMsg", result.exists ? "这条内容已经在收藏里。" : "已加入收藏。", true, { key: `favorite:${persona.id}:${cleanPostId}` });
  } catch (error) {
    const detail = String(error?.detail || error?.message || "").trim();
    if (error?.status === 404 || /post not found|草稿已发布|不存在/.test(detail)) {
      await loadPersonaDraftPosts(persona.id, { force: true }).catch(() => []);
      const rows = personaDraftPosts(persona);
      if (!rows.some((item) => String(item.id) === cleanPostId)) {
        setSelectedPersonaPostId(rows[0]?.id || "", { auto: true });
      }
      state.personaPanels.content = rows.length || personaFavoritePosts(persona).length ? "posts" : "generate";
      renderPersonaDetail();
      renderConfirmSummary();
      showMsg("commandMsg", "草稿已发布或已不存在，已刷新草稿库。", false, { key: `favorite-missing:${persona.id}:${cleanPostId}` });
      return;
    }
    throw error;
  } finally {
    setActionLocked(lockParts, false);
  }
}

