function personaGeneratedPreviewPosts(persona, runState) {
  const ids = new Set((Array.isArray(runState?.postIds) ? runState.postIds : [])
    .map((id) => String(id || "").trim())
    .filter(Boolean));
  const storedRows = personaDraftPosts(persona);
  const storedMatches = ids.size ? storedRows.filter((post) => ids.has(String(post?.id || "").trim())) : [];
  const resultRows = Array.isArray(runState?.posts) ? runState.posts : [];
  const merged = [];
  const seen = new Set();
  [...storedMatches, ...resultRows].forEach((post) => {
    const id = String(post?.id || "").trim();
    if (!id || seen.has(id)) return;
    seen.add(id);
    merged.push(post);
  });
  return merged;
}

function consumePersonaGeneratedPreviewPost(persona, postId) {
  const personaId = String(persona?.id || "").trim();
  const cleanPostId = String(postId || "").trim();
  const composeMode = resolvedPersonaGeneratedPreviewComposeMode(personaId);
  const previewState = personaGeneratedPreviewState(personaId, composeMode);
  if (!personaId || !cleanPostId || !previewState) return "";
  const currentRows = personaGeneratedPreviewPosts(persona, previewState);
  const currentIndex = currentRows.findIndex((post) => String(post?.id || "").trim() === cleanPostId);
  previewState.postIds = (Array.isArray(previewState.postIds) ? previewState.postIds : [])
    .filter((id) => String(id || "").trim() !== cleanPostId);
  previewState.posts = (Array.isArray(previewState.posts) ? previewState.posts : [])
    .filter((post) => String(post?.id || "").trim() !== cleanPostId);
  const remainingRows = personaGeneratedPreviewPosts(persona, previewState);
  if (!remainingRows.length) {
    deletePersonaGeneratedPreview(personaId, composeMode);
    return "";
  }
  previewState.generatedCount = remainingRows.length;
  previewState.visible = true;
  const nextIndex = Math.min(Math.max(currentIndex, 0), remainingRows.length - 1);
  return String(remainingRows[nextIndex]?.id || remainingRows[0]?.id || "").trim();
}

function renderPersonaGenerateStatusText(persona) {
  const runState = personaGenerateRunState(persona?.id);
  if (!persona || !runState) return "";
  const status = String(runState.status || "").trim();
  const kind = String(runState.kind || "draft").trim();
  const isRunning = status === "running";
  const isError = status === "error";
  const isSuccess = status === "success";
  const isDraft = kind === "draft";
  const rows = isSuccess && isDraft ? personaGeneratedPreviewPosts(persona, runState) : [];
  const fallbackSuccess = isDraft
    ? `图文草稿已生成 ${Number(runState.generatedCount || rows.length || 0)} 条`
    : "操作已完成";
  const label = String(runState.message || "").trim() || (isRunning
    ? (isDraft ? "图文草稿生成中" : "处理中")
    : (isError ? (isDraft ? "图文草稿生成失败" : "操作失败") : fallbackSuccess));
  const title = isRunning && isDraft
    ? `预计生成 ${Number(runState.count || 0) || personaGenerateDefaults().count} 条，目标约 ${Number(runState.targetWords || 0) || personaGenerateDefaults().targetWords} 字`
    : (isError ? String(runState.error || "请稍后重试。") : label);
  return `
    <span
      class="persona-generate-status-text ${isRunning ? "is-running" : ""} ${isSuccess ? "is-success" : ""} ${isError ? "is-error" : ""}"
      title="${esc(title)}"
      aria-live="polite"
    >
      <span class="persona-generate-status-label">${esc(label)}</span>
      ${isRunning ? `<span class="persona-generate-status-ellipsis" aria-hidden="true">...</span>` : ""}
    </span>
  `;
}

function renderPersonaGeneratePreviewDock(persona, composeMode = "") {
  if (composeMode === "hot") return "";
  const runState = personaGeneratedPreviewState(persona?.id, composeMode);
  if (!persona || !runState || runState.selectionRequired || runState.visible === false || String(runState.status || "") !== "success") return "";
  const rows = personaGeneratedPreviewPosts(persona, runState);
  if (!rows.length) return "";
  return `
    <div class="persona-generated-preview-dock">
      <div class="persona-generated-preview-dock-head">
        <div>
          <strong>生成结果预览</strong>
          <p>已生成 ${esc(Number(runState.generatedCount || rows.length || 0))} 条，结果已同步到草稿库。</p>
        </div>
        <div class="row-actions">
          <button type="button" data-persona-clear-generate-preview="${esc(persona.id)}">关闭预览</button>
        </div>
      </div>
      <div class="persona-memory-grid persona-generated-preview-grid">
        ${rows.map((post, index) => {
          const selected = String(post.id || "") === String(state.selectedPersonaPostId || "");
          const content = String(post.content || post.full_content || "").trim() || "暂无正文。";
          return `
            <article
              class="persona-memory-card persona-generated-preview-card ${selected ? "is-selected" : ""}"
              data-persona-generated-card="${esc(post.id)}"
              role="button"
              tabindex="0"
              aria-pressed="${selected ? "true" : "false"}"
            >
              <div class="persona-memory-card-main persona-generated-preview-main">
                <span class="persona-memory-index">${esc(index + 1)}</span>
                <span class="persona-memory-copy">
                  <strong>${esc(content)}</strong>
                  <small>${esc(personaDraftDisplayTitle(post, index, rows))} · ${esc(formatTime(post.published_at || post.updated_at || post.created_at))}</small>
                </span>
              </div>
              <div class="persona-memory-card-actions">
                <button type="button" data-persona-generated-view="${esc(post.id)}">查看</button>
              </div>
            </article>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

async function viewPersonaGeneratedPost(postId = "") {
  const activePreview = activePersonaGeneratePreview();
  const post = activePreview?.rows.find((item) => String(item.id || "") === String(postId || ""));
  if (!activePreview || !post) return;
  const content = String(post.content || post.full_content || "").trim() || "暂无正文。";
  await openConsoleModal({
    title: "推文完整内容",
    contentHtml: `
      <div class="console-modal-detail persona-draft-detail-modal">
        <div><span>推文标题</span><strong>${esc(personaDraftDisplayTitleForPost(post, activePreview.rows))}</strong></div>
        <div><span>生成时间</span><strong>${esc(formatTime(post.published_at || post.updated_at || post.created_at))}</strong></div>
        <div class="persona-draft-detail-content">
          <span>推文正文</span>
          <p>${esc(content)}</p>
        </div>
      </div>
    `,
    confirmText: "关闭",
    showCancel: false,
  });
}

function renderPersonaGeneratedSelectionCard(post, index, rows, selectedId) {
  const postId = String(post?.id || "").trim();
  const selected = postId === String(selectedId || "").trim();
  const content = String(post?.content || post?.full_content || "").trim() || "暂无正文。";
  return `
    <label class="persona-generated-selection-card ${selected ? "is-selected" : ""}" data-persona-generated-selection-card="${esc(postId)}">
      <input
        type="radio"
        name="personaGeneratedSelection"
        value="${esc(postId)}"
        ${selected ? "checked" : ""}
      />
      <span class="persona-generated-selection-index">${esc(index + 1)}</span>
      <span class="persona-generated-selection-copy">
        <strong>${esc(personaDraftDisplayTitle(post, index, rows))}</strong>
        <span>${esc(content)}</span>
      </span>
      <span class="persona-generated-selection-mark" aria-hidden="true">✓</span>
    </label>
  `;
}

async function openPersonaGeneratedSelectionModal(persona, rows = []) {
  const candidates = Array.isArray(rows) ? rows.filter((post) => String(post?.id || "").trim()) : [];
  if (!persona || !candidates.length) return { action: "", postId: "" };
  let selectedId = String(candidates[0]?.id || "").trim();
  const request = openConsoleModal({
    title: "选择一篇生成结果",
    message: `普通推文已生成 ${candidates.length} 篇候选。请选择其中一篇保存为草稿，或直接进入配图。`,
    contentHtml: `
      <div class="persona-generated-selection-list" role="radiogroup" aria-label="推文候选">
        ${candidates.map((post, index) => renderPersonaGeneratedSelectionCard(post, index, candidates, selectedId)).join("")}
      </div>
      <p class="persona-generated-selection-hint">未选择的候选将在完成当前操作后自动清理。</p>
    `,
    showCancel: false,
    showConfirm: false,
    showClose: false,
    extraActions: [
      { value: "save", text: "保存草稿" },
      { value: "media", text: "生成配图", primary: true },
      { value: "discard", text: "放弃本次结果", danger: true },
    ],
    modalKey: "persona-generated-selection",
    stack: true,
    dismissOnBackdrop: false,
    dismissOnEscape: false,
  });
  const chooserModals = document.querySelectorAll('.console-modal[data-modal-key="persona-generated-selection"]');
  const modal = chooserModals[chooserModals.length - 1] || null;
  const syncSelection = () => {
    selectedId = String(modal?.querySelector('input[name="personaGeneratedSelection"]:checked')?.value || "").trim();
    modal?.querySelectorAll("[data-persona-generated-selection-card]").forEach((card) => {
      card.classList.toggle("is-selected", String(card.dataset.personaGeneratedSelectionCard || "") === selectedId);
    });
  };
  modal?.addEventListener("change", (event) => {
    if (event.target?.matches?.('input[name="personaGeneratedSelection"]')) syncSelection();
  });
  syncSelection();
  const action = String(await request || "").trim();
  return {
    action: ["save", "media"].includes(action) ? action : "",
    postId: selectedId,
  };
}

function activePersonaGeneratePreview(persona = selectedPersona(), composeMode = "") {
  if (!persona) return null;
  const resolvedComposeMode = composeMode || personaFormState(persona?.id)?.generate?.composeMode || "tweet";
  if (resolvedComposeMode === "hot") return null;
  const runState = personaGeneratedPreviewState(persona?.id, resolvedComposeMode);
  if (!runState || runState.selectionRequired || runState.visible === false || String(runState.status || "") !== "success") return null;
  const rows = personaGeneratedPreviewPosts(persona, runState);
  return rows.length ? { persona, runState, rows } : null;
}

async function confirmLeavePersonaGeneratePreview() {
  const activePreview = activePersonaGeneratePreview();
  if (!activePreview) return true;
  const confirmed = await openConsoleModal({
    title: "退出当前预览？",
    message: "生成结果预览正在显示。确定后会关闭当前预览，再继续跳转或切换；已生成内容仍保留在草稿库。",
    confirmText: "退出并继续",
    cancelText: "留在预览",
  });
  if (!confirmed) return false;
  clearPersonaGenerateRunState(activePreview.persona.id);
  return true;
}

function activeMediaTaskResultPreview(persona = selectedPersona()) {
  if (!persona) return null;
  const { post } = personaMediaTargetPost(persona);
  if (!post) return null;
  const taskState = personaMediaTaskState(persona.id, post.id);
  if (!taskState?.taskId) return null;
  const hasSuccess = personaTaskMediaBatches(taskState).some((batch) => String(batch?.detail?.status || "").trim() === "success");
  if (!hasSuccess) return null;
  const items = personaTaskMediaItems(taskState);
  return items.length ? { persona, post, taskState, items } : null;
}

function activePersonaCreateResultPreview() {
  if (!state.personaCreateMode) return null;
  const createState = ensurePersonaCreateState();
  const aiResult = createState.aiResult && typeof createState.aiResult === "object" ? createState.aiResult : null;
  return aiResult?.id ? { createState, aiResult } : null;
}

function transientWorkspaceFingerprint(kind, value) {
  const normalize = (item) => {
    if (Array.isArray(item)) return item.map(normalize);
    if (!item || typeof item !== "object") return item;
    if (
      typeof item.name === "string"
      && Number.isFinite(Number(item.size))
      && Number.isFinite(Number(item.lastModified))
    ) {
      return {
        name: item.name,
        size: Number(item.size),
        type: String(item.type || ""),
        lastModified: Number(item.lastModified),
      };
    }
    return Object.keys(item).sort().reduce((result, key) => {
      result[key] = normalize(item[key]);
      return result;
    }, {});
  };
  return `${kind}:${JSON.stringify(normalize(value))}`;
}

function activePersonaDraftComposerTransientState(persona = selectedPersona()) {
  if (!persona || !isPersonaWorkspaceModule()) return null;
  if (state.personaGroup !== "content" || currentPersonaGroupStep("content", selectedPersonaProfile()) !== "generate") return null;
  snapshotPersonaCurrentForm();
  const form = personaFormState(persona.id);
  const draft = normalizePersonaDraftForm(form.draft);
  if (String(draft.editingPostId || "").trim()) return null;
  const composeDraftInputs = ensurePersonaComposeDraftInputs(form);
  const activeKey = personaComposeDraftInputKey(form.generate.composeMode);
  const activeInput = activeKey ? composeDraftInputs[activeKey] : null;
  const title = String(activeInput?.title || draft.title || $("personaDraftTitle")?.value || "").trim();
  const content = String(activeInput?.content || draft.content || $("personaDraftContent")?.value || "").trim();
  const hasComposeText = Object.values(composeDraftInputs).some((input) => (
    Boolean(String(input?.title || "").trim()) || Boolean(String(input?.content || "").trim())
  ));
  const fileCount = filesFromInput("personaPostMediaUploadFiles").length
    + filesFromInput("personaMediaTaskFiles").length;
  if (!hasComposeText && !fileCount) return null;
  const platform = personaContentPlatform(persona);
  return {
    kind: "persona_draft_composer",
    persona,
    title,
    content,
    fileCount,
    platform,
    guardKey: transientWorkspaceFingerprint("persona_draft_composer", {
      personaId: String(persona.id || ""),
      platform,
      composeDraftInputs,
      fileCount,
    }),
  };
}

async function confirmPersonaContentPlatformSwitch(persona, nextPlatform) {
  const currentPlatform = personaContentPlatform(persona);
  const targetPlatform = normalizePersonaContentPlatform(nextPlatform);
  if (currentPlatform === targetPlatform) return true;
  if (isActionLocked("persona", persona?.id, "generate_posts")) return false;
  const transient = activePersonaDraftComposerTransientState(persona);
  if (!transient) return true;
  const platformLabel = Object.fromEntries(accountPoolPlatforms);
  return openConsoleModal({
    title: "切换推文平台？",
    message: `当前 ${platformLabel[currentPlatform] || currentPlatform} 输入区还有未保存内容。切换到 ${platformLabel[targetPlatform] || targetPlatform} 后将清空这些临时内容。`,
    confirmText: "清空并切换",
    cancelText: "继续编辑",
    danger: true,
  });
}

function activeHotCandidateTransientState(persona = selectedPersona()) {
  if (!persona || !isPersonaWorkspaceModule()) return null;
  const form = personaFormState(persona.id).generate;
  const selectedIds = (Array.isArray(form.hotSelectedIds) ? form.hotSelectedIds : []).map((item) => String(item || "").trim()).filter(Boolean);
  const edited = form.hotEditedContentByCandidate && typeof form.hotEditedContentByCandidate === "object"
    ? Object.entries(form.hotEditedContentByCandidate).some(([candidateId, content]) => {
      const candidate = personaHotCandidates(persona).find((item) => personaHotCandidateKey(item) === String(candidateId || ""));
      if (!candidate) return String(content || "").trim();
      return String(content || "") !== String(candidate.full_content || candidate.content || "该热点没有完整正文。");
    })
    : false;
  const deletedMedia = form.hotDeletedMediaByCandidate && typeof form.hotDeletedMediaByCandidate === "object"
    ? Object.values(form.hotDeletedMediaByCandidate).some((rows) => Array.isArray(rows) && rows.length)
    : false;
  const replacementMedia = form.hotReplacementFilesByCandidate && typeof form.hotReplacementFilesByCandidate === "object"
    ? Object.values(form.hotReplacementFilesByCandidate).some((rows) => (
        Array.isArray(rows) ? rows.length > 0 : Boolean(rows && typeof rows === "object" && Object.keys(rows).length)
      ))
    : false;
  const stagedReplacementMedia = form.hotReplacementPoolByCandidate && typeof form.hotReplacementPoolByCandidate === "object"
    ? Object.values(form.hotReplacementPoolByCandidate).some((rows) => Array.isArray(rows) && rows.length)
    : false;
  const textRetained = Boolean(selectedIds.length || edited);
  const mediaEdited = deletedMedia || replacementMedia || stagedReplacementMedia;
  if (!selectedIds.length && !edited && !deletedMedia && !replacementMedia && !stagedReplacementMedia) return null;
  return {
    persona,
    selectedIds,
    edited,
    deletedMedia,
    replacementMedia,
    stagedReplacementMedia,
    textRetained,
    mediaEdited,
    guardKey: transientWorkspaceFingerprint("hot_candidates", {
      personaId: String(persona.id || ""),
      selectedIds,
      editedContent: form.hotEditedContentByCandidate || {},
      deletedMedia: form.hotDeletedMediaByCandidate || {},
      replacementMedia: form.hotReplacementFilesByCandidate || {},
      replacementPool: form.hotReplacementPoolByCandidate || {},
    }),
  };
}

function activePublishCustomTransientState() {
  if (state.activeModule !== "publishing") return null;
  const mode = normalizedPublishMode($("simplePublishMode")?.value || state.simpleBranches.publishing);
  const source = normalizePublishContentSource();
  if (mode !== "publish_now" && mode !== "schedule_publish") return null;
  if (source !== "custom") return null;
  const content = String($("simpleContent")?.value || state.publishCustomContent || "").trim();
  const files = filesFromInput("simpleMediaFiles");
  return (content || files.length) ? { content, fileCount: files.length } : null;
}

function activeMatrixPublishTransientState() {
  if (state.activeModule !== "publishing") return null;
  const mode = normalizedPublishMode($("simplePublishMode")?.value || state.simpleBranches.publishing);
  if (mode !== "matrix_start") return null;
  if ($("matrixPublishPlatform") || $("matrixPublishCount")) {
    updateMatrixPublishStateFromForm();
  }
  const selectedIds = matrixPublishSelectedIds();
  const source = "posts";
  const platform = String(state.matrixPublish.platform || "threads");
  const perPersonaCount = Number(state.matrixPublish.perPersonaCount || 1);
  const changedFromDefault = selectedIds.length > 1 || source !== "posts" || platform !== "threads" || perPersonaCount !== 1;
  return changedFromDefault ? { selectedIds, source, platform, perPersonaCount } : null;
}

function activeAutomationPlanTransientState() {
  if (state.activeModule !== "publishing") return null;
  const mode = normalizedPublishMode($("simplePublishMode")?.value || state.simpleBranches.publishing);
  if (mode !== "automation_tasks") return null;
  const persona = selectedPersona();
  const { draft, account, key } = currentAutomationPlanDraft(persona);
  const rows = normalizeAutomationPlanReservations(draft.items);
  if (!rows.some((item) => Boolean(item.configured))) return null;
  return {
    persona,
    account,
    key,
    guardKey: transientWorkspaceFingerprint("automation_plan", {
      personaId: String(persona?.id || ""),
      accountId: String(account?.id || ""),
      mode: draft.mode,
      items: rows,
    }),
  };
}

function activeTransientWorkspaceState() {
  const generatePreview = activePersonaGeneratePreview();
  if (generatePreview) {
    return {
      kind: "generated_preview",
      title: "退出当前预览？",
      message: "生成结果预览正在显示。确定后会关闭当前预览，再继续跳转或切换；已生成内容仍保留在草稿库。",
      confirmText: "退出并继续",
      cancelText: "留在预览",
      clear: () => clearPersonaGenerateRunState(generatePreview.persona.id),
    };
  }
  const mediaTaskResult = activeMediaTaskResultPreview();
  if (mediaTaskResult) {
    return {
      kind: "media_task_result",
      title: "离开媒体结果？",
      message: "媒体生成结果还没有追加或替换到当前草稿。确定离开后，本次结果预览会保留在任务记录中，但当前回写流程会被中断。",
      confirmText: "离开并继续",
      cancelText: "继续处理",
    };
  }
  const createResult = activePersonaCreateResultPreview();
  if (createResult) {
    return {
      kind: "persona_create_result",
      title: "离开新人设结果？",
      message: "AI 新建人设结果还停留在当前预览中。确定离开后仍会保留已创建的人设，但当前结果面板会关闭。",
      confirmText: "离开并继续",
      cancelText: "继续查看",
      clear: () => {
        state.personaCreateMode = false;
      },
    };
  }
  const hotState = activeHotCandidateTransientState();
  if (hotState) {
    return {
      kind: "hot_candidates",
      title: hotState.mediaEdited ? "放弃图片修改并离开？" : "暂时离开热点处理？",
      message: hotState.mediaEdited
        ? (hotState.textRetained
          ? "当前热点候选中有尚未导入草稿的图片修改。离开后，图片删除、替换和待替换文件将全部放弃并恢复为抓取原图，不会保存到草稿；正文选择与编辑仅保留在当前页面。返回“热点抓取”可继续处理，刷新或关闭页面可能导致正文内容丢失。"
          : "当前热点候选中有尚未导入草稿的图片修改。离开后，图片删除、替换和待替换文件将全部放弃并恢复为抓取原图，不会保存到草稿或继续保留在页面。")
        : "当前热点候选中有尚未导入草稿的选择或正文编辑。暂时离开后，这些内容仅保留在当前页面；返回“热点抓取”可继续处理。刷新或关闭页面可能导致内容丢失。",
      confirmText: hotState.mediaEdited ? "放弃图片修改并离开" : "暂时离开",
      cancelText: "返回处理",
      guardKey: hotState.guardKey,
      danger: hotState.mediaEdited,
      clear: hotState.mediaEdited ? () => discardPersonaHotMediaEdits(hotState.persona.id) : null,
      acknowledgeRemainingState: hotState.mediaEdited,
    };
  }
  const publishCustom = activePublishCustomTransientState();
  if (publishCustom) {
    return {
      kind: "publish_custom",
      title: "离开自定义任务？",
      message: `当前自定义任务内容${publishCustom.fileCount ? `和 ${publishCustom.fileCount} 个上传素材` : ""}还没有提交。确定离开后，上传选择可能需要重新选择。`,
      confirmText: "离开并继续",
      cancelText: "继续编辑",
    };
  }
  const automationPlan = activeAutomationPlanTransientState();
  if (automationPlan) {
    return {
      kind: "automation_plan",
      title: "暂时离开自动化计划？",
      message: "当前自动化计划配置尚未提交。切换后会按当前人设和账号保留，再次返回可继续编辑。",
      confirmText: "暂时离开",
      cancelText: "继续配置",
      guardKey: automationPlan.guardKey,
    };
  }
  const matrixState = activeMatrixPublishTransientState();
  if (matrixState) {
    return {
      kind: "matrix_publish",
      title: "离开矩阵任务配置？",
      message: "当前矩阵任务配置还没有提交。确定离开后会保留当前页面状态，但本次提交预览不会继续停留。",
      confirmText: "离开并继续",
      cancelText: "继续配置",
    };
  }
  return null;
}

async function confirmLeaveTransientWorkspaceState({ allowNextUnload = false } = {}) {
  const activeState = activeTransientWorkspaceState();
  if (!activeState) return true;
  if (
    activeState.guardKey
    && activeState.guardKey === state.transientWorkspaceLeaveAcknowledgement
  ) {
    if (allowNextUnload) state.transientWorkspaceAllowNextUnload = true;
    return true;
  }
  const confirmed = await openConsoleModal({
    title: activeState.title,
    message: activeState.message,
    confirmText: activeState.confirmText || "继续",
    cancelText: activeState.cancelText || "取消",
    danger: Boolean(activeState.danger),
  });
  if (!confirmed) return false;
  if (typeof activeState.clear === "function") {
    activeState.clear();
    const remainingState = activeState.acknowledgeRemainingState
      ? activeTransientWorkspaceState()
      : null;
    state.transientWorkspaceLeaveAcknowledgement = remainingState?.guardKey || "";
  } else if (activeState.guardKey) {
    state.transientWorkspaceLeaveAcknowledgement = activeState.guardKey;
  }
  if (allowNextUnload) state.transientWorkspaceAllowNextUnload = true;
  return true;
}

function selectGeneratedPreviewPost(postId) {
  const persona = selectedPersona();
  const cleanPostId = String(postId || "").trim();
  if (!persona || !cleanPostId) return;
  setPersonaPostSource("posts", persona);
  setSelectedPersonaPostId(cleanPostId);
  renderPersonaDetail();
  renderConfirmSummary();
}

function refreshPersonaContentPlatformSummary(persona) {
  if (!persona) return;
  const { draftCount, favoriteCount } = personaSummaryCounts(persona);
  const selectedPlatformLabel = platformLabel(personaContentPlatform(persona));
  document.querySelectorAll("#personaDetail [data-persona-platform-summary]").forEach((node) => {
    const label = node.querySelector("small");
    const value = node.querySelector("strong");
    if (label) label.textContent = selectedPlatformLabel;
    if (value) value.textContent = `草稿 ${numberText(draftCount)} · 收藏 ${numberText(favoriteCount)}`;
  });
  document.querySelectorAll("#personaDetail .persona-profile-account-status").forEach((node) => {
    node.innerHTML = renderPersonaExecutionAccountBadge(persona);
  });
}

function refreshPersonaContentPlatformPanel(persona = selectedPersona()) {
  if (!persona) return false;
  const profile = selectedPersonaProfile();
  const groupKey = normalizedPersonaGroupKey(
    state.activeModule === "tweet_generation" ? "content" : state.personaGroup,
  );
  if (groupKey !== "content") return false;
  const step = currentPersonaGroupStep(groupKey, profile);
  const contentShell = $("personaDetail")?.querySelector(".persona-step-shell");
  const contentPanel = contentShell?.querySelector(":scope > .persona-inline-panel");
  if (!contentShell || !contentPanel) return false;
  contentPanel.outerHTML = renderPersonaContentPanel(
    persona,
    accountForPersona(persona),
    profile,
    step,
  );
  refreshPersonaContentPlatformSummary(persona);
  bindPersonaDraftSaveLongPress($("personaDetail"));
  bindMobileTweetStreamObservers();
  window.requestAnimationFrame(resizePersonaDraftEditContent);
  return true;
}

function renderPersonaDetail() {
  disconnectMobileTweetStreamObserver();
  const scrollSnapshot = snapshotConsoleScrollState();
  const layoutLocks = captureConsoleLayoutLocks();
  try {
  snapshotPersonaProfileEditDraft();
  snapshotPersonaCurrentForm();
  const persona = selectedPersona();
  if (state.personaCreateMode && !isPersonaCreateModalOpen()) state.personaCreateMode = false;
  if (!persona) {
    state.renderedPersonaId = "";
    if (!state.personaOverviewLoaded) {
      $("personaDetail").innerHTML = `
        <div class="persona-inline-panel is-flat persona-first-run-loading" role="status" aria-live="polite">
          <strong>正在准备你的人设工作区...</strong>
        </div>`;
      return;
    }
    if (!state.personas.length) {
      $("personaDetail").innerHTML = `
        <div class="persona-inline-panel is-flat persona-first-run-empty">
          <div class="persona-first-run-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.5"></circle><path d="M5.5 19c.8-4 3-6 6.5-6s5.7 2 6.5 6"></path><path d="M19 8v5"></path><path d="M16.5 10.5h5"></path></svg>
          </div>
          <div class="persona-first-run-copy">
            <span>新手第 1 步</span>
            <strong>先创建你的第一个人设</strong>
            <p>告诉它叫什么、怎么说话、准备创作哪类内容。以后生成推文、配图和发布任务时，就不用每次从头设置。</p>
            <small>创建完成后，我们会继续带你绑定账号；资料不用一次填满，之后随时都能修改。</small>
          </div>
          <div class="row-actions persona-first-run-actions">
            <button type="button" class="primary" data-persona-open-create>
              <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14"></path><path d="M5 12h14"></path></svg>
              <span>创建第一个人设</span>
            </button>
          </div>
        </div>`;
      return;
    }
    $("personaDetail").innerHTML = `
      <div class="persona-inline-panel is-flat">
        <strong>请选择一个人设</strong>
        <p>右侧人设列表只负责选择和管理；中间工作区会根据当前人设显示具体参数与操作。</p>
        <div class="row-actions">
          <button type="button" class="primary" data-persona-open-create>新建人设</button>
        </div>
      </div>`;
    return;
  }
  const profile = selectedPersonaProfile();
  if (!profile) loadPersonaProfile(persona.id).catch(() => {});
  if (!state.personaDraftPosts[String(persona.id)]) loadPersonaDraftPosts(persona.id).catch(() => {});
  if (!state.personaFavoritePosts[String(persona.id)]) loadPersonaFavoritePosts(persona.id).catch(() => {});
  const groupKey = normalizedPersonaGroupKey(state.activeModule === "tweet_generation" ? "content" : (state.personaGroup || personaModuleDefaultGroup()));
  state.personaGroup = groupKey;
  const step = currentPersonaGroupStep(groupKey, profile);
  if (groupKey === "content" && step === "generate" && !Array.isArray(state.personaMemories[String(persona.id)])) {
    loadPersonaMemories(persona.id).catch(() => {});
  }
  if (groupKey === "settings" && step === "profile") {
    if (!personaImageLibraryState(persona.id)) loadPersonaImageLibrary(persona.id).catch(() => {});
    if (!Array.isArray(state.personaPublishHistories[String(persona.id)])) loadPersonaPublishHistory(persona.id).catch(() => {});
  }
  if (groupKey === "content" && step === "publish") {
    ensurePersonaPublishResultLoaded(persona.id).catch(() => {});
  }
  if (groupKey === "content" && (step === "posts" || step === "history") && !Array.isArray(state.personaPublishHistories[String(persona.id)])) {
    loadPersonaPublishHistory(persona.id).catch(() => {});
  }
  const account = accountForPersona(persona);
  const groupPanel = renderPersonaGroupPanel(groupKey, step, persona, account, profile);
  $("personaDetail").classList.toggle("persona-detail--content", groupKey === "content");
  const personaDetailSummary = [
    state.activeModule === "tweet_generation"
      ? renderPersonaProfileIdentity(persona, profile, {
        compact: true,
        sidebarId: "personaWorkspaceSidebar",
      })
      : "",
    showPersonaGroupTabs() ? renderPersonaGroupTabs(profile) : "",
  ].filter(Boolean).join("");
  $("personaDetail").innerHTML = `
    ${personaDetailSummary ? `<div class="persona-detail-summary-panel">${personaDetailSummary}</div>` : ""}
    <div class="persona-step-shell">
      ${renderPersonaStepTabs(groupKey, profile)}
      ${groupPanel}
    </div>
  `;
  state.renderedPersonaId = String(persona.id || "");
  bindPersonaAccountPlatformSwipe($("personaDetail"));
  bindPersonaDraftSaveLongPress($("personaDetail"));
  bindMobileTweetStreamObservers();
  syncPersonaPostGenerationInteractionLock();
  window.requestAnimationFrame(resizePersonaDraftEditContent);
  } finally {
    restoreConsoleScrollState(scrollSnapshot);
    releaseConsoleLayoutLocks(layoutLocks);
  }
}

function renderPersonaContentPanel(persona, account, profile, step) {
  const panel = step || "overview";
  const drafts = personaDraftPosts(persona);
  const favorites = personaFavoritePosts(persona);
  const postSource = personaPostSource(persona);
  const sourceRows = personaSourcePosts(persona, postSource);
  const memoryRows = personaMemoryRows(persona);
  const publishResult = state.personaPublishResults[String(persona.id)] || "";
  const form = personaFormState(persona.id);
  const generateForm = form.generate;
  const draftForm = form.draft;
  const isWorkflowPersona = false;
  const showTimeSlot = false;
  const isEditingDraft = Boolean(String(draftForm.editingPostId || "").trim());
  const composeModeValue = String(generateForm.composeMode || "tweet");
  const composeMode = isEditingDraft
    ? "tweet"
    : (["tweet_media", "hot"].includes(composeModeValue) ? composeModeValue : "tweet");
  // A draft edit is a single, dedicated workflow. Never let a stale compose
  // mode replace it with the new-post form while the draft remains open.
  const generateMode = isEditingDraft
    ? "custom"
    : (composeMode === "hot" ? "hot" : "ai");
  const editingSource = draftForm.editingSource === "favorites" ? "favorites" : "posts";
  const editingRows = personaSourcePosts(persona, editingSource);
  const editingDraft = isEditingDraft ? editingRows.find((post) => String(post.id) === String(draftForm.editingPostId || "").trim()) || null : null;
  const editingHotMeta = editingDraft ? personaHotImportMeta(persona.id, editingDraft.id) : null;
  const editingDirty = isEditingDraft && syncPersonaDraftDirty(draftForm);
  const preflight = personaGeneratePreflight();
  const hiddenHistoryCount = personaHiddenPublishHistoryCount(persona);
  const hiddenHistoryHint = hiddenHistoryCount > 0 ? ` 当前另有 ${hiddenHistoryCount} 条登录或预检记录，未计入任务历史。` : "";
  const generateDefaults = personaGenerateDefaults();
  const editingSourceLabel = editingSource === "favorites" ? "收藏" : "草稿";
  const generateTitle = generateMode === "hot" ? "新建推文" : (isEditingDraft ? `编辑${editingSourceLabel}` : "新建推文");
  const canComposeMedia = composeMode !== "hot";
  const isBatchCompose = composeMode === "tweet_media";
  if (!String(draftForm.content || "").trim() && String(generateForm.prompt || "").trim()) {
    draftForm.content = String(generateForm.prompt || "");
    generateForm.prompt = "";
  }
  const currentGenerateCount = Math.min(Math.max(Number(generateForm.count || generateDefaults.count), 1), PERSONA_GENERATE_MAX_COUNT);
  generateForm.count = currentGenerateCount;
  generateForm.targetWords = Math.min(Math.max(Number(generateForm.targetWords || generateDefaults.targetWords), 10), 2000);
  const selectedPostBase = selectedPersonaPost(persona, { requireExplicit: panel === "generate" && composeMode === "tweet_media" });
  const focusedOrdinaryPostId = String(form.media?.focusPostId || "").trim();
  const selectedPost = isEditingDraft
    ? editingDraft
    : (panel === "generate" && composeMode === "tweet"
      ? (focusedOrdinaryPostId
        ? personaSourcePosts(persona).find((item) => String(item.id) === focusedOrdinaryPostId) || null
        : null)
      : selectedPostBase);
  const ordinaryMediaTarget = composeMode === "tweet"
    && Boolean(focusedOrdinaryPostId)
    && String(selectedPost?.id || "").trim() === focusedOrdinaryPostId;
  const selectedMediaSource = isEditingDraft ? editingSource : postSource;
  const selectedSourceLabel = selectedMediaSource === "favorites" ? "收藏" : "草稿";
  const selectedPostMediaItems = selectedPost ? personaDraftMediaPreviewItems(persona, selectedMediaSource, selectedPost) : [];
  const generateIntro = generateMode === "hot"
    ? "按当前人设与记忆抓取 Threads / Instagram 热点候选。"
    : (isEditingDraft
      ? "可修改正文、媒体或 AI 重写。"
      : `这里处理推文内容。已识别 ${memoryRows.length} 条可选记忆。`);
  const generationLocked = isActionLocked("persona", persona.id, "generate_posts");
  const postDirectionsLocked = isActionLocked("persona", persona.id, "post_directions");
  const generationControlsLocked = generationLocked || postDirectionsLocked;
  const activeGenerateComposeMode = String(personaGenerateRunState(persona.id)?.composeMode || composeMode);
  const generateBusy = generationLocked && activeGenerateComposeMode === composeMode;
  const directionState = personaPostDirectionState(persona.id, composeMode);
  const directionButtonContent = directionState.keywords.length && !directionState.selectedKeywords.length
    ? `${renderRefreshIcon()}<span>换一批</span>`
    : "AI 生成";
  const hotImportBusy = isActionLocked("persona", persona.id, "hot_import");
  const generatePreviewDock = renderPersonaGeneratePreviewDock(persona, composeMode);
  const hasComposeAside = canComposeMedia || Boolean(generatePreviewDock);

  if (panel === "generate") {
    return `
      <div class="persona-inline-panel persona-generate-panel ${isEditingDraft ? "is-editing-draft" : ""} ${editingDirty ? "is-dirty" : ""}">
        ${!isEditingDraft ? `
          <div class="persona-head-copy persona-head-copy--split">
            <div class="persona-head-copy-main">
              <strong>${esc(generateTitle)}</strong>
              ${generateIntro
                ? `<span class="persona-panel-intro" data-i18n-ui>${esc(generateIntro)}</span>`
                : `<span class="persona-panel-intro persona-panel-intro--reserved" aria-hidden="true">&nbsp;</span>`}
            </div>
          </div>
        ` : ""}
        ${renderPersonaContentPlatformRail(persona, {
          disabled: isEditingDraft || generationControlsLocked || hotImportBusy,
          showHotCandidateBadges: composeMode === "hot",
        })}
        <div class="persona-compose-workspace ${hasComposeAside ? "has-media" : ""}">
          <section class="persona-compose-post-side persona-production-section ${isEditingDraft ? "is-editing-draft" : ""} ${editingDirty ? "is-dirty" : ""}">
            ${isEditingDraft ? `
              <div class="persona-temp-edit-actions persona-temp-edit-actions--inline">
                <div class="persona-temp-edit-copy">
                  <strong>${esc(generateTitle)}</strong>
                  <span>编辑中 · 可修改正文、媒体或 AI 重写。</span>
                </div>
                <div class="persona-temp-edit-icon-actions" aria-label="草稿编辑操作">
                  <button type="button" class="unified-action-icon-button" data-persona-clear-draft-edit title="清空" aria-label="清空">${renderClearSelectionIcon()}</button>
                  <button type="button" class="unified-action-icon-button" data-persona-exit-draft-edit title="退出编辑" aria-label="退出编辑">${renderCloseIcon()}</button>
                </div>
              </div>
            ` : ""}
            <div class="persona-compose-mode-slot">
              ${renderPersonaGenerateComposeTabs(composeMode, {
                editingDraft: isEditingDraft,
                disabled: generationControlsLocked,
              })}
            </div>
            ${isEditingDraft ? `<p class="persona-compose-lock-hint" role="status">正在编辑单条草稿，批量推文和热点抓取不可用；请先保存或退出编辑后切换。</p>` : ""}
            ${isBatchCompose && generateMode === "ai" ? `
              <div class="persona-generate-current-settings">
                <label>本次生成数量
                  <select id="personaGenerateCount">
                    ${Array.from({ length: PERSONA_GENERATE_MAX_COUNT }, (_, index) => index + 1)
                      .map((count) => `<option value="${count}" ${count === currentGenerateCount ? "selected" : ""}>${count} 篇</option>`)
                      .join("")}
                  </select>
                </label>
                <label>目标字数
                  <input id="personaGenerateTargetWords" type="number" min="10" max="2000" step="10" value="${esc(generateForm.targetWords)}" />
                </label>
              </div>
            ` : ""}
        ${generateMode === "custom" ? `
          ${!isEditingDraft && editingHotMeta ? renderPersonaHotOrigin(editingHotMeta) : ""}
          <label>草稿标题（可选）
            <input id="personaDraftTitle" value="${esc(draftForm.title || "")}" placeholder="例如：今日主题帖" />
          </label>
          <label>自定义正文
            <textarea id="personaDraftContent" class="persona-draft-content--full" rows="6" placeholder="直接输入本次要保存的推文正文。">${esc(draftForm.content || "")}</textarea>
          </label>
          ${isEditingDraft ? `<div class="row-actions persona-generate-actions persona-generate-actions--editing">
              <button type="button" data-persona-stash-draft-edit>暂存草稿</button>
              ${renderPersonaWritingLocaleSelect(generateForm.writingLocale, generationLocked)}
              <button type="button" class="primary persona-generate-ai-action" data-persona-generate-posts aria-label="使用 AI 重新生成当前推文" ${preflight.ready && !generationLocked ? "" : "disabled"}>${generateBusy ? renderBusyButtonContent("正在重新生成", true, actionLockStartedAt("persona", persona.id, "generate_posts")) : "AI 重新生成"}</button>
          </div>` : ""}
        ` : generateMode === "hot" ? `
          ${renderPersonaHotCandidatePicker(persona, generateForm)}
          ${personaHotCandidates(persona).length ? `<div class="persona-draft-global-save-dock persona-hot-import-dock">
            <button type="button" class="primary persona-draft-global-save-button persona-gradient-outline-action" data-persona-import-hot-drafts ${personaHotSelectedCandidates(persona).length && !hotImportBusy ? "" : "disabled"}>${hotImportBusy ? renderBusyButtonContent("正在导入热点", true, actionLockStartedAt("persona", persona.id, "hot_import")) : "导入到当前人设草稿库"}</button>
          </div>` : ""}
        ` : `
          <label>草稿标题（可选）
            <input id="personaDraftTitle" value="${esc(draftForm.title || "")}" placeholder="输入便于管理和识别的草稿标题" ${postDirectionsLocked ? "disabled" : ""} />
          </label>
          <label>推文内容（可选）
            <textarea id="personaDraftContent" rows="6" placeholder="留空由 AI 按当前人设生成；输入内容后可保存草稿或使用 AI 润色。" ${postDirectionsLocked ? "disabled" : ""}>${esc(draftForm.content || "")}</textarea>
          </label>
          ${!preflight.ready ? `<div class="persona-warning-inline">${esc(preflight.issues.join(" / "))}，请先补齐配置。</div>` : ""}
          <label>可选人设记忆（已识别 ${esc(memoryRows.length)} 条）</label>
          ${renderPersonaMemoryOptions(persona, generateForm.selectedMemoryIds || [])}
          ${renderPersonaPostDirectionPicker(persona, generateForm, generationControlsLocked)}
          <div class="row-actions persona-generate-actions">
            ${isEditingDraft ? `<button type="button" data-persona-create-post>保存修改</button>` : ""}
            ${renderPersonaWritingLocaleSelect(generateForm.writingLocale, generationControlsLocked)}
            <button type="button" class="primary persona-generate-ai-action" data-persona-generate-posts aria-label="${directionState.selectedKeywords.length ? "按已选方向生成推文" : (directionState.keywords.length ? "重新生成一批推文方向关键词" : "生成推文方向关键词")}" ${preflight.ready && !generationControlsLocked ? "" : "disabled"}>${generateBusy ? renderBusyButtonContent("正在生成草稿", true, actionLockStartedAt("persona", persona.id, "generate_posts")) : (postDirectionsLocked ? renderBusyButtonContent("正在生成方向", true, actionLockStartedAt("persona", persona.id, "post_directions")) : directionButtonContent)}</button>
          </div>
        `}
          </section>
          ${hasComposeAside ? `
            <div class="persona-compose-media-stack">
              ${generatePreviewDock}
              ${renderPublishLinkSettings(persona)}
              ${canComposeMedia ? ((isEditingDraft || isBatchCompose || ordinaryMediaTarget || composeMode === "tweet")
                ? renderPersonaInlineMediaComposer(persona, profile, generateForm, form.media, selectedPost, selectedPostMediaItems, selectedSourceLabel, selectedMediaSource === "favorites", composeMode)
                : renderPersonaMediaComposerPlaceholder(persona, form.media)) : ""}
            </div>
          ` : ""}
        </div>
        ${!isEditingDraft && generateMode !== "hot" ? `
          <div class="persona-draft-global-save-dock persona-compose-save-dock">
            <button type="button" class="primary persona-draft-global-save-button persona-gradient-outline-action" data-persona-create-post>保存草稿</button>
          </div>
        ` : ""}
        ${isEditingDraft ? `
          <div class="persona-draft-global-save-dock" data-persona-draft-save-dock>
            <div class="persona-draft-save-floating-actions" aria-hidden="true" aria-label="编辑操作">
              <button type="button" class="danger unified-action-icon-button" data-persona-clear-draft-edit title="清空" aria-label="清空">${renderClearSelectionIcon()}</button>
              <button type="button" class="unified-action-icon-button" data-persona-exit-draft-edit title="退出编辑" aria-label="退出编辑">${renderCloseIcon()}</button>
            </div>
            <button type="button" class="publish-mobile-selection-cancel persona-draft-save-cancel" data-persona-cancel-draft-edit aria-hidden="true">取消</button>
            <button type="button" class="primary persona-draft-global-save-button persona-gradient-outline-action" data-persona-create-post aria-expanded="false">保存修改</button>
          </div>
        ` : ""}
      </div>`;
  }

  if (panel === "media") {
    const mediaForm = form.media;
    const post = selectedPost;
    const mediaRows = sourceRows;
    const isFavoriteMedia = postSource === "favorites";
    const sourceLabel = isFavoriteMedia ? "收藏" : "草稿";
    const postMediaItems = post ? personaDraftMediaPreviewItems(persona, isFavoriteMedia ? "favorites" : "posts", post) : [];
    const mediaTaskOptions = personaMediaTaskOptions(profile, generateForm);
    const currentTaskType = mediaTaskOptions.some(([value]) => value === String(mediaForm.taskType || ""))
      ? String(mediaForm.taskType || "")
      : String(mediaTaskOptions[0]?.[0] || "persona_post_image");
    mediaForm.taskType = currentTaskType;
    normalizePersonaMediaGenerationForm(mediaForm);
    const showAspectRatio = currentTaskType === "persona_post_image";
    const showVideoOptions = false;
    const mediaBusy = post && (isActionLocked("media_task", persona.id, post.id, currentTaskType) || personaMediaTaskIsActive(persona.id, post.id, currentTaskType));
    const mediaBusyStartedAt = post ? personaMediaTaskStartedAt(persona.id, post.id, currentTaskType) : 0;
    const mediaTaskState = post ? personaMediaTaskState(persona.id, post.id) : null;
    const mediaModifyItem = personaTaskMediaModifyItem(mediaTaskState);
    const mediaModifyActive = Boolean(mediaModifyItem);
    const mediaEditSourceUploadActive = mediaModifyActive && mediaModifyItem?.inputId === "personaMediaEditSourceFile";
    const aiUploadSelectsModify = personaDraftMediaTargetIsEditing(persona);
    const mediaUploadInputId = mediaEditSourceUploadActive ? "personaMediaEditSourceFile" : "personaMediaTaskFiles";
    return `
      <div class="persona-inline-panel">
        <div class="persona-head-copy">
          <strong>推文配图 / 媒体</strong>
        </div>
        <div class="persona-draft-toolbar">
          <label>当前${sourceLabel}
            <select id="personaDraftPostSelect">
              ${mediaRows.length ? mediaRows.map((post, index) => `<option value="${esc(post.id)}" ${String(post.id) === String(state.selectedPersonaPostId || mediaRows[0]?.id || "") ? "selected" : ""}>${esc(personaDraftOptionLabel(post, index))}</option>`).join("") : `<option value="">当前还没有${sourceLabel}</option>`}
            </select>
          </label>
          <div class="row-actions">
            <button type="button" data-persona-route-step="content:generate">返回新建推文</button>
            <button type="button" data-persona-route-step="content:posts">查看列表</button>
          </div>
        </div>
        ${post ? `
          <div class="persona-media-workspace">
            <section class="persona-media-column">
              <div class="persona-inline-panel persona-inline-panel--nested">
                <strong>当前${sourceLabel}正文</strong>
                ${renderPersonaHotOrigin(personaHotImportMeta(persona.id, post.id), { compact: true })}
                <p>${esc(String(post.content || "").trim() || `当前${sourceLabel}没有正文。`)}</p>
              </div>
              <div class="persona-inline-panel persona-inline-panel--nested">
                <strong>媒体编辑</strong>
                ${renderPersonaEditableMediaGrid(postMediaItems, {
                  personaId: persona.id,
                  source: isFavoriteMedia ? "favorites" : "posts",
                  postId: post.id,
                  sourceLabel,
                })}
              </div>
            </section>
            <section class="persona-media-column">
              ${isFavoriteMedia ? `
              <div class="persona-inline-panel persona-inline-panel--nested">
                <strong>收藏媒体</strong>
                <span class="persona-panel-intro">收藏内容支持添加、编辑和删除媒体；生成新的配图请先复制为草稿后处理。</span>
              </div>
              ` : `
              <div class="persona-inline-panel persona-inline-panel--nested">
                <strong>生成媒体</strong>
                <div class="form-grid persona-detail-controls">
                  <label>生成张数
                    <select id="personaMediaImageCount" ${mediaModifyActive ? "disabled title=\"局部修改每次只生成 1 张图片\"" : ""}>
                      ${[1, 2, 3, 4].map((count) => `<option value="${count}" ${count === Number(mediaForm.imageCount) ? "selected" : ""}>${count} 张</option>`).join("")}
                    </select>
                  </label>
                  ${showAspectRatio ? `<label>图像比例
                    <select id="personaMediaAspectRatio">
                      <option value="auto" ${String(mediaForm.aspectRatio || "auto") === "auto" ? "selected" : ""}>自动</option>
                      <option value="1:1" ${String(mediaForm.aspectRatio || "") === "1:1" ? "selected" : ""}>1:1</option>
                      <option value="3:4" ${String(mediaForm.aspectRatio || "") === "3:4" ? "selected" : ""}>3:4</option>
                      <option value="4:3" ${String(mediaForm.aspectRatio || "") === "4:3" ? "selected" : ""}>4:3</option>
                      <option value="9:16" ${String(mediaForm.aspectRatio || "") === "9:16" ? "selected" : ""}>9:16</option>
                      <option value="16:9" ${String(mediaForm.aspectRatio || "") === "16:9" ? "selected" : ""}>16:9</option>
                    </select>
                  </label>` : ""}
                  ${showVideoOptions ? `<label>视频分辨率
                    <select id="personaMediaResolution">
                      <option value="720p" ${String(mediaForm.resolution || "720p") === "720p" ? "selected" : ""}>720p</option>
                      <option value="1080p" ${String(mediaForm.resolution || "") === "1080p" ? "selected" : ""}>1080p</option>
                    </select>
                  </label>` : ""}
                  ${showVideoOptions ? `<label>时长（秒）
                    <input id="personaMediaDuration" type="number" min="2" max="15" value="${esc(mediaForm.duration || 2)}" />
                  </label>` : ""}
                </div>
                ${renderPersonaMediaPromptField(mediaForm, mediaTaskState)}
              </div>
              <div class="persona-inline-panel persona-inline-panel--nested persona-media-preview-surface" data-persona-media-preview-surface>
                <strong>任务结果预览</strong>
                ${mediaEditSourceUploadActive ? renderUploadDropzone("personaMediaEditSourceFile", {
                  label: "上传替换编辑图片",
                  accept: "image/*",
                  hint: "可用一张自定义图片替换当前编辑源；仅支持图片。",
                  multiple: false,
                  imageEditSource: true,
                  publicMediaCards: true,
                  embeddedPreview: true,
                }) : renderUploadDropzone("personaMediaTaskFiles", {
                  label: "添加媒体",
                  accept: "image/*",
                  hint: "仅支持图片；可作为 AI 生成的参考素材。",
                  multiple: !aiUploadSelectsModify,
                  publicMediaCards: true,
                  embeddedPreview: true,
                })}
                ${renderPersonaMediaTaskResult(persona.id, post.id, { mediaBusy, mediaBusyStartedAt, addMediaInputId: mediaUploadInputId })}
              </div>
              `}
            </section>
          </div>
        ` : renderModuleEmptyState({
          icon: "media",
          title: `当前还没有${sourceLabel}`,
          detail: "先选择内容，再回来处理媒体",
        })}
      </div>`;
  }

  if (panel === "posts") {
    const draftViewMode = personaDraftViewMode(persona.id);
    const postPageInfo = personaPostPageInfo(persona, postSource, sourceRows);
    const selectedPostCount = syncPersonaSelectedPostIds(persona, postSource, sourceRows).length;
    if (!state.personaFavoritePosts[String(persona.id)]) loadPersonaFavoritePosts(persona.id).catch(() => {});
    return `
      <div class="persona-inline-panel">
        <div class="persona-head-copy">
          <strong>${postSource === "favorites" ? "收藏推文" : "草稿库"}</strong>
          <span class="persona-panel-intro">${esc(`这里集中查看并选择待执行内容。当前草稿 ${drafts.length} 条，收藏 ${favorites.length} 条。`)}</span>
        </div>
        ${renderPersonaContentPlatformRail(persona)}
        <div class="persona-draft-toolbar persona-draft-toolbar--posts">
          ${renderPersonaPostBulkActions(persona, postSource, sourceRows)}
          <div class="row-actions persona-draft-toolbar-actions">
            <button type="button" class="primary persona-post-bulk-execute" data-persona-post-bulk="execute" data-persona-post-bulk-source="${esc(postSource)}" ${selectedPostCount ? "" : "disabled"}>全部执行</button>
            ${renderPersonaDraftViewToggle(draftViewMode)}
          </div>
        </div>
        ${renderPersonaDraftRows(postPageInfo.items, postSource, sourceRows)}
        ${renderPersonaPostPager(postPageInfo, postSource)}
      </div>`;
  }

  if (panel === "history") {
    const historyRows = personaPublishHistoryRows(persona);
    return `
      <div class="persona-inline-panel">
        <div class="persona-head-copy">
          <strong>任务历史</strong>
          <span class="persona-panel-intro">${esc(`这里集中查看当前人设的已执行记录。当前草稿 ${drafts.length} 条，任务历史 ${historyRows.length} 条。${hiddenHistoryHint}`)}</span>
        </div>
        ${renderPersonaPostsViewTabs(drafts, historyRows, "history")}
        ${renderPersonaHistoryRows(historyRows, { hiddenCount: hiddenHistoryCount })}
      </div>`;
  }

  if (panel === "publish") {
    const publishAccounts = publishPlatformAccountsForPersona(persona);
    const publishAccount = selectedPublishAccountForPersona(persona);
    const publishHint = publishPlatformHint(publishAccount);
    const publishSource = personaPostSource(persona);
    const publishSourceLabel = publishSource === "favorites" ? "收藏推文" : "草稿";
    const publishCanSubmit = canSubmitPublishWithAccount(publishAccount);
    const publishTask = publishCanSubmit && selectedPost
      ? activeSocialTaskFor({ accountId: publishAccount.id, personaId: persona.id, taskType: "publish_post", postId: selectedPost.id, postSource: publishSource })
      : null;
    const publishBusy = publishCanSubmit && selectedPost
      ? (isActionLocked("publish", publishSource, persona.id, selectedPost.id, publishAccount.id) || publishTask)
      : false;
    const publishWaitsForManualLogin = Boolean(publishTask && socialTaskWaitsForManualLogin(publishTask));
    const publishBusyStartedAt = actionTaskStartedAt(publishTask, "publish", publishSource, persona.id, selectedPost?.id || "", publishAccount?.id || "");
    return `
      <div class="persona-inline-panel persona-publish-panel">
        <div class="persona-head-copy">
          <strong>任务前检查</strong>
          <span class="persona-panel-intro">${esc(publishAccount ? (isReadyPublishAccount(publishAccount) ? `${publishPlatformLabel(publishAccount)} · ${publishHint}` : publishAccountBlockMessage(publishAccount)) : "当前人设还没有绑定 Threads 或 Instagram 执行账号。请到账号管理绑定账号后再发布。")}</span>
        </div>
        ${renderPersonaPublishPreflight(publishAccount)}
        <div class="form-grid persona-detail-controls">
          <label class="account-field">
            ${renderAccountFieldHead("执行账号", publishAccount)}
            <select id="personaPublishAccountSelect" ${publishAccounts.length ? "" : "disabled"}>
              ${publishAccounts.length ? publishAccounts.map((entry) => `<option value="${esc(entry.id)}" ${String(entry.id) === String(publishAccount?.id || "") ? "selected" : ""}>${esc(accountDisplayName(entry))}</option>`).join("") : `<option value="">当前没有可发布账号</option>`}
            </select>
          </label>
          <label>任务${publishSourceLabel}
            <select id="personaDraftPostSelect" ${sourceRows.length ? "" : "disabled"}>
              ${sourceRows.length ? sourceRows.map((post, index) => `<option value="${esc(post.id)}" ${String(post.id) === String(state.selectedPersonaPostId || sourceRows[0]?.id || "") ? "selected" : ""}>${esc(personaDraftOptionLabel(post, index))}</option>`).join("") : `<option value="">当前还没有可发布内容</option>`}
            </select>
          </label>
        </div>
        ${personaPublishPreview(selectedPost)}
        ${renderUploadDropzone("personaPublishFiles", { label: "任务素材", hint: publishHint || "拖动图片或视频到这里，或点击选择。" })}
        <div class="row-actions">
          <button type="button" class="primary persona-gradient-outline-action" data-persona-publish-submit ${dailyPublishActionAttrs()} ${(publishCanSubmit && selectedPost && !publishBusy) ? "" : "disabled"}>${dailyPublishIsLocked() ? "今日任务已锁定" : (publishWaitsForManualLogin ? "等待人工验证" : (publishBusy ? renderBusyButtonContent("任务执行中", true, publishBusyStartedAt) : "执行任务"))}</button>
          ${renderPublishAssistanceRestoreButton()}
        </div>
        <div id="personaPublishResult">${publishResult || renderModuleEmptyState({
          icon: "task",
          title: "等待执行结果",
          detail: "提交后，这里会显示任务状态、截图和执行结果",
        })}</div>
      </div>`;
  }

  return `
    <div class="form-grid">
      <div class="persona-inline-panel">
        <p>${esc(persona.content || "暂无人设描述。")}</p>
      </div>
      <div class="persona-inline-panel">
        <p>帖子 ${numberText(persona.counts?.posts)} · 已发布 ${numberText(persona.counts?.published)} · 素材图 ${numberText(persona.counts?.images)}</p>
        <p>当前主链路只保留：人设信息、草稿创建、素材处理、自动化执行结果；任务和矩阵任务统一在外层入口执行。</p>
      </div>
    </div>`;
}

async function loadTasks() {
  const [data, socialTasksData] = await Promise.all([
    api("/api/tasks"),
    loadAutomationTasksShared(),
  ]);
  state.tasks = Array.isArray(data.items) ? data.items : (Array.isArray(data.tasks) ? data.tasks : []);
  await restorePersonaMediaTasksFromTaskList(state.tasks);
  state.socialTasks = Array.isArray(socialTasksData.tasks) ? socialTasksData.tasks : (Array.isArray(state.socialTasks) ? state.socialTasks : []);
  const reopenTaskQueuePersonaSidebar = Boolean(
    document.getElementById("taskQueuePersonaSidebar")?.classList.contains("is-mobile-open")
  );
  const host = $("taskTable");
  host.innerHTML = renderTaskQueueView();
  if (state.view === "tasks") {
    setPersonaMobileSidebarOpen(reopenTaskQueuePersonaSidebar, "taskQueuePersonaSidebar");
  }
  bindMobileTweetStreamObservers();
  syncMobilePageToolbar();
}

async function showTaskDetail(id) {
  const task = await api(`/api/tasks/${encodeURIComponent(id)}`);
  const logs = Array.isArray(task.logs) ? task.logs : [];
  await openConsoleModal({
    title: "任务详情",
    contentHtml: renderTaskDetailLayout(task, logs, {
      kind: "regular",
      title: task.workflow_name || task.type || "任务",
      downloadUrl: task.has_download ? `/api/tasks/${encodeURIComponent(task.id || id)}/download` : "",
    }),
    confirmText: "关闭",
    showCancel: false,
  });
}

async function loadSocialOverview() {
  const publishPolicyRequestSeq = beginDailyPublishPolicyRequest();
  const overview = await api("/api/persona_dashboard/automation/overview");
  if (overview?.publish_policy) updateDailyPublishPolicy(overview.publish_policy, { requestSeq: publishPolicyRequestSeq });
  const worker = overview.worker || overview.worker_state || {};
  const workerState = $("workerState");
  const workerDetail = $("workerDetail");
  if (workerState) workerState.textContent = worker.running ? "运行中" : (worker.enabled === false ? "已关闭" : "待命");
  if (workerDetail) workerDetail.textContent = worker.last_error || `最近任务：${worker.last_task_id || "-"}`;
  return overview;
}

async function fetchSocialDataShared({ force = false } = {}) {
  if (force) {
    while (state.socialRefreshFetch) {
      await state.socialRefreshFetch.catch(() => {});
    }
  } else if (state.socialRefreshFetch) {
    return state.socialRefreshFetch;
  }
  const request = Promise.all([
    loadSocialOverview().catch(() => ({})),
    api("/api/persona_dashboard/automation/accounts").catch((error) => ({ accounts: tenantArrayFallback(error, state.socialAccounts) })),
    api("/api/persona_dashboard/automation/proxies").catch((error) => ({ proxies: tenantArrayFallback(error, state.socialProxies) })),
    loadAutomationTasksShared({ force }).catch((error) => ({ tasks: tenantArrayFallback(error, state.socialTasks) })),
  ]).then(([overview, accountsData, proxiesData, tasksData]) => {
    state.socialBrowserSessions = Array.isArray(overview.browser_sessions) ? overview.browser_sessions : tenantArrayFallback(null, state.socialBrowserSessions);
    state.socialAccounts = Array.isArray(accountsData.accounts) ? accountsData.accounts : [];
    state.socialProxies = Array.isArray(proxiesData.proxies)
      ? proxiesData.proxies
      : (Array.isArray(overview.proxies) ? overview.proxies : tenantArrayFallback(null, state.socialProxies));
    state.socialTasks = Array.isArray(tasksData.tasks) ? tasksData.tasks : [];
    state.socialDataLoadedAt = Date.now();
    saveSocialAccountsSnapshot();
    return overview;
  }).finally(() => {
    if (state.socialRefreshFetch === request) state.socialRefreshFetch = null;
  });
  state.socialRefreshFetch = request;
  return request;
}

async function loadSocial({ render = true, force = false } = {}) {
  const overview = await fetchSocialDataShared({ force });
  if (render) {
    clearAccountPasswordRevealState();
    renderSocialAccounts();
    renderSocialTasks();
    syncStandaloneSocialForm();
    if (isPersonaWorkspaceModule()) renderPersonaModule();
    if (state.activeModule && ["publishing", "automation"].includes(state.activeModule)) renderSimpleFlowModule(state.activeModule);
  } else {
    syncStandaloneSocialForm();
  }
  syncAccountStatusAutoRefresh();
  return overview;
}

function cancelScheduledSocialViewRefresh() {
  const handle = state.socialViewRefreshHandle;
  if (handle) {
    if (typeof window.cancelIdleCallback === "function") window.cancelIdleCallback(handle);
    else window.clearTimeout(handle);
  }
  state.socialViewRefreshHandle = 0;
  state.socialViewRefreshTarget = "";
}

function scheduleSocialViewRefresh(view = state.view) {
  const targetView = ["social", "accounts"].includes(view) ? view : "";
  if (!targetView) return;
  if (state.socialViewRefreshHandle) {
    if (state.socialViewRefreshTarget === targetView) return;
    cancelScheduledSocialViewRefresh();
  }
  if (state.socialDataLoadedAt && Date.now() - state.socialDataLoadedAt < 15000) return;
  const refresh = () => {
    state.socialViewRefreshHandle = 0;
    state.socialViewRefreshTarget = "";
    if (state.view !== targetView) return;
    loadSocial({ render: false }).then(() => {
      if (state.view !== targetView) return;
      renderSocialAccounts();
      if (targetView === "social") renderSocialTasks();
    }).catch(() => {});
  };
  state.socialViewRefreshTarget = targetView;
  state.socialViewRefreshHandle = typeof window.requestIdleCallback === "function"
    ? window.requestIdleCallback(refresh, { timeout: 1200 })
    : window.setTimeout(refresh, 240);
}

async function refreshSocialAccountsOnly({ force = false, includeOverview = false } = {}) {
  if (includeOverview) {
    await fetchSocialDataShared({ force });
  } else {
    const accountsData = await api("/api/persona_dashboard/automation/accounts")
      .catch((error) => ({ accounts: tenantArrayFallback(error, state.socialAccounts) }));
    state.socialAccounts = Array.isArray(accountsData.accounts) ? accountsData.accounts : [];
    saveSocialAccountsSnapshot();
  }
  updateAccountStatusViews();
  if (includeOverview) renderLiveBrowserSessions();
}

async function refreshLiveBrowserSessionsOnly() {
  if (state.liveBrowserSessionsFetch) return state.liveBrowserSessionsFetch;
  const request = api("/api/persona_dashboard/automation/browser_sessions")
    .then((data) => {
      state.socialBrowserSessions = Array.isArray(data?.sessions) ? data.sessions : [];
      renderLiveBrowserSessions();
      return state.socialBrowserSessions;
    })
    .finally(() => {
      if (state.liveBrowserSessionsFetch === request) state.liveBrowserSessionsFetch = null;
    });
  state.liveBrowserSessionsFetch = request;
  return request;
}

async function refreshSocialTaskState(taskId = "") {
  const cleanTaskId = String(taskId || "").trim();
  if (!cleanTaskId) return null;
  const data = await api(`/api/persona_dashboard/automation/tasks/${encodeURIComponent(cleanTaskId)}`)
    .catch(() => null);
  const task = data?.task || null;
  if (!task?.id) return null;
  mergeSocialTaskState(task);
  syncSocialTaskToast(task, { force: true });
  return task;
}

function refreshLiveBrowserSessionsSoon(taskId = "", attempts = 16, delayMs = 500) {
  const token = `${Date.now()}:${Math.random()}`;
  const targetTaskId = String(taskId || "").trim();
  const refreshKey = targetTaskId || "__all__";
  state.liveBrowserRefreshTokens ||= {};
  state.liveBrowserRefreshTokens[refreshKey] = token;
  let observedTarget = Boolean(targetTaskId && (state.socialBrowserSessions || [])
    .some((session) => String(session?.task_id || "") === targetTaskId));
  const isCurrent = () => state.liveBrowserRefreshTokens?.[refreshKey] === token;
  const finish = () => {
    if (isCurrent()) delete state.liveBrowserRefreshTokens[refreshKey];
  };
  const run = async (attempt) => {
    if (!isCurrent()) return;
    await refreshLiveBrowserSessionsOnly().catch(() => {});
    const sessions = Array.isArray(state.socialBrowserSessions) ? state.socialBrowserSessions : [];
    const matched = targetTaskId
      ? sessions.find((session) => String(session.task_id || "") === targetTaskId)
      : sessions[0];
    if (matched) observedTarget = true;
    const found = !targetTaskId || Boolean(matched);
    const takeoverPending = Boolean(matched) && liveBrowserLoginMode(matched) === "switching";
    let targetTask = targetTaskId
      ? (state.socialTasks || []).find((task) => String(task?.id || "") === targetTaskId)
      : null;
    let taskFinished = Boolean(targetTask)
      && !["queued", "running", "need_manual"].includes(String(targetTask?.status || "").trim());
    if (!isCurrent()) return;
    if (targetTaskId && !matched && observedTarget) {
      // The browser registry is removed before the worker's terminal task
      // update reaches this page. Refresh the task itself so account actions
      // cannot remain stuck in the local "执行中" state.
      const refreshedTask = await refreshSocialTaskState(targetTaskId);
      if (!isCurrent()) return;
      if (refreshedTask) {
        targetTask = refreshedTask;
        taskFinished = !["queued", "running", "need_manual"].includes(String(refreshedTask.status || "").trim());
      }
      if (!taskFinished && attempt < attempts) {
        window.setTimeout(() => run(attempt + 1), delayMs);
        return;
      }
      finish();
      if (state.view === "accounts" || state.view === "social") renderSocialAccounts();
      if (isPersonaWorkspaceModule()) renderPersonaDetail();
      return;
    }
    if (targetTaskId && !matched && taskFinished) {
      finish();
      if (state.view === "accounts" || state.view === "social") renderSocialAccounts();
      if (isPersonaWorkspaceModule()) renderPersonaDetail();
      return;
    }
    if (matched && !takeoverPending) {
      if (targetTaskId && !taskFinished && attempt < attempts) {
        window.setTimeout(() => run(attempt + 1), delayMs);
        return;
      }
      finish();
      return;
    }
    if (found && !takeoverPending) {
      finish();
      return;
    }
    if (attempt >= attempts && takeoverPending) {
      if (takeoverPending) {
        matched.login_mode = "takeover_timeout";
        matched.input_allowed = false;
        renderLiveBrowserSessions();
        showMsg("socialMsg", "自动登录未能及时停止，请重试人工接管或停止进程。", false);
      }
      finish();
      return;
    }
    if (attempt >= attempts && !observedTarget) {
      finish();
      return;
    }
    window.setTimeout(() => run(attempt + 1), delayMs);
  };
  window.setTimeout(() => run(1), 250);
}

function captureLiveBrowserReturnTarget() {
  const view = String(state.view || "").trim();
  if (view === "tasks") {
    return {
      view: "tasks",
      taskPanel: state.taskQueuePanel === "regular" ? "regular" : "persona",
      taskQueueRegularPage: Math.max(1, Number(state.taskQueueRegularPage || 1)),
      taskQueuePersonaPage: Math.max(1, Number(state.taskQueuePersonaPage || 1)),
      personaId: String(state.selectedPersonaId || "").trim(),
    };
  }
  if (view === "workspace") {
    return {
      view: "workspace",
      module: String(state.activeModule || "personas").trim() || "personas",
      personaId: String(state.selectedPersonaId || "").trim(),
      personaGroup: String(state.personaGroup || "").trim(),
      personaStep: String(state.personaPanels?.[state.personaGroup] || "").trim(),
    };
  }
  if (view === "accounts") {
    return {
      view: "accounts",
      accountPanel: state.accountBrowserPanel === "proxies" ? "proxies" : "accounts",
    };
  }
  return { view: ["persona_dashboard", "billing", "console_settings"].includes(view) ? view : "accounts" };
}

function liveBrowserReturnLabel(target = state.liveBrowserReturnTarget) {
  if (target?.view === "tasks") return "返回任务";
  if (target?.view === "workspace") return "返回工作台";
  if (target?.view === "persona_dashboard") return "返回人设看板";
  return "返回账号管理";
}

function returnFromLiveBrowserTaskView() {
  const target = state.liveBrowserReturnTarget;
  state.liveBrowserReturnTarget = null;
  if (!target || typeof target !== "object") {
    setAccountBrowserPanel("accounts");
    return;
  }
  const targetView = String(target.view || "accounts").trim();
  const targetPersonaId = String(target.personaId || "").trim();
  if (targetPersonaId && state.personas.some((persona) => String(persona?.id || "") === targetPersonaId)) {
    setSelectedPersonaId(targetPersonaId);
  }
  if (targetView === "tasks") {
    state.taskQueuePanel = target.taskPanel === "regular" ? "regular" : "persona";
    state.taskQueueRegularPage = Math.max(1, Number(target.taskQueueRegularPage || 1));
    state.taskQueuePersonaPage = Math.max(1, Number(target.taskQueuePersonaPage || 1));
    setView("tasks");
    return;
  }
  if (targetView === "workspace") {
    state.activeModule = String(target.module || "personas").trim() || "personas";
    if (target.personaGroup) {
      state.personaGroup = normalizedPersonaGroupKey(target.personaGroup);
      setPersonaGroupStep(state.personaGroup, target.personaStep, selectedPersonaProfile());
    }
    setView("workspace");
    return;
  }
  if (targetView === "accounts") {
    setAccountBrowserPanel(target.accountPanel === "proxies" ? "proxies" : "accounts");
    return;
  }
  setView(["persona_dashboard", "billing", "console_settings"].includes(targetView) ? targetView : "accounts");
}

function openLiveBrowserTaskView(taskId = "") {
  const cleanTaskId = String(taskId || "").trim();
  if (!(state.view === "accounts" && state.accountBrowserPanel === "browsers")) {
    state.liveBrowserReturnTarget = captureLiveBrowserReturnTarget();
  }
  state.accountBrowserPanel = "browsers";
  setView("accounts");
  setAccountBrowserPanel("browsers");
  refreshLiveBrowserSessionsSoon(cleanTaskId);
}

function loginAssistanceTaskStatus(task = {}) {
  return String(task?.status || "queued").trim().toLowerCase() || "queued";
}

function taskAssistancePayload(task = {}) {
  let payload = task?.payload || task?.payload_json || {};
  if (typeof payload === "string") {
    try { payload = JSON.parse(payload || "{}"); } catch (_) { payload = {}; }
  }
  return payload && typeof payload === "object" ? payload : {};
}

function taskAssistanceViewModel(task = {}, session = null) {
  const taskType = String(task?.task_type || session?.task_type || "").trim();
  if (taskType === "publish_post") return publishAssistanceViewModel(task, session);
  return loginAssistanceViewModel(task, session);
}

function publishAssistanceViewModel(task = {}, session = null) {
  const taskStatus = loginAssistanceTaskStatus(task);
  const assistance = session?.login_assistance && typeof session.login_assistance === "object"
    ? session.login_assistance
    : {};
  const result = task?.result && typeof task.result === "object" ? task.result : {};
  const permalink = String(
    assistance.permalink || result.published_url || result.publishedUrl || result.url || result.post_url || result.permalink || "",
  ).trim();
  const screenshotUrl = String(assistance.screenshot_url || "").trim()
    || latestSocialTaskScreenshot(task, [])
    || "";
  const expiresAt = Number(assistance.expires_at || 0);
  const remainingSeconds = expiresAt > 0
    ? Math.max(0, Math.ceil(expiresAt - (Date.now() / 1000)))
    : 0;
  const loginLike = loginAssistanceViewModel(task, session);
  if (["verification_code", "credentials", "choice", "browser_interaction"].includes(String(assistance.kind || ""))) {
    return { ...loginLike, permalink, screenshotUrl };
  }
  if (taskStatus === "success" || assistance.phase === "success") {
    return {
      phase: "success",
      kind: "success",
      title: "发布成功",
      message: permalink ? "帖子已发布，可查看截图和链接。" : "发布已完成。",
      permalink,
      screenshotUrl,
    };
  }
  if (["failed", "cancelled"].includes(taskStatus) || assistance.phase === "error") {
    return {
      phase: "error",
      kind: "error",
      title: String(assistance.title || (taskStatus === "cancelled" ? "发布已停止" : "发布未完成")),
      message: String(assistance.message || task?.error || "本次发布没有完成，请稍后重试。"),
    };
  }
  if (taskStatus === "need_manual" || assistance.kind === "takeover") {
    return {
      phase: "attention",
      kind: "takeover",
      title: String(assistance.title || "需要人工接管"),
      message: String(assistance.message || "自动发布遇到需要人工处理的步骤，接受后将打开实时浏览器。"),
      submitLabel: String(assistance.submit_label || "接受并接管"),
      remainingSeconds,
    };
  }
  const bootstrapStarting = String(assistance.title || "") === "正在启动发布"
    && String(assistance.kind || "progress") === "progress";
  return {
    phase: "running",
    kind: "progress",
    title: String(assistance.title || (session?.browser_ready || !bootstrapStarting ? "正在发布" : "正在启动发布")),
    message: String(assistance.message || (session ? "正在同步发布进度，无需打开浏览器。" : "正在连接指纹浏览器，请稍候。")),
    remainingSeconds,
  };
}

function loginAssistanceViewModel(task = {}, session = null) {
  const taskStatus = loginAssistanceTaskStatus(task);
  let assistance = session?.login_assistance && typeof session.login_assistance === "object"
    ? session.login_assistance
    : {};
  const expiresAt = Number(assistance.expires_at || 0);
  const remainingSeconds = expiresAt > 0
    ? Math.max(0, Math.ceil(expiresAt - (Date.now() / 1000)))
    : 0;
  if (taskStatus === "success" || assistance.phase === "success") {
    return {
      phase: "success",
      kind: "success",
      title: "登录成功",
      message: "账号登录状态已确认，可以开始使用。",
    };
  }
  if (["failed", "cancelled"].includes(taskStatus) || assistance.phase === "error") {
    return {
      phase: "error",
      kind: "error",
      title: String(assistance.title || (taskStatus === "cancelled" || assistance.kind === "cancelled" ? "登录已停止" : "登录未完成")),
      message: String(assistance.message || task?.error || "本次登录任务没有完成，请稍后重试。"),
    };
  }
  const bootstrapStarting = String(assistance.title || "") === "正在启动登录"
    && String(assistance.kind || "progress") === "progress";
  if (bootstrapStarting && session?.browser_ready) {
    assistance = {
      ...assistance,
      title: "正在执行登录",
      message: "指纹浏览器已打开，正在检查页面并同步登录状态。",
    };
  }
  const actions = Array.isArray(assistance.actions)
    ? assistance.actions
      .map((item) => ({
        kind: String(item?.kind || "choice"),
        label: String(item?.label || "").trim(),
        title: String(item?.title || item?.label || "").trim(),
      }))
      .filter((item) => item.label)
    : [];
  return {
    phase: String(assistance.phase || "running"),
    kind: String(assistance.kind || "progress"),
    title: String(assistance.title || (session ? "正在执行登录" : "正在启动浏览器")),
    message: String(assistance.message || (session ? "正在同步浏览器登录状态。" : "正在连接指纹浏览器，请稍候。")),
    fieldLabel: String(assistance.field_label || "验证码"),
    inputMode: String(assistance.input_mode || "text"),
    submitLabel: String(assistance.submit_label || "提交并继续"),
    actions,
    remainingSeconds,
  };
}

function loginAssistanceTimeLimitLabel(remainingSeconds = 0) {
  const totalSeconds = Math.max(0, Number(remainingSeconds || 0));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = Math.floor(totalSeconds % 60);
  return `剩余 ${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}，超时后本次登录将自动取消。`;
}

function updateLoginAssistanceDeadline(modal, remainingSeconds = 0, phase = "") {
  const copy = modal?.querySelector(".login-assistance-copy");
  if (!copy) return;
  let deadline = copy.querySelector(".login-assistance-deadline");
  const show = Number(remainingSeconds || 0) > 0 && !["success", "error"].includes(String(phase || ""));
  if (!show) {
    deadline?.remove();
    return;
  }
  const label = loginAssistanceTimeLimitLabel(remainingSeconds);
  if (!deadline) {
    deadline = document.createElement("small");
    deadline.className = "login-assistance-deadline";
    copy.append(deadline);
  }
  if (deadline.textContent !== label) deadline.textContent = label;
}

function renderLoginAssistanceVisual(model = {}) {
  if (model.phase === "success") {
    return `<span class="login-assistance-success" aria-hidden="true">
      <svg viewBox="0 0 64 64"><circle cx="32" cy="32" r="27"></circle><path d="m19 33 9 9 18-20"></path></svg>
    </span>`;
  }
  if (model.phase === "error") {
    if (String(model.title || "").trim() === "账号封控") {
      return `<span class="login-assistance-error-icon" aria-hidden="true">${renderPersonaAccountHealthIcon({ tone: "danger" })}</span>`;
    }
    return `<span class="login-assistance-error-icon" aria-hidden="true">
      <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"></circle><path d="M12 7v6"></path><path d="M12 17h.01"></path></svg>
    </span>`;
  }
  if (model.phase === "attention") {
    return `<span class="login-assistance-attention" aria-hidden="true">
      <svg viewBox="0 0 24 24"><path d="M12 3 2.8 20h18.4L12 3Z"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg>
    </span>`;
  }
  return `<span class="login-assistance-spinner" aria-hidden="true"></span>`;
}

function loginAssistanceMappedInputAllowed(session = null) {
  return Boolean(liveBrowserSessionId(session));
}

function renderLoginAssistanceChoices(model = {}, session = null) {
  const inputAllowed = loginAssistanceMappedInputAllowed(session);
  const actions = Array.isArray(model.actions) ? model.actions : [];
  if (!actions.length) return "";
  return `<div class="login-assistance-choices" role="group" aria-label="页面可用操作">
    ${actions.map((item) => `<button type="button" class="login-assistance-choice" data-login-assistance-choice="${esc(item.label)}" ${inputAllowed ? "" : "disabled"}>${esc(item.title || item.label)}</button>`).join("")}
  </div>`;
}

function renderLoginAssistanceAction(model = {}, session = null, options = {}) {
  const inputAllowed = loginAssistanceMappedInputAllowed(session);
  const choices = renderLoginAssistanceChoices(model, session);
  if (model.kind === "verification_code") {
    return `<form class="login-assistance-form" data-login-assistance-form data-login-assistance-kind="verification_code">
      <label>${esc(model.fieldLabel)}
        <input name="verification_code" type="text" inputmode="${model.inputMode === "numeric" ? "numeric" : "text"}" autocomplete="one-time-code" maxlength="64" placeholder="请输入${esc(model.fieldLabel)}" required />
      </label>
      <button type="submit" class="primary" ${inputAllowed ? "" : "disabled"}>${esc(inputAllowed ? model.submitLabel : "正在连接浏览器")}</button>
    </form>${choices}`;
  }
  if (model.kind === "credentials") {
    return `<form class="login-assistance-form" data-login-assistance-form data-login-assistance-kind="credentials">
      <label>账号、邮箱或手机号
        <input name="login_username" type="text" autocomplete="username" maxlength="320" placeholder="请输入登录账号" required />
      </label>
      <label>登录密码
        <input name="login_password" type="password" autocomplete="current-password" maxlength="512" placeholder="请输入登录密码" required />
      </label>
      <button type="submit" class="primary" ${inputAllowed ? "" : "disabled"}>${esc(inputAllowed ? model.submitLabel : "正在连接浏览器")}</button>
    </form>${choices}`;
  }
  if (model.kind === "choice") {
    return `${choices || `<button type="button" class="primary login-assistance-wide-action" data-login-assistance-accept>${esc(model.submitLabel || "接受并接管")}</button>`}`;
  }
  if (model.kind === "browser_interaction") {
    return `${choices}<button type="button" class="primary login-assistance-wide-action" data-login-assistance-accept>${esc(model.submitLabel || "接受并接管")}</button>`;
  }
  if (model.kind === "takeover") {
    return `<button type="button" class="primary login-assistance-wide-action" data-login-assistance-accept>${esc(model.submitLabel || "接受并接管")}</button>`;
  }
  if (model.phase === "success") {
    return `<button type="button" class="primary login-assistance-wide-action" data-login-assistance-close>完成</button>`;
  }
  if (model.phase === "error") {
    return `<button type="button" class="primary login-assistance-wide-action" ${options.stopTaskOnClose ? "data-login-assistance-stop data-login-assistance-close-after-stop" : "data-login-assistance-close"}>${options.stopTaskOnClose ? "关闭并停止任务" : "关闭"}</button>`;
  }
  return `<div class="login-assistance-progress-note"><span></span>页面状态会自动更新，无需刷新</div>`;
}

function renderTaskAssistanceDetails(model = {}) {
  if (String(model.phase || model.kind || "") !== "success") return "";
  const permalink = String(model.permalink || "").trim();
  const screenshotUrl = String(model.screenshotUrl || "").trim();
  if (!permalink && !screenshotUrl) return "";
  const shotHref = screenshotUrl.startsWith("http") || screenshotUrl.startsWith("/")
    ? adminWorkspaceUrl(screenshotUrl)
    : screenshotUrl;
  const linkHref = permalink ? adminWorkspacePageUrl(permalink) : "";
  const shotGroupId = screenshotUrl
    ? registerMediaPreviewGroup([{
      previewUrl: shotHref,
      originalUrl: shotHref,
      type: "image",
      label: "任务截图",
    }])
    : "";
  return `<div class="login-assistance-details">
    ${screenshotUrl ? `<button type="button" class="login-assistance-shot-button" data-media-preview-group="${esc(shotGroupId)}" data-media-preview-index="0" data-media-preview-type="image" data-media-preview-label="任务截图" title="查看截图" aria-label="查看截图">
      <img class="login-assistance-shot" src="${esc(shotHref)}" alt="任务截图" />
    </button>` : ""}
    ${linkHref ? `<a class="login-assistance-permalink" href="${esc(linkHref)}" target="_blank" rel="noopener">查看发布链接</a>` : ""}
  </div>`;
}

function updateLoginAssistanceModal(modal, task = {}, session = null) {
  if (!modal?.isConnected) return;
  const model = taskAssistanceViewModel(task, session);
  const taskStatus = loginAssistanceTaskStatus(task);
  const taskCanStop = !["success", "failed", "cancelled"].includes(taskStatus);
  const showFooterStop = taskCanStop && !["success", "error"].includes(String(model.phase || ""));
  const renderKey = JSON.stringify([
    model.phase,
    model.kind,
    model.title,
    model.message,
    model.fieldLabel,
    model.inputMode,
    model.submitLabel,
    JSON.stringify(model.actions || []),
    model.permalink || "",
    model.screenshotUrl || "",
    taskStatus,
    Boolean(session?.input_allowed),
    Boolean(loginAssistanceMappedInputAllowed(session)),
  ]);
  if (modal.dataset.loginAssistanceRenderKey === renderKey) {
    updateLoginAssistanceDeadline(modal, model.remainingSeconds, model.phase);
    return;
  }
  modal.dataset.loginAssistanceRenderKey = renderKey;
  const body = modal.querySelector("[data-login-assistance-body]");
  if (!body) return;
  body.className = `login-assistance-body is-${esc(model.phase)}`;
  body.innerHTML = `
    <div class="login-assistance-visual">${renderLoginAssistanceVisual(model)}</div>
    <div class="login-assistance-copy">
      <strong>${esc(model.title)}</strong>
      <p>${esc(model.message)}</p>
      ${model.remainingSeconds > 0 && !["success", "error"].includes(model.phase)
        ? `<small class="login-assistance-deadline">${esc(loginAssistanceTimeLimitLabel(model.remainingSeconds))}</small>`
        : ""}
    </div>
    ${renderTaskAssistanceDetails(model)}
    <div class="login-assistance-action">${renderLoginAssistanceAction(model, session, {
      stopTaskOnClose: modal.classList.contains("is-publish-assistance") && taskCanStop,
    })}</div>
    ${session && model.kind !== "browser_interaction" && model.phase !== "success"
      ? `<button type="button" class="login-assistance-live-link" data-login-assistance-live>查看实时画面</button>`
      : ""}
  `;
  const footer = modal.querySelector("[data-login-assistance-footer]");
  const footerStopButton = footer?.querySelector("[data-login-assistance-stop]");
  if (footer) footer.hidden = !showFooterStop;
  if (footerStopButton && !footerStopButton.dataset.stopPending) {
    footerStopButton.disabled = !showFooterStop;
  }
  translateConsoleLanguage(body, currentLanguage());
}

function clearLoginAssistancePendingSubmission(modal) {
  if (!modal?.dataset) return;
  delete modal.dataset.loginAssistancePendingKind;
  delete modal.dataset.loginAssistancePendingUpdatedAt;
}

function loginAssistancePollShouldPreserveSubmission(modal, task = {}, session = null) {
  const pendingKind = String(modal?.dataset?.loginAssistancePendingKind || "").trim();
  if (!pendingKind) return false;
  if (["success", "failed", "cancelled"].includes(loginAssistanceTaskStatus(task))) {
    clearLoginAssistancePendingSubmission(modal);
    return false;
  }
  const assistance = session?.login_assistance && typeof session.login_assistance === "object"
    ? session.login_assistance
    : null;
  if (!assistance) return true;
  const pendingUpdatedAt = Number(modal.dataset.loginAssistancePendingUpdatedAt || 0);
  const nextKind = String(assistance.kind || "").trim();
  const nextUpdatedAt = Number(assistance.updated_at || 0);
  if (nextKind === pendingKind && nextUpdatedAt <= pendingUpdatedAt) return true;
  clearLoginAssistancePendingSubmission(modal);
  return false;
}

async function submitLoginAssistance(modal, session, payload = {}) {
  const sessionId = liveBrowserSessionId(session);
  if (!sessionId) return;
  const previousAssistance = session?.login_assistance && typeof session.login_assistance === "object"
    ? session.login_assistance
    : {};
  modal.dataset.loginAssistancePendingKind = String(payload.kind || "").trim();
  modal.dataset.loginAssistancePendingUpdatedAt = String(Number(previousAssistance.updated_at || 0));
  const submitButton = modal.querySelector("[data-login-assistance-form] button[type='submit']");
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.textContent = "提交中...";
  }
  try {
    await api(`/api/persona_dashboard/automation/browser_sessions/${encodeURIComponent(sessionId)}/login_assistance`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    modal.dataset.loginAssistanceRenderKey = "";
    updateLoginAssistanceModal(modal, { status: "running" }, {
      ...session,
      login_assistance: {
        phase: "running",
        kind: "progress",
        title: "正在验证",
        message: "内容已同步到指纹浏览器，正在等待平台反馈。",
      },
    });
  } catch (error) {
    clearLoginAssistancePendingSubmission(modal);
    showToast(error?.detail || error?.message || "登录信息提交失败", false);
    modal.dataset.loginAssistanceRenderKey = "";
  }
}

function openPublishAssistanceView(taskId = "", options) {
  options = options || {};
  return openTaskAssistanceView(taskId, { ...options, mode: "publish" });
}

function openLoginAssistanceView(taskId = "", accountId = "") {
  return openTaskAssistanceView(taskId, { accountId });
}

function openTaskAssistanceView(taskId = "", options) {
  options = options || {};
  const cleanTaskId = String(taskId || "").trim();
  if (!cleanTaskId) return;
  const accountId = String(options.accountId || "").trim();
  const mode = String(options.mode || "login").trim() || "login";
  const existing = document.getElementById("loginAssistanceModal");
  if (existing) closeConsoleModal(null, existing);
  if (mode === "publish") hidePublishAssistanceRestore();
  const account = selectedSocialAccount(accountId)
    || (state.socialAccounts || []).find((item) => String(item?.id || "") === String(accountId || ""))
    || {};
  const modal = document.createElement("div");
  modal.id = "loginAssistanceModal";
  modal.className = `console-modal login-assistance-modal${mode === "publish" ? " is-publish-assistance" : ""}`;
  modal.dataset.modalKey = mode === "publish" ? "publish-assistance" : "login-assistance";
  modal.innerHTML = `
    <div class="console-modal-backdrop"></div>
    <section class="console-modal-dialog login-assistance-dialog" role="dialog" aria-modal="true" aria-labelledby="loginAssistanceTitle">
      <div class="console-modal-head login-assistance-head">
        <div>
          <strong id="loginAssistanceTitle">${mode === "publish" ? "发布助手" : "登录助手"}</strong>
          <span>${esc(platformLabel(account?.platform || ""))} · ${esc(account?.username || account?.login_username || "当前账号")}</span>
        </div>
        ${renderModalCloseButton("data-login-assistance-close")}
      </div>
      <div class="login-assistance-body is-running" data-login-assistance-body></div>
      <div class="login-assistance-footer" data-login-assistance-footer>
        <button type="button" class="danger" data-login-assistance-stop>停止任务</button>
      </div>
    </section>
  `;
  document.body.appendChild(modal);
  markConsoleDynamicUi(modal);
  translateConsoleLanguage(modal, currentLanguage());
  let currentSession = null;
  let stopped = false;
  let timer = 0;
  const poll = async () => {
    if (stopped || !modal.isConnected) return;
    const [task] = await Promise.all([
      refreshSocialTaskState(cleanTaskId),
      refreshLiveBrowserSessionsOnly().catch(() => []),
    ]);
    currentSession = (state.socialBrowserSessions || []).find((item) => String(item?.task_id || "") === cleanTaskId)
      || (accountId
        ? (state.socialBrowserSessions || []).find((item) => String(item?.account_id || "") === String(accountId || ""))
        : null)
      || null;
    const currentTask = task || (state.socialTasks || []).find((item) => String(item?.id || "") === cleanTaskId) || { id: cleanTaskId, status: "queued" };
    const taskStatus = loginAssistanceTaskStatus(currentTask);
    const assistancePhase = String(currentSession?.login_assistance?.phase || "").trim().toLowerCase();
    const statusAccountId = accountId || String(currentTask?.account_id || "").trim();
    if (statusAccountId && (["failed", "cancelled"].includes(taskStatus) || assistancePhase === "error")) {
      const accountSyncKey = `${taskStatus}:${assistancePhase}:${String(currentSession?.login_assistance?.updated_at || "")}`;
      if (modal.dataset.publishAssistanceAccountSyncKey !== accountSyncKey) {
        modal.dataset.publishAssistanceAccountSyncKey = accountSyncKey;
        await refreshSocialAccountsOnly({ force: true }).catch(() => {});
      }
    }
    if (!loginAssistancePollShouldPreserveSubmission(modal, currentTask, currentSession)) {
      updateLoginAssistanceModal(modal, currentTask, currentSession);
    }
    if (publishAssistanceLooksSettled(currentTask, currentSession)) {
      refreshPublishingDockAfterAssistanceSettle(cleanTaskId);
    }
    if (!stopped && modal.isConnected && !["success", "failed", "cancelled"].includes(taskStatus)) {
      timer = window.setTimeout(poll, 1000);
    }
  };
  modal.__cleanup = () => {
    stopped = true;
    if (timer) window.clearTimeout(timer);
    if (mode !== "publish") return;
    if (modal.dataset.publishAssistanceStopped === "true") {
      hidePublishAssistanceRestore();
      return;
    }
    window.setTimeout(() => {
      if (document.getElementById("loginAssistanceModal")) return;
      const currentTask = (state.socialTasks || []).find((item) => String(item?.id || "") === cleanTaskId)
        || mobilePublishingTask();
      const status = loginAssistanceTaskStatus(currentTask || { id: cleanTaskId, status: "queued" });
      if (!["preparing", "queued", "running", "need_manual"].includes(status)) return;
      state.publishAssistanceDismissed = true;
      syncPublishAssistanceRestore();
    }, 0);
  };
  modal.addEventListener("click", async (event) => {
    const previewButton = event.target.closest("[data-media-preview-group]");
    if (previewButton) {
      event.preventDefault();
      openPersonaMediaLightbox(
        previewButton.dataset.mediaPreviewGroup || "",
        Number(previewButton.dataset.mediaPreviewIndex || 0),
      );
      return;
    }
    const stopButton = event.target.closest("[data-login-assistance-stop]");
    if (stopButton) {
      const closeAfterStop = stopButton.hasAttribute("data-login-assistance-close-after-stop");
      stopButton.disabled = true;
      stopButton.dataset.stopPending = "true";
      stopButton.textContent = "正在停止…";
      if (closeAfterStop) {
        modal.dataset.publishAssistanceStopped = "true";
        closeConsoleModal(null, modal);
      }
      try {
        const result = await cancelSocialAutomationTask(cleanTaskId, "socialMsg");
        const cancelledTask = result?.task
          || (state.socialTasks || []).find((item) => String(item?.id || "") === cleanTaskId)
          || { id: cleanTaskId, status: "cancelled" };
        if (modal.isConnected) {
          modal.dataset.loginAssistanceRenderKey = "";
          updateLoginAssistanceModal(modal, { ...cancelledTask, status: "cancelled" }, currentSession);
        }
      } catch (error) {
        if (modal.isConnected) {
          delete stopButton.dataset.stopPending;
          stopButton.disabled = false;
          stopButton.textContent = closeAfterStop ? "关闭并停止任务" : "停止任务";
        } else if (closeAfterStop) {
          state.publishAssistanceDismissed = true;
          syncPublishAssistanceRestore();
        }
        showToast(error?.detail || error?.message || "停止登录任务失败", false);
      }
      return;
    }
    if (event.target.closest("[data-login-assistance-close]")) {
      closeConsoleModal(null, modal);
      return;
    }
    if (event.target.closest("[data-login-assistance-live]")) {
      closeConsoleModal(null, modal);
      openLiveBrowserTaskView(cleanTaskId);
      return;
    }
    if (event.target.closest("[data-login-assistance-accept]")) {
      const acceptButton = event.target.closest("[data-login-assistance-accept]");
      acceptButton.disabled = true;
      acceptButton.textContent = "正在打开浏览器…";
      const sessionId = liveBrowserSessionId(currentSession);
      Promise.resolve(sessionId ? setLiveBrowserMode(sessionId, "manual") : null)
        .catch((error) => showToast(error?.detail || error?.message || "切换人工接管失败", false))
        .finally(() => {
          closeConsoleModal(null, modal);
          openLiveBrowserTaskView(cleanTaskId);
        });
      return;
    }
    const choice = event.target.closest("[data-login-assistance-choice]");
    if (choice && currentSession) {
      void submitLoginAssistance(modal, currentSession, {
        kind: "choice",
        action_label: String(choice.dataset.loginAssistanceChoice || ""),
      });
    }
  });
  modal.addEventListener("submit", (event) => {
    const form = event.target.closest("[data-login-assistance-form]");
    if (!form || !currentSession) return;
    event.preventDefault();
    const values = new FormData(form);
    const kind = String(form.dataset.loginAssistanceKind || "");
    const payload = { kind };
    if (kind === "verification_code") payload.verification_code = String(values.get("verification_code") || "").trim();
    if (kind === "credentials") {
      payload.login_username = String(values.get("login_username") || "").trim();
      payload.login_password = String(values.get("login_password") || "");
    }
    void submitLoginAssistance(modal, currentSession, payload);
  });
  updateLoginAssistanceModal(modal, { id: cleanTaskId, status: "queued" }, null);
  void poll();
}

function openVideoWorkspace(moduleId = "") {
  const nextModule = VIDEO_WORKSPACE_MODULES.some((item) => item.id === moduleId)
    ? moduleId
    : VIDEO_WORKSPACE_MODULES[0].id;
  state.activeVideoModule = nextModule;
  state.videoWorkspaceMenuOpen = true;
  if (state.view === "video_workspace") {
    syncVideoWorkspaceRoute();
    syncVideoModuleMenuState();
    window.VideoWorkbench?.selectModule?.(nextModule);
    return;
  }
  setView("video_workspace");
}

window.VectoConsoleNavigation = {
  ...(window.VectoConsoleNavigation || {}),
  openLiveBrowserTaskView,
  openVideoWorkspace,
};

function renderAccountOpenLoginButtonContent(activeLoginTask = null) {
  if (activeLoginTask?.id) {
    return renderBusyButtonContent(
      "执行中",
      true,
      activeLoginTask.started_at || activeLoginTask.created_at || activeLoginTask.updated_at
    );
  }
  return `${renderBrowserLaunchIcon()}<span>打开登录</span>`;
}

function updateAccountOpenLoginButton(button, accountId = "") {
  if (!button) return;
  const activeLoginTask = activeOpenLoginTaskForAccount(accountId);
  button.innerHTML = renderAccountOpenLoginButtonContent(activeLoginTask);
  if (activeLoginTask?.id) {
    button.dataset.openLoginTaskId = String(activeLoginTask.id);
    button.setAttribute("aria-busy", "true");
    return;
  }
  delete button.dataset.openLoginTaskId;
  button.removeAttribute("aria-busy");
}

function updateAccountLoginResumeButton(button, accountId = "") {
  if (!button) return;
  const activeLoginTask = activeOpenLoginTaskForAccount(accountId);
  const activePublishTask = activeLoginTask?.id ? null : activePublishTaskForAccount(accountId);
  const canResume = Boolean(activeLoginTask?.id) || Boolean(activePublishTask?.id);
  button.hidden = !canResume;
  button.innerHTML = `${renderBrowserLaunchIcon()}<span>${activePublishTask?.id ? "发布助手" : "继续登录"}</span>`;
  button.dataset.accountTaskAssistance = String(accountId || "");
  button.setAttribute("aria-label", activePublishTask?.id ? "打开发布助手" : "继续登录");
  button.setAttribute("title", activePublishTask?.id ? "打开发布助手" : "继续登录");
  if (canResume && activeLoginTask?.id) {
    button.dataset.openLoginTaskId = String(activeLoginTask.id);
    delete button.dataset.openPublishTaskId;
    return;
  }
  if (canResume && activePublishTask?.id) {
    button.dataset.openPublishTaskId = String(activePublishTask.id);
    delete button.dataset.openLoginTaskId;
    return;
  }
  delete button.dataset.openLoginTaskId;
  delete button.dataset.openPublishTaskId;
}

function openAccountTaskAssistance(button) {
  if (!button) return false;
  const accountId = String(button.dataset.accountTaskAssistance || "").trim();
  const publishTaskId = String(button.dataset.openPublishTaskId || "").trim();
  const loginTaskId = String(button.dataset.openLoginTaskId || "").trim();
  const taskId = publishTaskId || loginTaskId;
  if (!taskId) return false;
  if (publishTaskId) {
    const task = (state.socialTasks || []).find((item) => String(item?.id || "").trim() === publishTaskId);
    deferMobilePublishingBrowserView(
      publishTaskId,
      task?.started_at || task?.created_at || task?.updated_at || 0,
    );
    bindPublishAssistanceContext({ accountId, personaId: task?.persona_id || "" });
    openPublishAssistanceView(taskId, { accountId });
    return true;
  }
  openLoginAssistanceView(taskId, accountId);
  return true;
}

function updateAccountStatusViews() {
  const accountById = new Map((state.socialAccounts || []).map((account) => [String(account.id || ""), account]));
  document.querySelectorAll("[data-account-status-for]").forEach((node) => {
    const account = accountById.get(String(node.dataset.accountStatusFor || ""));
    const status = accountDisplayedStatus(account);
    node.className = node.classList.contains("status")
      ? `status ${accountStatusClassNames(status)}`
      : `task-status-text is-${statusTone(status)} account-status-chip`;
    node.innerHTML = renderAccountStatusContent(account);
    node.title = accountStatusTitle(account);
  });
  ["simpleAccount", "socialAccount", "personaAutoAccount", "personaPublishAccountSelect"].forEach((id) => {
    const select = $(id);
    if (!select) return;
    Array.from(select.options || []).forEach((option) => {
      const account = accountById.get(String(option.value || ""));
      if (account) option.textContent = accountDisplayName(account);
    });
  });
  document.querySelectorAll("[data-account-proxy-for]").forEach((node) => {
    const account = accountById.get(String(node.dataset.accountProxyFor || ""));
    if (account) node.textContent = accountResidentialProxyLabel(account);
  });
  document.querySelectorAll("[data-account-proxy-picker]").forEach((button) => {
    const account = accountById.get(String(button.dataset.accountProxyPicker || ""));
    const label = button.querySelector("[data-account-proxy-label]");
    if (account && label) label.textContent = String(account.proxy_id || "").trim() ? "切换代理" : "选择代理";
  });
  document.querySelectorAll("[data-social-open-login], [data-persona-account-open-login]").forEach((button) => {
    const accountId = String(button.dataset.socialOpenLogin || button.dataset.personaAccountOpenLogin || "");
    if (button.matches("[data-account-login-resume]")) updateAccountLoginResumeButton(button, accountId);
    else updateAccountOpenLoginButton(button, accountId);
  });
}

