function bindAccountPoolPlatformSwipe(host) {
  const options = arguments[1] && typeof arguments[1] === "object" ? arguments[1] : {};
  const swipeSurface = host?.querySelector(".account-pool-body");
  const accountPanel = host?.querySelector(".account-pool-account-panel");
  const resolvedSwipeSurface = options.swipeSurface || swipeSurface;
  const resolvedAccountPanel = options.accountPanel || accountPanel;
  const platformEntries = Array.isArray(options.platformEntries) ? options.platformEntries : accountPoolPlatforms;
  const currentPlatform = typeof options.currentPlatform === "function"
    ? options.currentPlatform
    : normalizeAccountPoolPlatform;
  const createMotion = typeof options.createMotion === "function"
    ? options.createMotion
    : createAccountPoolPlatformMotion;
  const settleMotion = typeof options.settleMotion === "function"
    ? options.settleMotion
    : settleAccountPoolPlatformMotion;
  const transitionIsActive = typeof options.transitionIsActive === "function"
    ? options.transitionIsActive
    : () => Boolean(accountPoolPlatformTransitionPromise);
  const setTransition = typeof options.setTransition === "function"
    ? options.setTransition
    : (transition) => {
      accountPoolPlatformTransitionPromise = transition;
      void transition.finally(() => {
        if (accountPoolPlatformTransitionPromise === transition) accountPoolPlatformTransitionPromise = null;
      });
    };
  const suppressClickUntil = typeof options.suppressClickUntil === "function"
    ? options.suppressClickUntil
    : (value) => {
      if (value !== undefined) accountPoolPlatformSwipeSuppressClickUntil = value;
      return accountPoolPlatformSwipeSuppressClickUntil;
    };
  if (!resolvedSwipeSurface || !resolvedAccountPanel) return;
  let gesture = null;
  const moveWindowGesture = (event) => moveGesture(event);
  const finishWindowGesture = (event) => finishGesture(event, false);
  const cancelWindowGesture = (event) => finishGesture(event, true);
  const removeWindowGestureListeners = () => {
    window.removeEventListener("pointermove", moveWindowGesture, true);
    window.removeEventListener("pointerup", finishWindowGesture, true);
    window.removeEventListener("pointercancel", cancelWindowGesture, true);
  };
  const abandonGesture = () => {
    removeWindowGestureListeners();
    gesture = null;
  };
  resolvedSwipeSurface.addEventListener("click", (event) => {
    if (Date.now() >= suppressClickUntil()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  }, true);
  resolvedSwipeSurface.addEventListener("pointerdown", (event) => {
    if (event.pointerType !== "touch" || event.isPrimary === false) return;
    if (transitionIsActive()) return;
    gesture = {
      pointerId: event.pointerId,
      x: Number(event.clientX || 0),
      y: Number(event.clientY || 0),
      lastAt: Number(event.timeStamp || performance.now()),
      lastX: Number(event.clientX || 0),
      velocityX: 0,
      motion: null,
      locked: false,
      deltaX: 0,
    };
    window.addEventListener("pointermove", moveWindowGesture, { capture: true, passive: false });
    window.addEventListener("pointerup", finishWindowGesture, true);
    window.addEventListener("pointercancel", cancelWindowGesture, true);
  });

  function moveGesture(event) {
    if (!gesture || event.pointerId !== gesture.pointerId) return;
    const deltaX = Number(event.clientX || 0) - gesture.x;
    const deltaY = Number(event.clientY || 0) - gesture.y;
    if (!gesture.locked) {
      if (Math.max(Math.abs(deltaX), Math.abs(deltaY)) < 7) return;
      if (Math.abs(deltaY) >= Math.abs(deltaX)) {
        abandonGesture();
        return;
      }
      const currentIndex = platformEntries.findIndex(([value]) => value === currentPlatform());
      const direction = deltaX < 0 ? 1 : -1;
      const nextIndex = currentIndex + direction;
      if (nextIndex < 0 || nextIndex >= platformEntries.length) {
        abandonGesture();
        return;
      }
      gesture.motion = createMotion(platformEntries[nextIndex][0], direction);
      if (!gesture.motion) {
        abandonGesture();
        return;
      }
      gesture.locked = true;
    }
    if (gesture.motion.discarded) {
      abandonGesture();
      return;
    }
    event.preventDefault();
    gesture.deltaX = gesture.motion.apply(deltaX);
    const now = Number(event.timeStamp || performance.now());
    const elapsed = Math.max(1, now - gesture.lastAt);
    gesture.velocityX = (Number(event.clientX || 0) - gesture.lastX) / elapsed;
    gesture.lastAt = now;
    gesture.lastX = Number(event.clientX || 0);
  }

  const finishGesture = (event, cancelled = false) => {
    if (!gesture || event.pointerId !== gesture.pointerId) return;
    const currentGesture = gesture;
    gesture = null;
    removeWindowGestureListeners();
    if (!currentGesture.motion) return;
    const distanceThreshold = Math.min(72, currentGesture.motion.width * 0.18);
    const commit = !cancelled && (
      Math.abs(currentGesture.deltaX) >= distanceThreshold
      || (Math.abs(currentGesture.deltaX) >= 24 && Math.abs(currentGesture.velocityX) >= 0.45)
    );
    if (Math.abs(currentGesture.deltaX) >= 7) {
      suppressClickUntil(Date.now() + 350);
    }
    const transition = settleMotion(currentGesture.motion, commit);
    setTransition(transition);
  };
}

function bindPersonaAccountPlatformSwipe(host) {
  const accountPanel = host?.querySelector(".persona-account-pool-panel");
  const persona = selectedPersona();
  const platforms = persona ? personaAutomationPlatformOptions(persona) : [];
  if (!accountPanel || platforms.length < 2) return;
  bindAccountPoolPlatformSwipe(host, {
    swipeSurface: accountPanel,
    accountPanel,
    platformEntries: platforms.map((value) => [value, platformLabel(value)]),
    currentPlatform: () => personaContentPlatform(persona),
    createMotion: (next, direction) => createPersonaAccountPlatformMotion(persona, next, direction),
    settleMotion: settleAccountPoolPlatformMotion,
    transitionIsActive: () => Boolean(personaAccountPlatformTransitionPromise),
    setTransition: (transition) => {
      personaAccountPlatformTransitionPromise = transition;
      void transition.finally(() => {
        if (personaAccountPlatformTransitionPromise === transition) personaAccountPlatformTransitionPromise = null;
      });
    },
  });
}

async function bindAccountPoolAccountToPersona(personaId = "") {
  if (state.accountPoolBinding) return;
  const cleanPersonaId = String(personaId || "").trim();
  if (!cleanPersonaId) return;
  const accounts = selectedAccountPoolAccounts();
  if (!accounts.length) {
    showMsg("socialMsg", "请先选择要绑定的账号。", false);
    return;
  }
  if (accounts.length !== 1) {
    showMsg("socialMsg", "同一人设在同一平台只能绑定一个账号，请只勾选一个账号。", false);
    return;
  }
  const account = accounts[0];
  const replacedAccount = (state.socialAccounts || []).find((item) => (
    String(item.id || "") !== String(account.id || "")
    && String(item.persona_id || "").trim() === cleanPersonaId
    && String(item.platform || "").trim().toLowerCase() === String(account.platform || "").trim().toLowerCase()
  ));
  state.accountPoolBinding = true;
  renderSocialAccounts();
  try {
    await api(`/api/persona_dashboard/automation/accounts/${encodeURIComponent(account.id)}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ persona_id: cleanPersonaId, replace_existing_binding: true }),
    });
    state.accountPoolAccountId = String(account.id || "");
    await loadSocial({ force: true });
    showMsg("socialMsg", replacedAccount ? "已切换人设绑定账号。" : "账号已绑定到人设。", true);
  } finally {
    state.accountPoolBinding = false;
    renderSocialAccounts();
  }
}

async function unbindAccountPoolAccount(accountId = "", successMessage = "账号已解绑。") {
  const cleanAccountId = String(accountId || "").trim();
  if (!cleanAccountId) return;
  await api(`/api/persona_dashboard/automation/accounts/${encodeURIComponent(cleanAccountId)}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ persona_id: "" }),
  });
  showMsg("socialMsg", successMessage, true);
  await loadSocial();
}

function proxyPoolRows({ includeSystemAvailable = false } = {}) {
  const rows = Array.isArray(state.socialProxies) ? state.socialProxies : [];
  return includeSystemAvailable ? rows : rows.filter((proxy) => proxy?.system_available !== true);
}

function proxyProtocol(proxy = {}) {
  return String(proxy?.protocol || proxy?.proxy_type || "-").trim().toUpperCase();
}

function proxyProtocolLabel(proxy = {}) {
  const clean = proxyProtocol(proxy).toLowerCase();
  return {
    http: "网页代理",
    https: "加密网页代理",
    socks: "通用代理",
    socks5: "通用代理",
    auto: "自动识别",
  }[clean] || "其他协议";
}

function proxyExitIp(proxy = {}) {
  return String(proxy.exit_ip || proxy.last_check_result?.response?.ip || proxy.last_check_result?.ip || "-").trim() || "-";
}

function proxyBoundAccountCount(proxy = {}) {
  const explicit = Number(proxy.bound_account_count ?? proxy.bound_accounts_count ?? proxy.accounts_count);
  if (Number.isFinite(explicit)) return explicit;
  const proxyId = String(proxy.id || "");
  return (state.socialAccounts || []).filter((account) => String(account.proxy_id || "") === proxyId).length;
}

function proxyStatusLabel(value = "") {
  const clean = String(value || "").trim().toLowerCase();
  return { active: "正常", inactive: "停用", disabled: "停用", failed: "异常", checking: "检测中", pending: "待检测" }[clean] || (value || "-");
}

function proxySourceLabel(value = "") {
  const clean = String(value || "").trim().toLowerCase();
  return {
    manual: "手动添加",
    marketplace: "平台选择",
    provider_purchase: "平台选择",
    provider: "平台选择",
    owlproxy: "平台导入",
    self_owned: "自有代理",
  }[clean] || "其他来源";
}

function proxyPurchaseStatusLabel(value = "") {
  return { owned: "自有", leased: "租用" }[String(value || "").trim().toLowerCase()] || "自有";
}

function proxyIpTypeLabel(value = "") {
  const clean = String(value || "static_residential").trim().toLowerCase();
  return {
    static_residential: "静态住宅",
    residential: "住宅代理",
    rotating_residential: "动态住宅",
    datacenter: "数据中心",
    mobile: "移动网络",
  }[clean] || "其他类型";
}

function proxyDisplayName(proxy = {}, endpoint = "") {
  const country = accountProxyCountry(proxy).label;
  const ipType = proxyIpTypeLabel(proxy.ip_type);
  if (country && country !== "待识别") return `${country}${ipType}代理 IP`;
  return endpoint && endpoint !== "-" ? "专属代理 IP" : "代理 IP";
}

function proxyAutomaticValidityLabel(proxy = null) {
  const expiresAt = Number(proxy?.expires_at || 0);
  if (expiresAt > 0) return `有效至 ${formatTime(expiresAt)}`;
  if (!Number(proxy?.last_check_at || 0)) return "待系统检测";
  return String(proxy?.status || "").trim().toLowerCase() === "active" ? "系统检测可用" : "系统检测异常";
}

